@namespace Lumeo
@using System.Globalization
@using Lumeo.SchedulerKernel
@inject Lumeo.Services.Localization.ILumeoLocalizer L

@* First-party agenda/list view (spec §1.1/§1.2/§5.1) — the existing SchedulerView.List value,
   a flat chronological list rather than a grid (spec §0's decision to keep
   the enum member and change only the internal rendering). Not a grid — a flat, day-grouped
   list, which is what it visually already is (spec §5.1). *@
<div class="@($"flex flex-col w-full rounded-md border border-border/60 overflow-hidden {Class}".Trim())" @attributes="AdditionalAttributes">
    <div role="list" aria-label="@L["Scheduler.List"]" class="max-h-[34rem] overflow-y-auto divide-y divide-border/60">
        @if (_days.Count == 0)
        {
            <div class="p-4 text-sm text-muted-foreground">@L["Scheduler.NoEvents"]</div>
        }
        else
        {
            @foreach (var day in _days)
            {
                <div class="p-3">
                    <div class="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-1.5">
                        @day.Date.ToString("D", CultureInfo.CurrentUICulture)
                    </div>
                    @foreach (var row in day.Rows)
                    {
                        <div role="listitem"
                             tabindex="0"
                             class="@($"flex items-center gap-2.5 py-1.5 px-1 rounded-md cursor-pointer hover:bg-accent/60 focus-visible:outline focus-visible:outline-2 focus-visible:outline-ring {ResolveEventClassNames?.Invoke(row.Source)}".TrimEnd())"
                             data-event-id="@row.Source.Id"
                             aria-label="@RowAriaLabel(row)"
                             @onclick="() => OnEventClickAsync(row.Source)"
                             @onkeydown="e => OnRowKeyDownAsync(e, row.Source)">
                            <span class="w-2 h-2 rounded-[calc(var(--radius)*2)] flex-none" style="background-color: @(ResolveEventColor?.Invoke(row.Source) ?? row.Source.Color ?? "var(--color-primary)")" aria-hidden="true"></span>
                            <span class="flex-1 min-w-0 text-sm font-medium truncate">@row.Source.Title</span>
                            <span class="text-xs text-muted-foreground flex-none">@TimeLabel(row)</span>
                        </div>
                    }
                </div>
            }
        }
    </div>
</div>

@code {
    [Parameter] public IEnumerable<SchedulerEvent>? Events { get; set; }

    /// <summary>The window's start (inclusive). Default: today.</summary>
    [Parameter] public DateTime AnchorDate { get; set; } = DateTime.Today;

    /// <summary>How many days from <see cref="AnchorDate"/> to list. Default 30, matching the uploaded demo's "next 30 days" agenda.</summary>
    [Parameter] public int DaysToShow { get; set; } = 30;

    [Parameter] public EventCallback<SchedulerEvent> OnEventClick { get; set; }
    [Parameter] public Func<SchedulerEvent, string?>? ResolveEventColor { get; set; }

    /// <summary>Extra CSS classes per event chip, matching the month and time-grid views' own resolver.</summary>
    [Parameter] public Func<SchedulerEvent, string?>? ResolveEventClassNames { get; set; }

    [Parameter] public string? Class { get; set; }
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private List<AgendaDay> _days = new();

    protected override void OnParametersSet()
    {
        var events = (Events ?? Enumerable.Empty<SchedulerEvent>()).ToList();
        var byId = new Dictionary<string, SchedulerEvent>(StringComparer.Ordinal);
        foreach (var ev in events)
            if (!string.IsNullOrEmpty(ev.Id)) byId[ev.Id] = ev;

        var rangeStart = AnchorDate.Date;
        var rangeEnd = rangeStart.AddDays(Math.Max(1, DaysToShow));
        var instances = SchedulerRecurrenceExpander.ExpandAll(events, rangeStart, rangeEnd)
            .Where(i => byId.ContainsKey(i.EventId))
            .ToList();

        var byDay = new SortedDictionary<DateTime, List<AgendaRow>>();
        foreach (var inst in instances)
        {
            var src = byId[inst.EventId];
            var day = inst.Start.Date < rangeStart ? rangeStart : inst.Start.Date;
            if (!byDay.TryGetValue(day, out var list))
                byDay[day] = list = new List<AgendaRow>();
            list.Add(new AgendaRow(inst, src));
        }

        _days = byDay
            .Select(kvp => new AgendaDay(kvp.Key, kvp.Value.OrderBy(r => r.Source.AllDay ? TimeSpan.Zero : r.Instance.Start.TimeOfDay).ToList()))
            .ToList();
    }

    private static string TimeLabel(AgendaRow row) => row.Source.AllDay
        ? "—"
        : row.Instance.Start.ToString("t", CultureInfo.CurrentUICulture);

    private static string RowAriaLabel(AgendaRow row) => row.Source.AllDay
        ? row.Source.Title
        : $"{row.Source.Title}, {row.Instance.Start:t}";

    private async Task OnEventClickAsync(SchedulerEvent ev)
    {
        if (OnEventClick.HasDelegate) await OnEventClick.InvokeAsync(ev);
    }

    private async Task OnRowKeyDownAsync(KeyboardEventArgs e, SchedulerEvent ev)
    {
        if (e.Key is "Enter" or " ") await OnEventClickAsync(ev);
    }

    private sealed record AgendaDay(DateTime Date, List<AgendaRow> Rows);
    private sealed record AgendaRow(SchedulerEventInstance Instance, SchedulerEvent Source);
}

namespace Lumeo.SchedulerKernel;

/// <summary>
/// Pure, static calendar-field arithmetic backing every Scheduler view's grid boundaries: week
/// starts (for all 7 possible <c>FirstDayOfWeek</c> values), the always-42-cell month grid, and
/// leap-year-safe day counts. Spec §1.1/§7.1.
///
/// TZ/DST safety (spec §2.3): every method below operates purely on calendar-field reads
/// (<c>Year</c>/<c>Month</c>/<c>Day</c>/<c>DayOfWeek</c>) and calendar-field arithmetic
/// (<c>AddDays</c>) — never <see cref="TimeZoneInfo"/>, never <c>ToLocalTime</c>/<c>ToUniversalTime</c>,
/// never elapsed-time (<c>TimeSpan</c>) subtraction across a day boundary. <see cref="DateTime.Kind"/>
/// is therefore irrelevant to every result here, and nothing in this class can be perturbed by a
/// DST transition or by the difference between a CI box (Ubuntu/UTC) and a local dev machine's
/// timezone — see <c>Lumeo.GanttV3.GanttScale</c> (src/Lumeo.Gantt/UI/GanttV3/GanttScale.cs)
/// for the identical argument applied to the Gantt v3 timeline, which this class deliberately
/// mirrors (not a <c>cref</c>: Lumeo.Scheduler doesn't reference Lumeo.Gantt).
/// </summary>
internal static class SchedulerDateMath
{
    /// <summary>
    /// Every month-grid view (FullCalendar's <c>dayGridMonth</c>, and every calendar app that
    /// copies it) renders a fixed 6-week-by-7-day grid regardless of how many weeks the month
    /// itself actually spans, so the grid never visually resizes as the user navigates between
    /// months.
    /// </summary>
    internal const int MonthGridCellCount = 42;

    /// <summary>
    /// The first day of the calendar week containing <paramref name="date"/>, per
    /// <paramref name="firstDayOfWeek"/>. Time-of-day is dropped (the result is always midnight).
    /// Faithful port of <c>Scheduler.razor</c>'s existing <c>StartOfWeek</c> (int-typed
    /// <c>FirstDayOfWeek</c>, 0-6 Sun-Sat) — same formula, <see cref="DayOfWeek"/>-typed here
    /// since the kernel is a fresh implementation, not a byte-for-byte extraction of the
    /// FullCalendar-era component that has since been removed.
    /// </summary>
    internal static DateTime StartOfWeek(DateTime date, DayOfWeek firstDayOfWeek)
    {
        var diff = (7 + (date.DayOfWeek - firstDayOfWeek)) % 7;
        return date.Date.AddDays(-diff);
    }

    /// <summary>
    /// The last day (still midnight, inclusive) of the calendar week containing
    /// <paramref name="date"/>, per <paramref name="firstDayOfWeek"/>. Always exactly 6 days
    /// after <see cref="StartOfWeek"/>.
    /// </summary>
    internal static DateTime EndOfWeek(DateTime date, DayOfWeek firstDayOfWeek) =>
        StartOfWeek(date, firstDayOfWeek).AddDays(6);

    /// <summary>
    /// The first day (midnight) of the calendar month containing <paramref name="date"/>.
    /// </summary>
    internal static DateTime StartOfMonth(DateTime date) => new(date.Year, date.Month, 1);

    /// <summary>
    /// Builds the fixed <see cref="MonthGridCellCount"/>-cell (6 weeks x 7 days) grid a month
    /// view renders, anchored so the grid always fully covers every day of
    /// <paramref name="monthAnchor"/>'s month regardless of which weekday the 1st falls on or how
    /// many weeks the month itself spans (28-31 days can span 4, 5, or 6 calendar weeks
    /// depending on alignment — the grid is always exactly 6 to accommodate the worst case, with
    /// leading/trailing days from the adjacent months filling the remainder). Cell 0 is always
    /// <c>StartOfWeek(StartOfMonth(monthAnchor), firstDayOfWeek)</c>; each subsequent cell is
    /// exactly one day later — a plain <c>AddDays</c> walk, which is "AddMonths-safe" in the
    /// sense that it never itself calls <c>AddMonths</c> (the one call to <c>AddMonths</c>-adjacent
    /// logic — anchoring on day-1 of the month before doing any date walk — is what avoids the
    /// classic "Jan 31 + 1 month" overflow trap; see <see cref="StartOfMonth"/>).
    /// </summary>
    internal static IReadOnlyList<DateTime> BuildMonthGrid(DateTime monthAnchor, DayOfWeek firstDayOfWeek)
    {
        var gridStart = StartOfWeek(StartOfMonth(monthAnchor), firstDayOfWeek);
        var cells = new DateTime[MonthGridCellCount];
        for (var i = 0; i < MonthGridCellCount; i++)
            cells[i] = gridStart.AddDays(i);
        return cells;
    }

    /// <summary>
    /// Number of days in <paramref name="year"/>/<paramref name="month"/>, leap-year-aware.
    /// Thin, explicitly-named wrapper over <see cref="DateTime.DaysInMonth"/> so callers doing
    /// month-grid/recurrence math don't reach for the BCL method ad hoc — kept here as the single
    /// place this kernel's day-count logic lives.
    /// </summary>
    internal static int DaysInMonth(int year, int month) => DateTime.DaysInMonth(year, month);
}

namespace Lumeo;

/// <summary>
/// Which gesture produced a candidate (Start, End) window during a Scheduler drag/resize/create
/// gesture. Mirrors <c>GanttTaskUpdateSource</c>
/// (<c>src/Lumeo.Gantt/UI/GanttV3/GanttV3Types.cs</c>) — the Scheduler's interaction engine
/// deliberately reuses the same shape (spec §3.1/§3.2).
/// </summary>
public enum SchedulerEventUpdateSource
{
    /// <summary>The whole event was dragged to a new day/slot; its duration is unchanged.</summary>
    Move,

    /// <summary>The event's start edge was dragged (Week/Day time-grid only — month has no edge-resize).</summary>
    ResizeStart,

    /// <summary>The event's end edge was dragged (Week/Day time-grid only — month has no edge-resize).</summary>
    ResizeEnd,

    /// <summary>A brand-new event window was drawn by dragging on empty grid background.</summary>
    Create
}

/// <summary>
/// The candidate drop position offered to <c>CanDrop</c> before a move/resize/create commits.
/// Mirrors <c>GanttScheduleDropContext</c>'s shape and role — see
/// <see cref="SchedulerEventUpdateSource"/>'s remarks. Spec §3.2.
/// </summary>
/// <param name="ProposedStart">The candidate Start the gesture would commit if <c>CanDrop</c> returns <c>true</c>.</param>
/// <param name="ProposedEnd">The candidate End the gesture would commit if <c>CanDrop</c> returns <c>true</c>.</param>
/// <param name="Source">Which gesture produced this candidate.</param>
public sealed record SchedulerScheduleDropContext(DateTime ProposedStart, DateTime ProposedEnd, SchedulerEventUpdateSource Source);

/// <summary>
/// A candidate override for a drop's committed Start/End/AllDay, offered by <c>CanDrop</c> when
/// it accepts a drop but wants to snap it to different values than the raw proposal (e.g. round
/// to the nearest business-hour boundary instead of merely refusing an out-of-hours drop).
/// Mirrors ReUI's <c>onEventUpdate</c> return shape (<c>{ start?, end?, allDay? }</c>) — see
/// <see cref="SchedulerDropResult"/>. Any member left <c>null</c> keeps the corresponding
/// <see cref="SchedulerScheduleDropContext"/> proposal (or, for <c>AllDay</c>, the source
/// event's current value) unchanged.
/// </summary>
/// <param name="Start">Overrides <see cref="SchedulerScheduleDropContext.ProposedStart"/> when set.</param>
/// <param name="End">Overrides <see cref="SchedulerScheduleDropContext.ProposedEnd"/> when set.</param>
/// <param name="AllDay">Overrides the committed event's <c>AllDay</c> flag when set.</param>
public sealed record SchedulerDropAdjustment(DateTime? Start = null, DateTime? End = null, bool? AllDay = null);

/// <summary>
/// The three-way verdict a <c>CanDrop</c> predicate returns for a candidate drop: reject it
/// outright, accept it exactly as proposed, or accept it WITH an <see cref="SchedulerDropAdjustment"/>
/// that snaps the eventually-committed Start/End/AllDay to different values than what was
/// proposed. Widens the wave-1 binary allow/reject contract (spec §3.2) while <c>CanDrop</c> is
/// still <c>PublicAPI.Unshipped</c> — done now, deliberately, before it ships and this would
/// become a breaking change (mirrors why Gantt v3's own <c>OnTaskUpdate</c> is scheduled for a
/// PublicAPI-promotion release specifically because ITS binary contract already shipped).
///
/// An implicit <c>bool</c> conversion keeps the common "just allow/reject it" case exactly as
/// simple as returning a raw <c>bool</c> was before this type existed — e.g.
/// <c>CanDrop="(ev, ctx) => true"</c> still compiles unchanged against the widened
/// <c>Func&lt;SchedulerEvent, SchedulerScheduleDropContext, SchedulerDropResult&gt;</c> parameter
/// type.
/// </summary>
public readonly struct SchedulerDropResult : IEquatable<SchedulerDropResult>
{
    /// <summary>Whether the drop is permitted at all (with or without an <see cref="Adjustment"/>).</summary>
    public bool Accepted { get; }

    /// <summary>
    /// When set, the Start/End/AllDay a consumer wants committed instead of the raw proposal.
    /// Always <c>null</c> when <see cref="Accepted"/> is <c>false</c> (a rejected drop has
    /// nothing to adjust).
    /// </summary>
    public SchedulerDropAdjustment? Adjustment { get; }

    private SchedulerDropResult(bool accepted, SchedulerDropAdjustment? adjustment)
    {
        Accepted = accepted;
        Adjustment = accepted ? adjustment : null;
    }

    /// <summary>Rejects the drop outright.</summary>
    public static readonly SchedulerDropResult Reject = new(false, null);

    /// <summary>Accepts the drop exactly as proposed — no adjustment.</summary>
    public static readonly SchedulerDropResult Accept = new(true, null);

    /// <summary>Accepts the drop, but commits <paramref name="adjustment"/>'s values instead of the raw proposal.</summary>
    public static SchedulerDropResult AcceptWith(SchedulerDropAdjustment adjustment) => new(true, adjustment);

    /// <summary>Keeps <c>CanDrop="(ev, ctx) => true"</c>/<c>false</c> lambdas source-compatible with the widened delegate type.</summary>
    public static implicit operator SchedulerDropResult(bool accepted) => accepted ? Accept : Reject;

    public bool Equals(SchedulerDropResult other) => Accepted == other.Accepted && Equals(Adjustment, other.Adjustment);
    public override bool Equals(object? obj) => obj is SchedulerDropResult other && Equals(other);
    public override int GetHashCode() => HashCode.Combine(Accepted, Adjustment);
    public static bool operator ==(SchedulerDropResult left, SchedulerDropResult right) => left.Equals(right);
    public static bool operator !=(SchedulerDropResult left, SchedulerDropResult right) => !left.Equals(right);
}

namespace Lumeo.SchedulerKernel;

/// <summary>
/// Lane assignment for a single calendar month-row (7 consecutive day cells): multi-day and
/// all-day events keep a stable, visually-continuous lane across the days they span, instead of
/// the uploaded demo's own per-cell independent top-3 truncation (spec §1.4, which explicitly
/// calls out the demo's shortcut as not acceptable for the first-party component — a multi-day
/// event's pill must not land in a different vertical slot on consecutive days).
/// </summary>
internal static class SchedulerMonthLayout
{
    /// <summary>Default max lanes shown per day cell before the "+N more" affordance kicks in — matches the demo's <c>slice(0,3)</c>.</summary>
    internal const int DefaultMaxVisibleLanes = 3;

    /// <summary>
    /// Assigns each event in <paramref name="events"/> the lowest lane index that doesn't
    /// conflict, on any day cell the event occupies within the row, with an event already
    /// assigned that lane. <paramref name="events"/> should already be clamped to the 7-day row
    /// starting at <paramref name="weekStart"/> (spec §1.4's own stated input contract) — this
    /// method does not itself clip a span that extends outside the row, beyond a defensive clamp
    /// (see <see cref="DayCellSpan"/>).
    /// </summary>
    /// <remarks>
    /// Algorithm (spec §1.4):
    /// <list type="number">
    /// <item>Sort: all-day/multi-day events first (row-start-day ascending, then span length
    /// descending — "wider things first", matching FullCalendar's own ordering so a long bar
    /// doesn't get bumped by an unstably-sorted short single-day item); single-day timed events
    /// last (start time ascending).</item>
    /// <item>Greedily assign each event, in that order, the lowest lane index not already
    /// occupied — by any other event's lane assignment — on ANY day cell the event itself spans.
    /// The "lane" axis is a single index shared across the whole row (not a per-day pixel
    /// offset), which is what keeps a continuous multi-day bar's per-day pieces lined up.</item>
    /// </list>
    /// A day-cell span, not raw <c>DateTime</c> overlap, is what "conflicts" is computed over —
    /// see <see cref="DayCellSpan"/> for exactly how a (StartDate, EndDate, AllDay) triple maps
    /// onto the row's 7 day-cell indices.
    /// </remarks>
    internal static IReadOnlyDictionary<string, int> PackRow(
        DateTime weekStart,
        IReadOnlyList<(string Id, DateTime StartDate, DateTime EndDate, bool AllDay)> events)
    {
        var lanes = new Dictionary<string, int>();
        if (events.Count == 0) return lanes;

        var multi = new List<(string Id, (int Start, int EndExclusive) Span, DateTime StartDate)>();
        var single = new List<(string Id, (int Start, int EndExclusive) Span, DateTime StartDate)>();

        foreach (var e in events)
        {
            var span = DayCellSpan(weekStart, e.StartDate, e.EndDate, e.AllDay);
            var isMultiOrAllDay = e.AllDay || (span.EndExclusive - span.Start) > 1;
            (isMultiOrAllDay ? multi : single).Add((e.Id, span, e.StartDate));
        }

        multi.Sort((a, b) =>
        {
            var byStart = a.Span.Start.CompareTo(b.Span.Start);
            if (byStart != 0) return byStart;
            var aLen = a.Span.EndExclusive - a.Span.Start;
            var bLen = b.Span.EndExclusive - b.Span.Start;
            return bLen.CompareTo(aLen); // span length descending
        });
        single.Sort((a, b) => a.StartDate.CompareTo(b.StartDate)); // start time ascending

        // laneOccupancy[lane] = set of day-cell indices already claimed by some event in that lane.
        var laneOccupancy = new List<HashSet<int>>();

        void Assign(string id, (int Start, int EndExclusive) span)
        {
            var lane = 0;
            while (true)
            {
                if (lane >= laneOccupancy.Count) laneOccupancy.Add(new HashSet<int>());

                var conflict = false;
                for (var d = span.Start; d < span.EndExclusive; d++)
                {
                    if (!laneOccupancy[lane].Contains(d)) continue;
                    conflict = true;
                    break;
                }
                if (!conflict) break;
                lane++;
            }

            for (var d = span.Start; d < span.EndExclusive; d++)
                laneOccupancy[lane].Add(d);
            lanes[id] = lane;
        }

        foreach (var item in multi) Assign(item.Id, item.Span);
        foreach (var item in single) Assign(item.Id, item.Span);

        return lanes;
    }

    /// <summary>
    /// Per-day-cell hidden count: <c>max(0, occupiedLanes(day) - maxVisibleLanes)</c> (spec
    /// §1.4) — how many events on that specific day cell fall past the visible-lane budget, for
    /// the "+N more" affordance. Reads lane occupancy directly, so a day crowded only because
    /// several SHORT single-day events land on it doesn't inflate the hidden count on other,
    /// less-crowded days in the same row.
    /// </summary>
    internal static IReadOnlyDictionary<DateTime, int> HiddenCounts(
        DateTime weekStart,
        IReadOnlyDictionary<string, int> lanes,
        IReadOnlyList<(string Id, DateTime StartDate, DateTime EndDate, bool AllDay)> events,
        int maxVisibleLanes = DefaultMaxVisibleLanes)
    {
        var perDayLanes = new HashSet<int>[7];
        for (var i = 0; i < 7; i++) perDayLanes[i] = new HashSet<int>();

        foreach (var e in events)
        {
            if (!lanes.TryGetValue(e.Id, out var lane)) continue;
            var span = DayCellSpan(weekStart, e.StartDate, e.EndDate, e.AllDay);
            for (var d = span.Start; d < span.EndExclusive; d++)
                perDayLanes[d].Add(lane);
        }

        var result = new Dictionary<DateTime, int>();
        for (var i = 0; i < 7; i++)
        {
            var day = weekStart.Date.AddDays(i);
            result[day] = Math.Max(0, perDayLanes[i].Count - maxVisibleLanes);
        }
        return result;
    }

    /// <summary>
    /// Maps an event's (StartDate, EndDate, AllDay) onto the row's 7 day-cell indices [0, 7)
    /// relative to <paramref name="weekStart"/>, as a half-open [Start, EndExclusive) range.
    /// </summary>
    /// <remarks>
    /// <list type="bullet">
    /// <item>A single-day timed event (<c>allDay == false</c>, and EndDate falls on the same
    /// calendar date as StartDate) always occupies exactly the one day-cell it starts on —
    /// <c>[startIndex, startIndex + 1)</c>.</item>
    /// <item>An all-day or genuinely multi-day event follows <see cref="SchedulerEvent.End"/>'s
    /// exclusive-end convention: a midnight <c>EndDate</c> means the span does NOT touch that
    /// calendar day (e.g. Mon 22:00 -&gt; Wed 00:00 touches Mon and Tue only, not Wed); a
    /// non-midnight <c>EndDate</c> means it partially touches that day too.</item>
    /// <item>Both bounds are clamped to <c>[0, 7]</c> — the caller's event list is expected to
    /// already be clamped to the row (spec §1.4's stated input contract), so this clamp is a
    /// defensive fallback, not the primary clipping mechanism.</item>
    /// </list>
    /// </remarks>
    private static (int Start, int EndExclusive) DayCellSpan(DateTime weekStart, DateTime startDate, DateTime endDate, bool allDay)
    {
        var rowStart = weekStart.Date;
        var startIndex = (int)(startDate.Date - rowStart).TotalDays;

        int endIndexExclusive;
        if (!allDay && endDate.Date == startDate.Date)
        {
            endIndexExclusive = startIndex + 1;
        }
        else
        {
            var lastTouchedDate = endDate.TimeOfDay == TimeSpan.Zero ? endDate.Date.AddDays(-1) : endDate.Date;
            var lastTouchedIndex = (int)(lastTouchedDate - rowStart).TotalDays;
            endIndexExclusive = Math.Max(startIndex + 1, lastTouchedIndex + 1);
        }

        var clampedStart = Math.Clamp(startIndex, 0, 7);
        var clampedEnd = Math.Clamp(endIndexExclusive, clampedStart + 1, 7);
        return (clampedStart, clampedEnd);
    }
}

@namespace Lumeo
@using System.Globalization
@using Lumeo.SchedulerKernel
@using Lumeo.Services.Localization
@implements IAsyncDisposable
@inject Lumeo.Services.IComponentInteropService Interop
@inject Lumeo.Services.Localization.ILumeoLocalizer L

@* First-party month-grid view (spec §1.1/§1.2/§1.4/§5). Consumes SchedulerDateMath.BuildMonthGrid
   for the always-42-cell grid, SchedulerRecurrenceExpander for occurrence expansion, and
   SchedulerMonthLayout for continuous multi-day lane assignment. Internal building block —
   Scheduler.razor (the only component with public parameters, spec §1.2) is the eventual host;
   this component is usable and independently testable on its own in the meantime. *@
<div class="@($"flex flex-col w-full rounded-md border border-border/60 overflow-hidden {Class}".Trim())" @attributes="AdditionalAttributes">
    @* Live region for pointer-gesture outcomes (ReUI parity). Rendered
       unconditionally and EMPTY at mount: assistive tech must be observing the
       node before the text lands, so a region created at announce time is
       frequently missed. Same sr-only/polite/atomic shape Carousel.razor
       already uses. *@
    <span class="sr-only" aria-live="polite" aria-atomic="true"
          data-testid="scheduler-live-region" data-announce-epoch="@_announcementEpoch">@AnnouncementText</span>
    <div class="@GridColsClass border-b border-border/60 bg-card">
        @if (ShowWeekNumbers)
        {
            @* Corner cell above the week-number column. aria-hidden + presentation:
               it labels nothing, and letting it into the header row would make
               screen readers announce an empty column header for every row. *@
            <span class="px-1 py-1.5 text-center text-[11px] font-medium text-muted-foreground">@L["Scheduler.WeekNumberAbbrev"]</span>
        }
        @for (var i = 0; i < _weekdayHeaders.Length; i++)
        {
            var dow = (DayOfWeek)(((int)FirstDayOfWeek + i) % 7);
            if (HideWeekends && dow is DayOfWeek.Saturday or DayOfWeek.Sunday) { continue; }
            <span class="px-2 py-1.5 text-right text-[11px] font-medium text-muted-foreground">@_weekdayHeaders[i]</span>
        }
    </div>
    <div class="@GridColsClass" role="grid" aria-label="@L["Scheduler.Month"]" @ref="_hostRef">
        @for (var row = 0; row < 6; row++)
        {
            <div role="row" class="contents">
                @if (ShowWeekNumbers)
                {
                    @* role="rowheader" (not gridcell): it labels the row rather
                       than holding a focusable day, so keyboard grid navigation
                       — which walks _cellRefs by index — is untouched. *@
                    @* aria-label, not a bare number (Codex review of this PR, P2):
                       the "Wk"/"KW" column header lives in the header strip
                       ABOVE the grid, so it is not a columnheader of this grid
                       and carries no ARIA relationship to these cells. A screen
                       reader walking the grid would otherwise read an
                       unexplained "35". Labelling each row header makes it
                       self-describing regardless of what the header strip does. *@
                    <div role="rowheader"
                         class="flex items-start justify-center border-b border-e border-border/60 bg-muted/30 px-1 py-1 text-[11px] tabular-nums text-muted-foreground"
                         aria-label="@L["Scheduler.WeekNumberLabel", WeekNumberForRow(row)]"
                         data-week-number="@WeekNumberForRow(row)">@WeekNumberForRow(row)</div>
                }
                @for (var col = 0; col < 7; col++)
                {
                    var cellIndex = row * 7 + col;
                    var cell = _cellModels[cellIndex];
                    if (IsHiddenColumn(cell.Date)) { continue; }
                    var isFocused = cellIndex == _focusedIndex;
                    <div role="gridcell"
                         @ref="_cellRefs[cellIndex]"
                         tabindex="@(isFocused ? "0" : "-1")"
                         data-cell-date="@cell.Date.ToString("yyyy-MM-dd")"
                         data-cell-index="@cellIndex"
                         data-off="@(cell.IsOffDay ? "true" : null)"
                         aria-label="@CellAriaLabel(cell)"
                         aria-selected="@(SelectedDate.HasValue && SelectedDate.Value.Date == cell.Date ? "true" : "false")"
                         class="@CellClasses(cell)"
                         @onclick="() => OnCellClickAsync(cellIndex)"
                         @ondblclick="() => OnCellDoubleClickAsync(cell.Date)"
                         @onkeydown="e => OnGridKeyDownAsync(e, cellIndex)">
                        <span class="@DayNumberClasses(cell)">@cell.Date.Day</span>
                        @foreach (var slot in cell.Lanes)
                        {
                            if (slot is null)
                            {
                                <div class="h-[19px]" aria-hidden="true"></div>
                            }
                            else
                            {
                                var key = InstanceKey(slot.Instance);
                                <Tooltip ShowDelay="400" Class="w-full">
                                    <TooltipTrigger AsChild="true">
                                        <ChildContentSlot Context="pillSlot">
                                            <button type="button"
                                                    @ref="_pillRefs[key]"
                                                    class="@PillClasses(slot)"
                                                    data-event-instance="@key"
                                                    data-event-id="@slot.Instance.EventId"
                                                    style="@PillStyle(slot)"
                                                    tabindex="-1"
                                                    aria-label="@PillAriaLabel(slot)"
                                                    @attributes="pillSlot.Attributes"
                                                    @onclick:stopPropagation="true"
                                                    @onclick="() => OnEventClickAsync(slot.Source)"
                                                    @onkeydown="e => OnPillKeyDownAsync(e, slot.Source, cellIndex)">
                                                @if (slot.ShowTitle)
                                                {
                                                    @slot.Source.Title
                                                }
                                                else
                                                {
                                                    <span aria-hidden="true">&nbsp;</span>
                                                }
                                            </button>
                                        </ChildContentSlot>
                                    </TooltipTrigger>
                                    <TooltipContent>@TooltipLabel(slot.Source, slot.Instance)</TooltipContent>
                                </Tooltip>
                            }
                        }
                        @if (cell.HiddenCount > 0)
                        {
                            @* Self-contained popover (not the Popover/PopoverTrigger primitives — both the
                               AsChild and non-AsChild compositions were found, via this task's own Playwright
                               run (not just bUnit, which doesn't exercise real DOM event dispatch), to not
                               reliably open when nested this deep inside a 42-times-repeated grid structure;
                               PopoverTrigger AsChild in particular is exercised nowhere else in this codebase.
                               Mirrors DataGridColumnVisibility.razor's own proven manual click-outside popover
                               pattern — same RegisterClickOutside/UnregisterClickOutside lifecycle, just scoped
                               to this cell instead of a column id.) *@
                            <div class="relative">
                                <button type="button"
                                        class="px-0.5 text-left text-[11px] text-muted-foreground hover:text-foreground hover:underline cursor-pointer"
                                        data-testid="month-more-events"
                                        @onclick="() => ToggleMorePopoverAsync(cellIndex)"
                                        @onclick:stopPropagation="true">
                                    @L[LumeoPlurals.PluralKey(cell.HiddenCount, "Scheduler.MoreEvents", CultureInfo.CurrentUICulture), cell.HiddenCount]
                                </button>
                                @if (_openMoreCellIndex == cellIndex)
                                {
                                    <div id="@MorePopoverId(cellIndex)"
                                         role="dialog"
                                         aria-label="@L[LumeoPlurals.PluralKey(cell.HiddenCount, "Scheduler.MoreEvents", CultureInfo.CurrentUICulture), cell.HiddenCount]"
                                         class="absolute left-0 top-full mt-1 z-50 w-56 rounded-md border border-border/60 bg-popover text-popover-foreground shadow-lg p-2"
                                         data-testid="month-more-popover"
                                         @onclick:stopPropagation="true"
                                         @onkeydown="e => OnMorePopoverKeyDown(e, cellIndex)">
                                        <div class="flex flex-col gap-0.5">
                                            @foreach (var hidden in cell.HiddenInstances)
                                            {
                                                <button type="button"
                                                        class="flex items-center gap-1.5 w-full text-left text-xs px-1.5 py-1 rounded hover:bg-accent/60"
                                                        data-event-id="@hidden.Instance.EventId"
                                                        @onclick="() => OnMoreEventClickAsync(hidden.Source)">
                                                    <span class="w-1.5 h-1.5 rounded-[calc(var(--radius)*2)] flex-none" style="background-color: @(ResolveEventColor?.Invoke(hidden.Source) ?? hidden.Source.Color ?? "var(--color-primary)")" aria-hidden="true"></span>
                                                    <span class="flex-1 min-w-0 truncate">@hidden.Source.Title</span>
                                                </button>
                                            }
                                        </div>
                                    </div>
                                }
                            </div>
                        }
                    </div>
                }
            </div>
        }
    </div>
</div>

@code {
    /// <summary>The calendar's events (expanded per occurrence internally via <c>SchedulerRecurrenceExpander</c>).</summary>
    [Parameter] public IEnumerable<SchedulerEvent>? Events { get; set; }

    /// <summary>The month this grid renders. Only Year/Month are read.</summary>
    [Parameter] public DateTime AnchorDate { get; set; } = DateTime.Today;

    /// <summary>First day of the week for grid layout. Default Monday.</summary>
    [Parameter] public DayOfWeek FirstDayOfWeek { get; set; } = DayOfWeek.Monday;

    /// <summary>
    /// Renders an extra leading column with each row's ISO-8601 week number
    /// (ReUI parity — its event calendar exposes a "week numbers" display
    /// toggle). Default <c>false</c>: when off, the grid keeps its exact
    /// previous 7-column markup, so this cannot shift any existing layout.
    /// <para>
    /// The number is always the ISO-8601 week (<see cref="System.Globalization.ISOWeek"/>),
    /// computed from each row's own THURSDAY. Thursday is ISO's defining day —
    /// the week a Thursday falls in IS its ISO week — and every 7-day row
    /// contains exactly one Thursday no matter which
    /// <see cref="FirstDayOfWeek"/> the grid starts on. That makes the label
    /// independent of the grid's start day, which a naive "first cell of the
    /// row" reading is not: in a Sunday-start grid the leading Sunday belongs
    /// to the PREVIOUS ISO week, so reading the row's first cell would label
    /// most rows one week too low.
    /// </para>
    /// </summary>
    [Parameter] public bool ShowWeekNumbers { get; set; }

    /// <summary>
    /// Hides the Saturday and Sunday columns (ReUI parity — its event calendar
    /// exposes a weekend-hiding toggle). Default <c>false</c>: with it off the
    /// grid renders its exact previous seven-column markup.
    /// <para>
    /// The 42-cell model is untouched; only rendering and keyboard navigation
    /// skip the hidden columns. That matters because arrow navigation moves by
    /// raw cell index (+/-1, +/-7) — walking that index across a hidden column
    /// would put focus on a cell that is not in the DOM, so navigation runs over
    /// the VISIBLE cells instead (see <c>VisibleCellIndices</c>).
    /// </para>
    /// </summary>
    [Parameter] public bool HideWeekends { get; set; }

    /// <summary>Max visible pill lanes per day before "+N more". Default <see cref="SchedulerMonthLayout.DefaultMaxVisibleLanes"/>.</summary>
    [Parameter] public int MaxVisibleLanes { get; set; } = SchedulerMonthLayout.DefaultMaxVisibleLanes;

    /// <summary>The currently selected date (keyboard focus anchor / agenda-strip driver). Controlled via <see cref="SelectedDateChanged"/>.</summary>
    [Parameter] public DateTime? SelectedDate { get; set; }
    [Parameter] public EventCallback<DateTime> SelectedDateChanged { get; set; }

    /// <summary>Raised when an event chip is clicked or activated (Enter/Space).</summary>
    [Parameter] public EventCallback<SchedulerEvent> OnEventClick { get; set; }

    /// <summary>Raised when the user selects a date (double-click, or Enter/Space on an empty cell).</summary>
    [Parameter] public EventCallback<SchedulerDateRange> OnDateSelect { get; set; }

    /// <summary>Bubbles a PageUp (previous month) keyboard request up to the toolbar's own Prev.</summary>
    [Parameter] public EventCallback OnRequestPrev { get; set; }

    /// <summary>Bubbles a PageDown (next month) keyboard request up to the toolbar's own Next.</summary>
    [Parameter] public EventCallback OnRequestNext { get; set; }

    /// <summary>Resolves the effective CSS color for an event chip. Falls back to <c>var(--color-primary)</c>.</summary>
    [Parameter] public Func<SchedulerEvent, string?>? ResolveEventColor { get; set; }

    /// <summary>Resolves extra CSS class names appended to an event chip.</summary>
    [Parameter] public Func<SchedulerEvent, string?>? ResolveEventClassNames { get; set; }

    /// <summary>Allows events to be dragged to another day. Month has no edge-resize (spec §3.4). Default true.</summary>
    [Parameter] public bool Editable { get; set; } = true;

    /// <summary>
    /// Fail-closed validation predicate for a day-move drop (spec §3.2), widened to a three-way
    /// reject/accept/accept-with-adjustment contract (mirrors ReUI's <c>onEventUpdate</c>) — see
    /// <see cref="SchedulerDropResult"/>. <c>null</c> (default) means no consumer opted in — JS
    /// is told via <c>hasCanDrop: false</c> so zero <see cref="ValidateDrop"/> interop calls
    /// happen per drag.
    /// </summary>
    [Parameter] public Func<SchedulerEvent, SchedulerScheduleDropContext, SchedulerDropResult>? CanDrop { get; set; }

    /// <summary>Allows drag-across-cells date-range selection on empty grid background (spec §3.4's Month row — previously entirely absent). Default true.</summary>
    [Parameter] public bool Selectable { get; set; } = true;

    /// <summary>
    /// Shades non-business days (spec's business-hours regression fix — the first-party views
    /// previously had no equivalent at all, unlike the time-grid views' <c>BusinessHours</c>
    /// toggle). Month has no hour axis, so this shades whole day cells outside
    /// <see cref="BusinessDays"/>. Default false (opt-in, matches the wrapper's own default).
    /// </summary>
    [Parameter] public bool BusinessHours { get; set; }

    /// <summary>Which days of the week count as business days when <see cref="BusinessHours"/> is true. Default Mon–Fri, unchanged from the wrapper this engine replaced.</summary>
    [Parameter] public IReadOnlyList<DayOfWeek>? BusinessDays { get; set; }

    /// <summary>Raised after a day-move drag commits (post-<see cref="CanDrop"/> validation, ghost already removed).</summary>
    [Parameter] public EventCallback<SchedulerEvent> OnEventChange { get; set; }

    [Parameter] public string? Class { get; set; }
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private DateTime[] _cells = Array.Empty<DateTime>();
    private MonthCellModel[] _cellModels = new MonthCellModel[42];
    private readonly ElementReference[] _cellRefs = new ElementReference[42];
    private readonly Dictionary<string, ElementReference> _pillRefs = new(StringComparer.Ordinal);
    private int _focusedIndex;
    private string[] _weekdayHeaders = Array.Empty<string>();

    // Written as literal class strings, never interpolated: the Tailwind v4
    // build only emits utilities it can SEE in source, so a computed
    // $"grid-cols-{n}" would produce a class with no rule behind it — the
    // "class in the DOM without a rule" trap this repo has hit before.
    /// <summary>Whether <paramref name="date"/>'s column is hidden by <see cref="HideWeekends"/>.</summary>
    private bool IsHiddenColumn(DateTime date) =>
        HideWeekends && date.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday;

    /// <summary>
    /// The 0-41 indices actually rendered, in reading order. Arrow navigation
    /// walks POSITIONS in this list rather than raw indices, so a hidden column
    /// is stepped over instead of focused.
    /// </summary>
    private List<int> VisibleCellIndices
    {
        get
        {
            var list = new List<int>(42);
            for (var i = 0; i < 42; i++)
                if (!IsHiddenColumn(_cells[i].Date)) list.Add(i);
            return list;
        }
    }

    /// <summary>Rendered day columns per row — 5 when weekends are hidden.</summary>
    private int VisibleColumns => HideWeekends ? 5 : 7;

    // Every combination written out literally: Tailwind v4 only emits utilities
    // it can see in source, so an interpolated class would land in the DOM with
    // no rule behind it — a trap this repo has already been bitten by.
    private string GridColsClass => (ShowWeekNumbers, HideWeekends) switch
    {
        (true, true) => "grid grid-cols-[2.5rem_repeat(5,minmax(0,1fr))]",
        (true, false) => "grid grid-cols-[2.5rem_repeat(7,minmax(0,1fr))]",
        (false, true) => "grid grid-cols-5",
        (false, false) => "grid grid-cols-7",
    };

    /// <summary>
    /// The ISO-8601 week number for display row <paramref name="row"/>, read off
    /// that row's own Thursday — see <see cref="ShowWeekNumbers"/> for why
    /// Thursday rather than the row's first cell.
    /// </summary>
    private int WeekNumberForRow(int row)
    {
        for (var col = 0; col < 7; col++)
        {
            var date = _cells[row * 7 + col].Date;
            if (date.DayOfWeek == DayOfWeek.Thursday) return ISOWeek.GetWeekOfYear(date);
        }
        // Unreachable for a 7-day row, but a silent 0 would be a worse failure
        // than falling back to the row's first date.
        return ISOWeek.GetWeekOfYear(_cells[row * 7].Date);
    }
    private ElementReference _hostRef;
    private DotNetObjectReference<SchedulerMonthView>? _selfRef;
    private bool _dragRegistered;
    private int _lastDragOptionsHash;
    private int? _openMoreCellIndex;
    private bool _moreClickOutsideRegistered;

    protected override void OnParametersSet()
    {
        _cells = SchedulerDateMath.BuildMonthGrid(AnchorDate, FirstDayOfWeek).ToArray();
        BuildWeekdayHeaders();
        BuildCellModels();

        // Keep the roving-tabindex anchor in bounds when the grid changes from under it.
        if (_focusedIndex < 0 || _focusedIndex >= 42)
            _focusedIndex = 0;

        if (IsHiddenColumn(_cells[_focusedIndex].Date))
        {
            var firstVisible = VisibleCellIndices;
            _focusedIndex = firstVisible.Count > 0 ? firstVisible[0] : 0;
        }

        // ...and on a cell that is actually RENDERED (Codex review of this PR,
        // P1). A bounds check alone is not enough once HideWeekends exists: a
        // Sunday-first grid anchors at index 0, which is hidden, and toggling
        // the option on while a weekend cell holds focus strands it the same
        // way. Either case leaves every cell at tabindex="-1", so the grid
        // drops out of the tab order entirely and arrow keys do nothing.

    }

    private void BuildWeekdayHeaders()
    {
        var culture = CultureInfo.CurrentUICulture;
        var headers = new string[7];
        for (var i = 0; i < 7; i++)
        {
            var dow = (DayOfWeek)(((int)FirstDayOfWeek + i) % 7);
            headers[i] = culture.DateTimeFormat.AbbreviatedDayNames[(int)dow];
        }
        _weekdayHeaders = headers;
    }

    private void BuildCellModels()
    {
        _pillRefs.Clear();
        if (_cells.Length == 0) { _cellModels = new MonthCellModel[42]; return; }

        var events = (Events ?? Enumerable.Empty<SchedulerEvent>()).ToList();
        var byId = new Dictionary<string, SchedulerEvent>(StringComparer.Ordinal);
        foreach (var ev in events)
            if (!string.IsNullOrEmpty(ev.Id)) byId[ev.Id] = ev;

        var rangeStart = _cells[0];
        var rangeEnd = _cells[^1].AddDays(1);
        var allInstances = SchedulerRecurrenceExpander.ExpandAll(events, rangeStart, rangeEnd);

        var models = new MonthCellModel[42];
        for (var row = 0; row < 6; row++)
        {
            var weekStart = _cells[row * 7];
            var weekEnd = weekStart.AddDays(7);

            var rowInstances = allInstances
                .Where(i => i.Start < weekEnd && i.End > weekStart && byId.ContainsKey(i.EventId))
                .ToList();

            var packInput = rowInstances
                .Select(i => (Id: InstanceKey(i), StartDate: i.Start, EndDate: i.End, AllDay: byId[i.EventId].AllDay))
                .ToList();

            var lanes = SchedulerMonthLayout.PackRow(weekStart, packInput);
            var hidden = SchedulerMonthLayout.HiddenCounts(weekStart, lanes, packInput, MaxVisibleLanes);

            var maxLane = lanes.Count == 0 ? -1 : lanes.Values.Max();
            var visibleLaneCount = Math.Max(0, Math.Min(MaxVisibleLanes, maxLane + 1));

            for (var col = 0; col < 7; col++)
            {
                var date = weekStart.AddDays(col);
                var touching = rowInstances.Where(i => TouchesDay(i.Start, i.End, byId[i.EventId].AllDay, date)).ToList();

                var slots = new PillSlot?[visibleLaneCount];
                for (var lane = 0; lane < visibleLaneCount; lane++)
                {
                    var found = touching.FirstOrDefault(i => lanes.TryGetValue(InstanceKey(i), out var l) && l == lane);
                    if (found.EventId is null) { slots[lane] = null; continue; }

                    var src = byId[found.EventId];
                    var contL = date.Date > found.Start.Date;
                    var contR = date.Date < LastTouchedDate(found.End, src.AllDay, found.Start);
                    slots[lane] = new PillSlot(found, src, contL, contR, !contL);
                }

                // The events beyond the visible-lane budget — what the "+N more" popover
                // lists (spec §1's "the data is there; the affordance is not" finding: the
                // kernel's HiddenCounts already computed the COUNT, but nothing surfaced
                // WHICH instances were hidden until now).
                var hiddenInstances = touching
                    .Where(i => lanes.TryGetValue(InstanceKey(i), out var l) && l >= visibleLaneCount)
                    .OrderBy(i => byId[i.EventId].AllDay ? TimeSpan.MinValue : i.Start.TimeOfDay)
                    .Select(i => new PillSlot(i, byId[i.EventId], false, false, true))
                    .ToList();

                models[row * 7 + col] = new MonthCellModel(
                    date,
                    date.Month == AnchorDate.Month && date.Year == AnchorDate.Year,
                    date.Date == DateTime.Today,
                    slots,
                    hidden.TryGetValue(date, out var h) ? h : 0,
                    touching.Count,
                    hiddenInstances,
                    IsOffDay(date));
            }
        }

        _cellModels = models;
        PromoteTitlesOntoVisibleCells();
    }

    /// <summary>
    /// Moves a run's title onto its first RENDERED segment when
    /// <see cref="HideWeekends"/> hides the segment that would normally carry it
    /// (Codex review of this PR, P2).
    /// <para>
    /// <c>ShowTitle</c> is set to <c>!contL</c>, i.e. only the run's first day
    /// shows the name. For an event starting on a Saturday and continuing into
    /// the working week, hiding that Saturday removes the ONLY titled segment,
    /// so every weekday chip renders a non-breaking space and the event appears
    /// as an unlabelled bar. No-op when weekends are shown.
    /// </para>
    /// </summary>
    private void PromoteTitlesOntoVisibleCells()
    {
        if (!HideWeekends) return;

        // One pass in reading order; the first visible segment of each instance
        // wins, so a run that begins on a visible day is left untouched.
        var titled = new HashSet<string>(StringComparer.Ordinal);
        foreach (var cell in _cellModels)
        {
            if (cell is null || IsHiddenColumn(cell.Date)) continue;
            for (var lane = 0; lane < cell.Lanes.Count; lane++)
            {
                if (cell.Lanes[lane] is not { } slot) continue;
                var key = InstanceKey(slot.Instance);
                if (!titled.Add(key)) continue;
                if (!slot.ShowTitle) ((IList<PillSlot?>)cell.Lanes)[lane] = slot with { ShowTitle = true };
            }
        }
    }

    /// <summary>Whether <paramref name="date"/> is a non-business day per <see cref="BusinessDays"/> (default Mon–Fri) when <see cref="BusinessHours"/> is enabled.</summary>
    private bool IsOffDay(DateTime date)
    {
        if (!BusinessHours) return false;
        var businessDays = BusinessDays ?? DefaultBusinessDays;
        return !businessDays.Contains(date.DayOfWeek);
    }

    private static readonly DayOfWeek[] DefaultBusinessDays =
        { DayOfWeek.Monday, DayOfWeek.Tuesday, DayOfWeek.Wednesday, DayOfWeek.Thursday, DayOfWeek.Friday };

    private static DateTime LastTouchedDate(DateTime end, bool allDay, DateTime start)
    {
        if (!allDay && end.Date == start.Date) return start.Date;
        var last = end.TimeOfDay == TimeSpan.Zero ? end.Date.AddDays(-1) : end.Date;
        return last < start.Date ? start.Date : last;
    }

    private static bool TouchesDay(DateTime start, DateTime end, bool allDay, DateTime day)
    {
        if (!allDay && end.Date == start.Date) return day.Date == start.Date;
        var last = LastTouchedDate(end, allDay, start);
        return day.Date >= start.Date && day.Date <= last;
    }

    private static string InstanceKey(SchedulerEventInstance i) => $"{i.EventId}|{i.Start:O}";

    private string CellClasses(MonthCellModel cell)
    {
        var classes = "relative flex flex-col gap-0.5 min-h-[92px] p-1 border-b border-r border-border/60 cursor-pointer transition-colors hover:bg-accent/50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-ring focus-visible:-outline-offset-2";
        if (!cell.InCurrentMonth) classes += " bg-muted/30 text-muted-foreground";
        if (SelectedDate.HasValue && SelectedDate.Value.Date == cell.Date) classes += " outline outline-2 outline-ring -outline-offset-2";
        return classes;
    }

    /// <summary>Hover-tooltip label for an event chip: title + time range (spec §3.4's promised "title, time range, resource" — resource omitted here since neither view resolves a resource DISPLAY NAME, only the raw <see cref="SchedulerEvent.ResourceId"/>; falls back to that id, labelled, when present).</summary>
    private static string TooltipLabel(SchedulerEvent ev, SchedulerEventInstance inst)
    {
        var time = ev.AllDay ? null : $"{inst.Start:t}–{inst.End:t}";
        var parts = new List<string> { ev.Title };
        if (time is not null) parts.Add(time);
        if (!string.IsNullOrEmpty(ev.ResourceId)) parts.Add(ev.ResourceId);
        return string.Join(" · ", parts);
    }

    private static string DayNumberClasses(MonthCellModel cell)
    {
        var classes = "self-end w-6 h-6 rounded-[calc(var(--radius)*4)] flex items-center justify-center text-xs font-medium";
        if (cell.IsToday) classes += " bg-primary text-primary-foreground font-semibold";
        return classes;
    }

    private string PillClasses(PillSlot slot)
    {
        var classes = "block w-full text-left text-[11px] leading-tight font-medium px-1.5 py-0.5 rounded truncate cursor-pointer select-none border-0";
        if (slot.ContL) classes += " rounded-l-none";
        if (slot.ContR) classes += " rounded-r-none";
        var extra = ResolveEventClassNames?.Invoke(slot.Source);
        if (!string.IsNullOrEmpty(extra)) classes += " " + extra;
        return classes;
    }

    /// <summary>
    /// A day cell pads its content by <c>p-1</c> (4px) and carries a 1px right border, so two
    /// segments of the SAME run sat 9px apart and a multi-day event read as a row of separate
    /// bars — the continuation days looking like empty stubs, since only the first segment
    /// carries the title. A continued segment therefore bleeds out to the cell's border box on
    /// the side it continues, which closes the gap exactly and makes the run render as one
    /// bar. The rounded corners were already dropped on those sides for this reason; only the
    /// spacing was missing.
    /// </summary>
    private const double CellPadPx = 4;
    private const double CellBorderPx = 1;

    private string PillStyle(PillSlot slot)
    {
        var color = ResolveEventColor?.Invoke(slot.Source) ?? slot.Source.Color ?? "var(--color-primary)";
        var style = $"background-color: color-mix(in oklab, {color} 18%, transparent); color: color-mix(in oklab, {color} 38%, var(--lumeo-event-fg-anchor));";

        // Left bleed is only the padding — the border belongs to the PREVIOUS cell and is
        // already covered by that cell's own segment bleeding right.
        var left = slot.ContL ? CellPadPx : 0;
        var right = slot.ContR ? CellPadPx + CellBorderPx : 0;
        if (left == 0 && right == 0) return style;

        // The pill is w-full, i.e. width:100%. A negative margin alone only SHIFTS that box,
        // it does not widen it, so the first attempt closed 4px of the 9px gap and left a
        // visible seam. The width has to grow by the same amount it bleeds.
        var inv = CultureInfo.InvariantCulture;
        if (left > 0) style += $" margin-left: -{left.ToString(inv)}px;";
        if (right > 0) style += $" margin-right: -{right.ToString(inv)}px;";
        style += $" width: calc(100% + {(left + right).ToString(inv)}px);";
        return style;
    }

    private string CellAriaLabel(MonthCellModel cell)
    {
        var dateLabel = cell.Date.ToString("D", CultureInfo.CurrentUICulture);
        var countLabel = L[LumeoPlurals.PluralKey(cell.TotalCount, "Scheduler.EventCount", CultureInfo.CurrentUICulture), cell.TotalCount];
        return $"{dateLabel}, {countLabel}";
    }

    private static string PillAriaLabel(PillSlot slot) => slot.Source.AllDay
        ? slot.Source.Title
        : $"{slot.Source.Title}, {slot.Instance.Start:t}";

    // ── Interaction ──────────────────────────────────────────────────────

    private async Task OnCellClickAsync(int index)
    {
        _focusedIndex = index;
        var date = _cellModels[index].Date;
        if (SelectedDateChanged.HasDelegate) await SelectedDateChanged.InvokeAsync(date);
    }

    private async Task OnCellDoubleClickAsync(DateTime date)
    {
        if (OnDateSelect.HasDelegate)
            await OnDateSelect.InvokeAsync(new SchedulerDateRange(date, date.AddDays(1), true));
    }

    private async Task OnEventClickAsync(SchedulerEvent ev)
    {
        if (OnEventClick.HasDelegate) await OnEventClick.InvokeAsync(ev);
    }

    private async Task OnPillKeyDownAsync(KeyboardEventArgs e, SchedulerEvent ev, int cellIndex)
    {
        if (e.Key is "Enter" or " ")
        {
            await OnEventClickAsync(ev);
        }
        else if (e.Key == "Escape")
        {
            _focusedIndex = cellIndex;
            await FocusCellAsync(cellIndex);
        }
    }

    /// <summary>
    /// Roving-tabindex 2-D grid navigation (spec §5.2's Month column). Arrow keys move one
    /// day/week; Home/End snap to the row's first/last day; PageUp/PageDown bubble up as a
    /// month-navigation request (same effect as the toolbar's own Prev/Next); Enter/Space
    /// opens <see cref="OnDateSelect"/> for an empty cell, or moves focus to the cell's first
    /// event chip when one exists (mirrors a native listbox's "hand off focus to content").
    /// </summary>
    private async Task OnGridKeyDownAsync(KeyboardEventArgs e, int cellIndex)
    {
        _focusedIndex = cellIndex;

        // Navigation walks POSITIONS in the visible list, not raw 0-41 indices
        // (HideWeekends): stepping the raw index would move focus onto a cell
        // that is not rendered. With weekends shown the visible list is the
        // identity 0..41 and the arithmetic below is exactly what it was —
        // +/-1 for a day, +/-VisibleColumns for a week, and Home/End snapping to
        // the row's own first/last VISIBLE column.
        var visible = VisibleCellIndices;
        var pos = visible.IndexOf(cellIndex);
        if (pos < 0) return; // focused cell is hidden — nothing to move from

        var cols = VisibleColumns;
        var rowStart = pos - (pos % cols);
        int nextPos;
        switch (e.Key)
        {
            case "ArrowRight": nextPos = Math.Min(visible.Count - 1, pos + 1); break;
            case "ArrowLeft": nextPos = Math.Max(0, pos - 1); break;
            // Clamped by STAYING PUT, not by pinning to the first/last position
            // (Codex review of this PR, P2): clamping a flattened position
            // changes its column, so ArrowUp in the top row used to slide from
            // Friday to Monday instead of doing nothing.
            case "ArrowDown": nextPos = pos + cols < visible.Count ? pos + cols : pos; break;
            case "ArrowUp": nextPos = pos - cols >= 0 ? pos - cols : pos; break;
            case "Home": nextPos = rowStart; break;
            case "End": nextPos = Math.Min(visible.Count - 1, rowStart + cols - 1); break;
            case "PageUp":
                if (OnRequestPrev.HasDelegate) await OnRequestPrev.InvokeAsync();
                return;
            case "PageDown":
                if (OnRequestNext.HasDelegate) await OnRequestNext.InvokeAsync();
                return;
            case "Enter":
            case " ":
                await ActivateFocusedCellAsync(cellIndex);
                return;
            default:
                return;
        }

        var next = visible[nextPos];
        if (next != cellIndex)
        {
            _focusedIndex = next;
            await FocusCellAsync(next);
        }
    }

    private async Task ActivateFocusedCellAsync(int cellIndex)
    {
        var cell = _cellModels[cellIndex];
        var first = cell.Lanes.FirstOrDefault(s => s is not null);
        if (first is not null)
        {
            var key = InstanceKey(first.Instance);
            if (_pillRefs.TryGetValue(key, out var pillRef))
            {
                try { await pillRef.FocusAsync(); }
                catch (Microsoft.JSInterop.JSDisconnectedException) { }
            }
        }
        else if (OnDateSelect.HasDelegate)
        {
            await OnDateSelect.InvokeAsync(new SchedulerDateRange(cell.Date, cell.Date.AddDays(1), true));
        }
    }

    private async Task FocusCellAsync(int index)
    {
        try { await _cellRefs[index].FocusAsync(); }
        catch (Microsoft.JSInterop.JSDisconnectedException) { }
    }

    // ── Drag (whole-day move only — month has no edge-resize, spec §3.4) ──────
    // Ghost-only + fail-closed: see SchedulerTimeGridView's identical remarks and
    // scheduler-views.js's own header comment — the same two invariants apply here.

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        await SyncMorePopoverClickOutsideAsync();

        var hash = HashCode.Combine(Editable, CanDrop is not null, Selectable);
        if (_dragRegistered && hash == _lastDragOptionsHash) return;
        _lastDragOptionsHash = hash;
        _selfRef ??= DotNetObjectReference.Create(this);
        try
        {
            var options = new Dictionary<string, object?> { ["editable"] = Editable, ["hasCanDrop"] = CanDrop is not null, ["selectable"] = Selectable && OnDateSelect.HasDelegate };
            await Interop.SchedulerViewsRegisterMonthDragAsync(_hostRef, _selfRef, options);
            _dragRegistered = true;
        }
        catch (Microsoft.JSInterop.JSDisconnectedException) { }
    }

    // ── "+N more" self-contained popover (spec's dead-text regression fix, §1) ─────
    // Not the Popover/PopoverTrigger primitives — see the markup's own remarks
    // for why. (Written without angle brackets on purpose: the registry generator
    // scans this file for component tags, and a tag named in a line comment reads
    // as a real dependency.) Mirrors
    // DataGridColumnVisibility.razor's proven manual click-outside popover lifecycle.

    private async Task ToggleMorePopoverAsync(int cellIndex)
    {
        if (_openMoreCellIndex == cellIndex)
        {
            await CloseMorePopoverAsync();
        }
        else
        {
            if (_openMoreCellIndex is not null) await CloseMorePopoverAsync();
            _openMoreCellIndex = cellIndex;
        }
    }

    private async Task CloseMorePopoverAsync()
    {
        var wasOpen = _openMoreCellIndex;
        _openMoreCellIndex = null;
        if (_moreClickOutsideRegistered && wasOpen is { } idx)
        {
            _moreClickOutsideRegistered = false;
            try { await Interop.UnregisterClickOutside(MorePopoverId(idx)); }
            catch (Microsoft.JSInterop.JSDisconnectedException) { }
        }
    }

    private async Task SyncMorePopoverClickOutsideAsync()
    {
        if (_openMoreCellIndex is { } idx && !_moreClickOutsideRegistered)
        {
            try
            {
                await Interop.RegisterClickOutside(MorePopoverId(idx), null, async () =>
                {
                    _moreClickOutsideRegistered = false;
                    _openMoreCellIndex = null;
                    await InvokeAsync(StateHasChanged);
                });
                _moreClickOutsideRegistered = true;
            }
            catch (Microsoft.JSInterop.JSDisconnectedException) { }
        }
    }

    private async Task OnMoreEventClickAsync(SchedulerEvent ev)
    {
        await CloseMorePopoverAsync();
        await OnEventClickAsync(ev);
    }

    private void OnMorePopoverKeyDown(KeyboardEventArgs e, int cellIndex)
    {
        if (e.Key == "Escape" && _openMoreCellIndex == cellIndex)
            _ = CloseMorePopoverAsync();
    }

    /// <summary>
    /// Per-INSTANCE, not per-cell. The id also keys the global click-outside registry, so two
    /// month views on one page — which side-by-side calendar panes create — produced the same id
    /// for the same day: opening an overflow popover in the second pane re-registered the first
    /// one's id against the second callback, so the wrong popover closed and the other could not
    /// be dismissed at all (Codex review of PR #426).
    /// </summary>
    private string MorePopoverId(int cellIndex) => $"scheduler-month-more-{_instanceId}-{cellIndex}";

    private readonly string _instanceId = Guid.NewGuid().ToString("n")[..8];

    /// <summary>
    /// [JSInvokable] fail-closed CanDrop check for a candidate day-move. Returns
    /// <c>false</c> for any input JS shouldn't have been able to produce (unknown
    /// event id, unparsable date) rather than treating an unrecognized shape as
    /// permission. Only the <see cref="SchedulerDropResult.Accepted"/> half of the
    /// three-way verdict crosses the JS boundary here — the visual ghost only needs
    /// accept/reject; <see cref="SchedulerDropResult.Adjustment"/> is applied once,
    /// authoritatively, in <see cref="CommitDrag"/>.
    /// </summary>
    [JSInvokable]
    public bool ValidateDrop(string eventId, string dateIso)
    {
        if (CanDrop is null) return true;
        var ev = FindEvent(eventId);
        if (ev is null) return false;
        if (!DateTime.TryParse(dateIso, CultureInfo.InvariantCulture, DateTimeStyles.None, out var date)) return false;
        var newStart = date.Date + ev.Start.TimeOfDay;
        var newEnd = newStart + (ev.End - ev.Start);
        return CanDrop(ev, new SchedulerScheduleDropContext(newStart, newEnd, SchedulerEventUpdateSource.Move)).Accepted;
    }

    [JSInvokable]
    public async Task CommitDrag(string eventId, string dateIso)
    {
        var ev = FindEvent(eventId);
        if (ev is null) return;
        if (!DateTime.TryParse(dateIso, CultureInfo.InvariantCulture, DateTimeStyles.None, out var date)) return;
        var newStart = date.Date + ev.Start.TimeOfDay;
        if (newStart == ev.Start) return;
        var newEnd = newStart + (ev.End - ev.Start);
        var newAllDay = ev.AllDay;

        // Re-validate at commit time (not just trust the JS-side ValidateDrop that gated
        // getting here) — this is the ONLY place a SchedulerDropResult.Adjustment can be
        // applied, since ValidateDrop only surfaces the Accepted half over the JS boundary.
        // Also closes a staleness gap: a CanDrop that changes between the last ValidateDrop
        // poll and the actual drop no longer has to be trusted from a cached JS-side verdict.
        if (CanDrop is not null)
        {
            var ctx = new SchedulerScheduleDropContext(newStart, newEnd, SchedulerEventUpdateSource.Move);
            var result = CanDrop(ev, ctx);
            // The ORDINARY rejection never reaches this method — the JS awaits
            // ValidateDrop and returns before calling CommitDrag (see
            // NotifyDropRejected). What DOES reach it is the staleness case this
            // second check exists for: CanDrop said yes during the drag and says
            // no now. JS has already passed its own rejection branch, so this is
            // the only place that outcome can be announced (Codex review of this
            // PR, P2) — without it the drop silently does nothing.
            if (!result.Accepted)
            {
                Announce(L["Scheduler.Announce.MoveRejected", ev.Title]);
                return;
            }
            if (result.Adjustment is { } adjustment)
            {
                newStart = adjustment.Start ?? newStart;
                newEnd = adjustment.End ?? newEnd;
                newAllDay = adjustment.AllDay ?? newAllDay;
            }
        }

        var updated = ev with { Start = newStart, End = newEnd, AllDay = newAllDay };
        // Announced from the COMMITTED values, after any CanDrop adjustment has
        // been applied — an adjusted drop lands somewhere other than where the
        // pointer was released, so announcing the proposed date would tell the
        // user something that did not happen.
        //
        // Gated on OnEventChange (Codex review of this PR, P2): with no handler
        // the drag is ghost-only — the real chip snaps back and Events is
        // untouched — so announcing a move would describe something the user
        // can neither see nor keep.
        // A CanDrop adjustment can snap the event back to exactly where it
        // started; the earlier no-op check ran against the PROPOSED values,
        // not these (Codex review of this PR, P2). Announcing a move for an
        // unchanged event states something that did not happen.
        if (updated.Start == ev.Start && updated.End == ev.End && updated.AllDay == ev.AllDay) return;
        if (!OnEventChange.HasDelegate) return;
        // Announced AFTER the handler completes (Codex review of this PR,
        // P2): an async OnEventChange that faults — persistence refusing
        // the update, say — leaves the JS caller catching a failed
        // CommitDrag while the user has already been told it moved.
        await OnEventChange.InvokeAsync(updated);
        Announce(L["Scheduler.Announce.EventMoved", ev.Title, FormatAnnounceDate(updated.Start)]);
    }

    // ── Live-region announcements (ReUI parity) ──────────────────────────────
    // reui.io's event calendar lists "live-region announcements for gestures";
    // these views had no aria-live region at all, so a pointer drag produced no
    // screen-reader signal whatsoever. Mirrors Carousel.razor's existing house
    // pattern (sr-only span, polite, atomic) rather than inventing a second one.

    /// <summary>
    /// [JSInvokable] the drag engine calls when it refuses to commit a drop
    /// (Codex review of this PR, P1). The ordinary rejection path lives entirely
    /// in JS — it awaits <see cref="ValidateDrop"/> and returns without ever
    /// calling <see cref="CommitDrag"/> — so this is the ONLY seam where a
    /// refused drag can be announced.
    /// </summary>
    [JSInvokable]
    public void NotifyDropRejected(string eventId)
    {
        var ev = FindEvent(eventId);
        Announce(L["Scheduler.Announce.MoveRejected", ev?.Title ?? string.Empty]);
    }

    private string? _announcement;
    private int _announcementEpoch;

    /// <summary>
    /// The live region's rendered text. A zero-width space is appended on every
    /// other announcement so that repeating an identical message still changes
    /// the text node.
    /// <para>
    /// Two earlier attempts at this were both wrong, and the second was worse
    /// than the first. Clearing and re-setting inside one method does nothing —
    /// Blazor coalesces the two renders. Keying the element on an epoch does
    /// mutate the DOM, but by REMOVING the observed region and inserting a new,
    /// already-populated one; screen readers that only announce changes inside
    /// an already-observed live region can then miss every announcement (Codex
    /// review of this PR, P2). The node must stay mounted, so only its text
    /// changes — and U+200B is inaudible.
    /// </para>
    /// </summary>
    private string? AnnouncementText =>
        _announcement is null ? null : _announcementEpoch % 2 == 0 ? _announcement : _announcement + ZeroWidthSpace;

    /// <summary>
    /// U+200B. Named rather than written literally: an invisible character in
    /// source is unreadable and easy to delete by accident.
    /// </summary>
    private const string ZeroWidthSpace = "​";

    private void Announce(string message)
    {
        _announcementEpoch++;
        _announcement = message;
        StateHasChanged();
    }

    /// <summary>
    /// Long-date format for announcements — deliberately NOT the terse cell
    /// label: read aloud out of context, "14" says nothing, "14 March 2026" does.
    /// </summary>
    private static string FormatAnnounceDate(DateTime value) =>
        value.ToString("D", CultureInfo.CurrentUICulture);

    /// <summary>
    /// [JSInvokable] commits a drag-across-cells date-range selection (spec §3.4's Month row —
    /// previously entirely absent, only <see cref="OnCellDoubleClickAsync"/>'s single-day
    /// no-drag selection existed). Not CanDrop-gated: this creates a brand-new selection, there
    /// is no existing <see cref="SchedulerEvent"/> for a drop predicate to validate against
    /// (mirrors <see cref="SchedulerTimeGridView.CommitCreate"/>'s identical reasoning).
    /// </summary>
    [JSInvokable]
    public async Task CommitDateRangeSelect(string startDateIso, string endDateIso)
    {
        if (!DateTime.TryParse(startDateIso, CultureInfo.InvariantCulture, DateTimeStyles.None, out var start)) return;
        if (!DateTime.TryParse(endDateIso, CultureInfo.InvariantCulture, DateTimeStyles.None, out var end)) return;
        if (start > end) (start, end) = (end, start);
        if (OnDateSelect.HasDelegate) await OnDateSelect.InvokeAsync(new SchedulerDateRange(start.Date, end.Date.AddDays(1), true));
    }

    private SchedulerEvent? FindEvent(string id) =>
        (Events ?? Enumerable.Empty<SchedulerEvent>()).FirstOrDefault(e => e.Id == id);

    public async ValueTask DisposeAsync()
    {
        if (_dragRegistered)
        {
            try { await Interop.SchedulerViewsUnregisterMonthDragAsync(_hostRef); }
            catch (Microsoft.JSInterop.JSDisconnectedException) { }
        }
        if (_moreClickOutsideRegistered && _openMoreCellIndex is { } idx)
        {
            try { await Interop.UnregisterClickOutside(MorePopoverId(idx)); }
            catch (Microsoft.JSInterop.JSDisconnectedException) { }
        }
        _selfRef?.Dispose();
    }

    private sealed record MonthCellModel(DateTime Date, bool InCurrentMonth, bool IsToday, IReadOnlyList<PillSlot?> Lanes, int HiddenCount, int TotalCount, IReadOnlyList<PillSlot> HiddenInstances, bool IsOffDay);

    private sealed record PillSlot(SchedulerEventInstance Instance, SchedulerEvent Source, bool ContL, bool ContR, bool ShowTitle);
}

using System.Globalization;
using System.Linq;

// Deliberately alongside SchedulerRecurrenceRule.cs in UI/Scheduler rather than
// in Kernel/ (Codex review of this PR, P2): RegistryGen builds a component's
// vendored `files` list from its own UI/<Name>/ folder, so nothing under Kernel/
// is shipped by `lumeo add scheduler` — this parser would have been public API
// that source-vendored consumers simply did not receive. It also belongs next to
// the type it produces.
namespace Lumeo;

/// <summary>
/// Parses an RFC 5545 <c>RRULE</c> string into a <see cref="SchedulerRecurrenceRule"/>.
///
/// <para>
/// ReUI parity — its event calendar accepts raw RRULE strings, which is what anyone holding
/// iCalendar/Google/Outlook data actually has. Lumeo modelled recurrence only as a structured
/// record, so such a consumer had to hand-write a parser before they could pass their own data
/// in at all.
/// </para>
///
/// <para>
/// <b>Scope is deliberately the same subset the expander already implements</b>
/// (the recurrence expander): <c>FREQ</c> of DAILY/WEEKLY/MONTHLY, plus
/// <c>INTERVAL</c>, <c>COUNT</c>, <c>UNTIL</c> and <c>BYDAY</c> (with RFC 5545 ordinals such as
/// <c>2MO</c> / <c>-1FR</c>). Anything outside that — <c>FREQ=YEARLY</c>, <c>BYMONTHDAY</c>,
/// <c>BYSETPOS</c>, <c>WKST</c>, … — is <b>rejected</b>, never silently dropped. Accepting a
/// rule and then quietly ignoring half of it is the worst possible outcome here: the caller
/// gets a series that looks plausible and is wrong, on their real calendar data. A rejected
/// parse is a bug report; a silently narrowed rule is a support ticket six months later.
/// </para>
///
/// <para>
/// <b>Where the parsed rule actually takes effect.</b> Assign it to
/// <c>SchedulerEvent.Recurrence</c>. Every view expands it through the recurrence expander,
/// whether reached directly (<c>SchedulerMonthView</c>, <c>SchedulerTimeGridView</c>,
/// <c>SchedulerAgendaView</c>, <c>SchedulerResourceView</c>) or through
/// <c>&lt;Scheduler&gt;</c>, which renders those same views. This used to hold for the
/// first-party views only: the
/// wrapper serialized events to a JS calendar that branched on the legacy <c>DaysOfWeek</c>
/// pair alone, so a <c>Recurrence</c> rule reached its change-detection hash and stopped there
/// (Codex review, P1). Removing the wrapper closed that gap rather than the parser changing.
/// </para>
///
/// <para>
/// <b>Known divergence, deliberately NOT rejected — a bare <c>FREQ=MONTHLY</c> anchored on
/// day 29, 30 or 31.</b> RFC 5545 SKIPS months that lack that day (a 31st-anchored rule has no
/// February occurrence); the expander CLAMPS to the month's last day instead, which is a
/// documented wave-1 choice of its own. So importing <c>FREQ=MONTHLY;COUNT=3</c> for a
/// <c>DTSTART</c> of 2026-01-31 yields a February date the source calendar would not have.
/// </para>
/// <para>
/// Rejecting every bare monthly rule would close that hole, and is the wrong trade: the
/// overwhelming majority are anchored on days 1-28, where the two readings are identical, and
/// refusing them would make importing ordinary monthly events impossible. The divergence is
/// also not visible from the rule text at all — it depends on <c>DTSTART</c>, which this parser
/// never sees — so the check belongs where both are known, not here. Callers importing
/// month-end anchors should either supply an explicit <c>BYDAY</c> ordinal (<c>-1FR</c> and
/// friends resolve exactly) or filter the expanded occurrences themselves.
/// </para>
/// </summary>
public static class SchedulerRRuleParser
{
    /// <summary>
    /// Largest accepted <c>INTERVAL</c> — see the INTERVAL branch for why a
    /// bound is needed at all.
    /// </summary>
    /// <summary>
    /// Mirror of the expander's own occurrence cap, duplicated as a literal on
    /// purpose (Codex review of this PR, P2): referencing
    /// <c>SchedulerRecurrenceExpander.OccurrenceCap</c> would compile here but
    /// NOT in a source-vendored install, because nothing under <c>Kernel/</c> is
    /// shipped by <c>lumeo add scheduler</c> — the very gap moving this file
    /// closed, reintroduced as a type reference. Kept in sync by the
    /// round-trip tests, which expand parser output through the real expander.
    /// </summary>
    private const int ExpanderOccurrenceCap = 500;

    /// <summary>
    /// Largest accepted <c>INTERVAL</c>, per frequency (Codex review of this PR,
    /// P2). A single flat cap was not enough: the expander takes up to
    /// <see cref="ExpanderOccurrenceCap"/> + 1 steps and advances BEFORE it can
    /// notice COUNT is satisfied, so the safe bound depends on how far one step
    /// moves. 501 steps must stay inside DateTime's range from any realistic
    /// start — roughly 2.9M days, i.e. ~5 700 daily / ~820 weekly / ~190 monthly
    /// steps — and these are the next round number below each.
    /// </summary>
    private static int MaxIntervalFor(SchedulerRecurrenceFrequency freq) => freq switch
    {
        SchedulerRecurrenceFrequency.Daily => 5_000,
        SchedulerRecurrenceFrequency.Weekly => 800,
        SchedulerRecurrenceFrequency.Monthly => 12,
        _ => 1,
    };

    /// <summary>
    /// Attempts to parse <paramref name="rrule"/>. Returns <c>false</c> (with
    /// <paramref name="rule"/> set to <c>null</c>) for anything malformed or outside the
    /// supported subset — see the type's own remarks for why unsupported parts are a failure
    /// rather than a silent omission.
    /// </summary>
    /// <param name="rrule">
    /// The rule text, with or without the <c>RRULE:</c> prefix an iCalendar line carries
    /// (<c>"RRULE:FREQ=WEEKLY;BYDAY=MO,WE"</c> and <c>"FREQ=WEEKLY;BYDAY=MO,WE"</c> both parse).
    /// Part names and values are treated case-insensitively, matching RFC 5545, which defines
    /// them as case-insensitive tokens.
    /// </param>
    /// <param name="rule">The parsed rule, or <c>null</c> when this returns <c>false</c>.</param>
    public static bool TryParse(string? rrule, out SchedulerRecurrenceRule? rule)
    {
        rule = null;
        if (string.IsNullOrWhiteSpace(rrule)) return false;

        var text = rrule!.Trim();
        if (text.StartsWith("RRULE:", StringComparison.OrdinalIgnoreCase))
            text = text["RRULE:".Length..];

        SchedulerRecurrenceFrequency? freq = null;
        var interval = 1;
        var intervalSeen = false;
        int? count = null;
        DateTime? until = null;
        List<SchedulerByDayRule>? byDay = null;

        // NOT RemoveEmptyEntries (Codex review of this PR, P2): that silently
        // swallowed ";FREQ=DAILY", "FREQ=DAILY;" and "FREQ=DAILY;;COUNT=2",
        // which is exactly the truncated/mis-assembled calendar line this
        // parser's strictness exists to surface.
        var parts = text.Split(';');
        if (parts.Length == 0) return false;
        foreach (var part in parts)
        {
            var eq = part.IndexOf('=');
            if (eq <= 0) return false; // "FREQ" with no value, or a stray "=WEEKLY"

            var name = part[..eq].Trim();
            var value = part[(eq + 1)..].Trim();
            if (value.Length == 0) return false;

            switch (name.ToUpperInvariant())
            {
                case "FREQ":
                    if (freq is not null) return false; // duplicate part — ambiguous, not a merge
                    freq = value.ToUpperInvariant() switch
                    {
                        "DAILY" => SchedulerRecurrenceFrequency.Daily,
                        "WEEKLY" => SchedulerRecurrenceFrequency.Weekly,
                        "MONTHLY" => SchedulerRecurrenceFrequency.Monthly,
                        _ => null, // YEARLY / HOURLY / … — outside the expander's own scope
                    };
                    if (freq is null) return false;
                    break;

                case "INTERVAL":
                    // Duplicate-rejected like every other part (Codex review of
                    // this PR, P2): letting a second INTERVAL overwrite the
                    // first silently picks a winner from an ambiguous rule.
                    if (intervalSeen) return false;
                    intervalSeen = true;
                    if (!int.TryParse(value, NumberStyles.None, CultureInfo.InvariantCulture, out interval) || interval < 1)
                        return false; // RFC 5545: INTERVAL is a positive integer
                    // The upper bound depends on FREQ, which may appear LATER in
                    // the string, so it is enforced after the loop.
                    break;

                case "COUNT":
                    if (count is not null || until is not null) return false; // COUNT and UNTIL are mutually exclusive
                    if (!int.TryParse(value, NumberStyles.None, CultureInfo.InvariantCulture, out var parsedCount) || parsedCount < 1)
                        return false;
                    // The expander stops after OccurrenceCap generated candidates
                    // regardless of COUNT (Codex review of this PR, P2), so a
                    // larger COUNT silently yields fewer occurrences than asked
                    // for — the same accept-then-quietly-do-something-else
                    // failure this parser exists to refuse.
                    if (parsedCount > ExpanderOccurrenceCap) return false;
                    count = parsedCount;
                    break;

                case "UNTIL":
                    if (until is not null || count is not null) return false;
                    if (!TryParseUntil(value, out var parsedUntil)) return false;
                    until = parsedUntil;
                    break;

                case "BYDAY":
                    if (byDay is not null) return false;
                    if (!TryParseByDay(value, out byDay)) return false;
                    break;

                default:
                    // Deliberately strict — see the type's own remarks.
                    return false;
            }
        }

        if (freq is null) return false; // FREQ is the one REQUIRED part (RFC 5545 §3.3.10)
        if (interval > MaxIntervalFor(freq.Value)) return false;
        if (!ByDayIsHonouredBy(freq.Value, byDay)) return false;

        rule = new SchedulerRecurrenceRule(freq.Value, interval, count, until, byDay);
        return true;
    }

    /// <summary>
    /// Parses <paramref name="rrule"/>, or throws <see cref="FormatException"/> when it is
    /// malformed or outside the supported subset. Prefer <see cref="TryParse"/> when the input
    /// comes from user data.
    /// </summary>
    public static SchedulerRecurrenceRule Parse(string? rrule) =>
        TryParse(rrule, out var rule) && rule is not null
            ? rule
            : throw new FormatException(
                $"Not a supported RRULE: '{rrule}'. Supported: FREQ=DAILY|WEEKLY|MONTHLY with " +
                "optional INTERVAL, COUNT or UNTIL, and BYDAY (ordinals allowed, e.g. 2MO or -1FR).");

    /// <summary>
    /// Whether the expander will actually HONOUR <paramref name="byDay"/> under
    /// <paramref name="freq"/> (Codex review of this PR, P1). Rejecting mismatches is the whole
    /// point of this parser's strictness — each case below otherwise parses cleanly and then
    /// produces a series that silently means something else:
    /// <list type="bullet">
    ///   <item><c>FREQ=DAILY;BYDAY=MO</c> — daily expansion ignores ByDay entirely, so this
    ///   would expand to EVERY day rather than Mondays.</item>
    ///   <item><c>FREQ=WEEKLY;BYDAY=2MO</c> — weekly expansion ignores the ordinal, so
    ///   "second Monday" would expand to every Monday.</item>
    ///   <item><c>FREQ=MONTHLY;BYDAY=MO</c> — RFC 5545 reads an unqualified monthly term as
    ///   EVERY Monday in the month; this rule model treats a missing ordinal as the FIRST one
    ///   (see <see cref="SchedulerByDayRule.Ordinal"/>, which records that divergence as
    ///   out of scope), so accepting it would quietly drop every occurrence but the first.</item>
    /// </list>
    /// </summary>
    private static bool ByDayIsHonouredBy(SchedulerRecurrenceFrequency freq, List<SchedulerByDayRule>? byDay)
    {
        if (byDay is null) return true; // no BYDAY at all is always fine

        return freq switch
        {
            SchedulerRecurrenceFrequency.Daily => false,
            SchedulerRecurrenceFrequency.Weekly => byDay.All(d => d.Ordinal is null),
            SchedulerRecurrenceFrequency.Monthly => byDay.All(d => d.Ordinal is not null),
            _ => false,
        };
    }

    /// <summary>
    /// RFC 5545 writes UNTIL as a DATE (<c>yyyyMMdd</c>) or a DATE-TIME (<c>yyyyMMddTHHmmss</c>,
    /// optionally UTC-suffixed with <c>Z</c>).
    /// <para>
    /// A DATE-TIME is accepted ONLY when its time-of-day is <c>23:59:59</c> — the end-of-day
    /// idiom real calendars emit. Correction to an earlier claim of mine that the distinction was
    /// "moot" (Codex review of this PR, P2): it is not.
    /// <see cref="SchedulerRecurrenceRule.Until"/> is bounded by DATE, so a cutoff of
    /// <c>20260812T080000</c> would still include that day's 09:00 occurrence — later than the
    /// caller asked for. End-of-day is the one time-of-day where date-only bounding is exactly
    /// equivalent; every other value is rejected rather than silently widened to the full day.
    /// </para>
    /// <para>
    /// A <c>Z</c> (UTC) suffix is <b>rejected</b>. The kernel is wall-clock throughout and the
    /// parser never sees the target time zone, so a UTC cutoff cannot be honoured without
    /// silently shifting the series end by up to a day. Importers should convert to local
    /// wall-clock before parsing.
    /// </para>
    /// </summary>
    private static bool TryParseUntil(string value, out DateTime result)
    {
        // Upper-cased first: the 'T' separator is matched as a literal, so a
        // producer that lowercases the whole value ("20261231t235959") must
        // still parse — the contract promises case-insensitive values.
        var upper = value.ToUpperInvariant();

        // A Z (UTC) suffix is REJECTED outright, reversing an earlier decision
        // of mine to accept it unconverted (Codex review of this PR, P2).
        //
        // Z means UTC and this kernel is wall-clock throughout — it never
        // converts. For a consumer in UTC+10, "20260812T235959Z" is
        // 2026-08-13 09:59:59 local, so a daily 09:00 occurrence on the 13th
        // falls inside the cutoff; parsing the date part alone yields the 12th
        // and drops it. Accepting the value would move someone's series end by a
        // day, silently, and the parser cannot do better — it never sees the
        // target time zone.
        //
        // The cost is real: "...T235959Z" is the form most calendars emit, so
        // importers must convert to local wall-clock first. Worse ergonomics,
        // better data — the trade this parser makes everywhere else.
        if (upper.EndsWith("Z", StringComparison.Ordinal)) { result = default; return false; }
        var text = upper;

        if (DateTime.TryParseExact(text, "yyyyMMdd", CultureInfo.InvariantCulture, DateTimeStyles.None, out result))
            return true;

        if (!DateTime.TryParseExact(text, "yyyyMMdd'T'HHmmss", CultureInfo.InvariantCulture, DateTimeStyles.None, out result))
            return false;

        // See the remarks above: only the end-of-day idiom survives date-only bounding intact.
        if (result.TimeOfDay == new TimeSpan(23, 59, 59)) return true;

        result = default;
        return false;
    }

    private static bool TryParseByDay(string value, out List<SchedulerByDayRule>? terms)
    {
        terms = null;
        var parsed = new List<SchedulerByDayRule>();

        // Empty entries preserved for the same reason the outer split preserves
        // them (Codex review of this PR, P2): "BYDAY=MO,", ",MO" and "MO,,WE"
        // are malformed, and dropping the blanks made them parse.
        foreach (var raw in value.Split(','))
        {
            var term = raw.Trim();
            if (term.Length < 2) return false;

            // Trailing two characters are the weekday; anything before them is the ordinal.
            var dayToken = term[^2..].ToUpperInvariant();
            var ordinalToken = term[..^2];

            var day = dayToken switch
            {
                "SU" => DayOfWeek.Sunday,
                "MO" => DayOfWeek.Monday,
                "TU" => DayOfWeek.Tuesday,
                "WE" => DayOfWeek.Wednesday,
                "TH" => DayOfWeek.Thursday,
                "FR" => DayOfWeek.Friday,
                "SA" => DayOfWeek.Saturday,
                _ => (DayOfWeek?)null,
            };
            if (day is null) return false;

            int? ordinal = null;
            if (ordinalToken.Length > 0)
            {
                if (!int.TryParse(ordinalToken, NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out var parsedOrdinal))
                    return false;
                // RFC 5545 allows +/-1..53; 0 is explicitly invalid, and this rule set treats a
                // missing ordinal as "first", so a literal 0 must not silently become that.
                // Bounded to +/-1..5, not RFC 5545's +/-1..53 (Codex review of
                // this PR, P2): ordinals are only honoured for MONTHLY here (see
                // ByDayIsHonouredBy), and no month can contain a sixth
                // occurrence of a weekday. "6MO" would otherwise resolve to
                // nothing every month, so the expander spins to its safety cap
                // and yields a silently EMPTY series instead of reporting the
                // bad rule. The wider RFC range exists for YEARLY, which this
                // subset does not implement.
                //
                // Compared without Math.Abs on purpose: Math.Abs(int.MinValue)
                // THROWS, which would make the documented never-throwing
                // TryParse throw for "BYDAY=-2147483648MO".
                if (parsedOrdinal is 0 or > 5 or < -5) return false;
                ordinal = parsedOrdinal;
            }

            // Duplicate terms are rejected, not collapsed (Codex review of this
            // PR, P2): "BYDAY=1MO,1MO" reaches monthly expansion as two rules,
            // emitting two instances at the SAME timestamp and burning the whole
            // COUNT on one date. Rejecting matches how duplicate PARTS are
            // handled — an ambiguous rule is not silently resolved.
            if (parsed.Any(t => t.Day == day.Value && t.Ordinal == ordinal)) return false;
            // ...and reject SEMANTIC overlap too — but only where it can actually
            // happen (Codex review of this PR, P2, correcting an earlier
            // over-broad rule of mine that refused ANY mixed-sign pair).
            //
            // A weekday occurs 4 or 5 times in a month. Counting from the end,
            // "-j" is the (k+1-j)-th from the start for a month with k
            // occurrences, so a positive n and a negative -j land on the same
            // date exactly when n + j == k + 1, i.e. when n + j is 5 or 6.
            // "1MO,-1MO" (first and last Monday) sums to 2 and therefore never
            // collides — every month has at least four Mondays — so it is a
            // faithful rule the expander emits correctly, and refusing it was
            // wrong.
            if (ordinal is { } o && parsed.Any(t =>
                    t.Day == day.Value && t.Ordinal is { } prev &&
                    Math.Sign(prev) != Math.Sign(o) &&
                    (Math.Abs(prev) + Math.Abs(o)) is 5 or 6))
                return false;
            parsed.Add(new SchedulerByDayRule(day.Value, ordinal));
        }

        if (parsed.Count == 0) return false;
        terms = parsed;
        return true;
    }
}

namespace Lumeo.SchedulerKernel;

/// <summary>
/// One concrete occurrence produced by <see cref="SchedulerRecurrenceExpander"/> — a single
/// (possibly recurring) source event resolved down to one real Start/End pair. Deliberately
/// carries nothing beyond the back-reference and the two timestamps: title/color/resource/etc.
/// don't vary per-occurrence, so the view layer re-joins an instance to its source
/// <see cref="SchedulerEvent"/> by <see cref="EventId"/> rather than this type duplicating those
/// fields per occurrence.
/// </summary>
/// <param name="EventId">The source <see cref="SchedulerEvent.Id"/> this occurrence belongs to.</param>
/// <param name="Start">This occurrence's concrete start (wall-clock, same <see cref="DateTime.Kind"/> semantics as <see cref="SchedulerEvent.Start"/>).</param>
/// <param name="End">This occurrence's concrete end (exclusive, per FullCalendar convention — matches <see cref="SchedulerEvent.End"/>).</param>
internal readonly record struct SchedulerEventInstance(string EventId, DateTime Start, DateTime End);

/// <summary>
/// Expands a <see cref="SchedulerEvent"/> — recurring or not — into concrete
/// <see cref="SchedulerEventInstance"/>s intersecting a given date range. Spec §2.5/§4.1/§7.1.
///
/// <para>
/// <b>One engine, two input shapes.</b> The legacy simple-recurrence model
/// (<see cref="SchedulerEvent.DaysOfWeek"/> + <see cref="SchedulerEvent.RecurrenceEnd"/>) is not a
/// parallel implementation — <see cref="ResolveRule"/> translates it into the exact
/// <see cref="SchedulerRecurrenceRule"/> it's semantically equivalent to
/// (<c>FREQ=WEEKLY;BYDAY=&lt;DaysOfWeek&gt;;UNTIL=&lt;RecurrenceEnd&gt;</c>) and everything downstream
/// runs through the identical structured-rule expansion path. See
/// <c>SchedulerRecurrenceExpanderTests.LegacyDaysOfWeek_And_EquivalentStructuredRule_Produce_ByteIdentical_Instances</c>
/// for the test that proves this rather than just asserting it.
/// </para>
///
/// <para>
/// <b>TZ/DST safety (spec §2.3).</b> Every occurrence is generated via calendar-field arithmetic
/// (<c>AddDays</c>/<c>AddMonths</c>, <c>Year</c>/<c>Month</c>/<c>Day</c>/<c>DayOfWeek</c> reads) on
/// the event's own wall-clock <see cref="DateTime"/> values — never <see cref="TimeZoneInfo"/>,
/// never elapsed-time subtraction across a day boundary. A recurring event's wall-clock
/// time-of-day is carried forward unchanged to every occurrence regardless of DST, matching spec
/// §2.3's rule that each occurrence independently resolves its own wall-clock position (no
/// special-casing for a series that happens to cross a DST boundary).
/// </para>
/// </summary>
internal static class SchedulerRecurrenceExpander
{
    /// <summary>
    /// FLOOR for the number of RRULE-generated candidate occurrences examined for a single
    /// event, independent of (and in addition to) any <see cref="SchedulerRecurrenceRule.Count"/>/
    /// <see cref="SchedulerRecurrenceRule.Until"/> the caller supplied. Mirrors the uploaded
    /// demo's <c>guard++ &lt; 500</c> (spec §2.5) — the safety net for a <c>COUNT</c>-less,
    /// <c>UNTIL</c>-less rule.
    /// </summary>
    /// <remarks>
    /// It used to be a flat ceiling, and that truncated windows longer than itself. Candidates
    /// are generated from the series' own DTSTART, not from <c>rangeStart</c>, so a resource
    /// timeline showing 24 months asks for 730 daily candidates and stopped 230 days short —
    /// the tail of an axis it had already drawn rendered as free (Codex review of PR #424).
    /// The budget now scales with the requested window via <see cref="EffectiveCandidateCap"/>,
    /// with this value as its floor and <see cref="AbsoluteCandidateCap"/> as its ceiling.
    /// </remarks>
    internal const int OccurrenceCap = 500;

    /// <summary>
    /// Ceiling on candidates examined for one event, whatever the window. Reached only by a
    /// rule whose DTSTART sits far enough before the window that the run-up alone exhausts the
    /// budget — the expansion loop itself already stops at <c>rangeEnd</c>.
    /// </summary>
    internal const int AbsoluteCandidateCap = 20_000;

    /// <summary>
    /// Candidate budget for one expansion: enough to REACH the far edge of the requested
    /// window, clamped between <see cref="OccurrenceCap"/> and <see cref="AbsoluteCandidateCap"/>.
    /// Estimated per frequency, always rounding in the direction that over-counts (a month is
    /// treated as its shortest possible length), because under-counting is what truncates.
    /// </summary>
    internal static int EffectiveCandidateCap(SchedulerRecurrenceRule rule, DateTime dtstart,
                                              DateTime rangeStart, DateTime rangeEnd,
                                              TimeSpan duration = default)
    {
        if (rangeEnd <= dtstart) return OccurrenceCap;

        var interval = Math.Max(1, rule.Interval);
        // Weekly collapses BYDAY to distinct weekdays — one occurrence per weekday per week.
        // Monthly does NOT: MonthlyCandidates resolves each ByDay ENTRY separately, so "first
        // through fourth Monday" is four candidates a month, not one. Counting distinct days
        // there left the budget at its floor and stopped a 366-month axis after ~125 months
        // (Codex review round 3).
        var perWeek = rule.ByDay is { Count: > 0 } ? rule.ByDay.Select(b => b.Day).Distinct().Count() : 1;
        var perMonth = rule.ByDay is { Count: > 0 } ? rule.ByDay.Count : 1;
        var daysPerCandidate = rule.Freq switch
        {
            SchedulerRecurrenceFrequency.Daily => (double)interval,
            SchedulerRecurrenceFrequency.Weekly => 7.0 * interval / Math.Max(1, perWeek),
            SchedulerRecurrenceFrequency.Monthly => 28.0 * interval / Math.Max(1, perMonth),
            _ => interval,
        };

        // The margin is a whole boundary burst, not a flat 2: weekly and monthly candidates
        // arrive in clusters, so a range ending partway through an active week or month leaves
        // an average-based estimate short by up to that cluster — enough to drop the last
        // occupied day and render it free (Codex review round 4).
        var burst = rule.Freq switch
        {
            SchedulerRecurrenceFrequency.Weekly => perWeek,
            SchedulerRecurrenceFrequency.Monthly => perMonth,
            _ => 1,
        };
        // Measured over the REQUESTED WINDOW, not from the series' start. Counting the run-up
        // meant a rule whose DTSTART sits far in the past exhausted the budget before reaching
        // the window at all: a daily standup defined in 1970 needs 20 454 candidates to reach
        // 2026 and rendered as nothing (CodeRabbit, PR #424). ExpandRule now seeks past the
        // run-up, so the budget only has to cover what is actually on screen.
        // Measured from where the SEEK starts, not from rangeStart. The seek deliberately reaches
        // back by the event's duration so an occurrence crossing the left edge survives, and those
        // earlier candidates spend the same budget: a 30-day event over a 730-day window begins
        // about 31 candidates early and ran out roughly 28 days short of the end, leaving the tail
        // of the axis free (Codex review round 8).
        var lookback = duration > TimeSpan.Zero ? duration : TimeSpan.Zero;
        var seekFrom = rangeStart - DateTime.MinValue > lookback ? rangeStart - lookback : DateTime.MinValue;
        var from = seekFrom > dtstart ? seekFrom : dtstart;
        var needed = (rangeEnd - from).TotalDays / Math.Max(0.5, daysPerCandidate) + burst + 2;
        return (int)Math.Clamp(needed, OccurrenceCap, AbsoluteCandidateCap);
    }

    /// <summary>
    /// Expands <paramref name="ev"/> into every occurrence whose span intersects the half-open
    /// range [<paramref name="rangeStart"/>, <paramref name="rangeEnd"/>). Handles all three
    /// cases uniformly: a plain non-recurring event (at most one instance), the legacy
    /// <see cref="SchedulerEvent.DaysOfWeek"/> model, and the structured
    /// <see cref="SchedulerEvent.Recurrence"/> rule — mirroring the uploaded demo's single shared
    /// <c>expandEvents()</c> entry point (spec §1.1) rather than requiring the caller to branch
    /// on which recurrence shape a given event uses.
    /// </summary>
    internal static IReadOnlyList<SchedulerEventInstance> Expand(SchedulerEvent ev, DateTime rangeStart, DateTime rangeEnd)
    {
        var rule = ResolveRule(ev);
        return rule is null
            ? ExpandSingle(ev, rangeStart, rangeEnd)
            : ExpandRule(ev, rule, rangeStart, rangeEnd);
    }

    /// <summary>Convenience overload: expands every event in <paramref name="events"/> and flattens the results.</summary>
    internal static IReadOnlyList<SchedulerEventInstance> ExpandAll(IEnumerable<SchedulerEvent> events, DateTime rangeStart, DateTime rangeEnd)
    {
        var result = new List<SchedulerEventInstance>();
        foreach (var ev in events)
            result.AddRange(Expand(ev, rangeStart, rangeEnd));
        return result;
    }

    /// <summary>
    /// Resolves the effective <see cref="SchedulerRecurrenceRule"/> for <paramref name="ev"/>, or
    /// <c>null</c> for a non-recurring event. <see cref="SchedulerEvent.Recurrence"/> wins when
    /// both it and <see cref="SchedulerEvent.DaysOfWeek"/> are set (spec §4.1) — flagged via a
    /// debug-build assertion, not a thrown exception, since the two are redundant rather than
    /// contradictory (both ultimately resolve to a rule) and this repo's convention is to warn,
    /// not crash the render, on caller ambiguity. Exposed (not private) so tests — and the
    /// legacy/structured parity test in particular — can assert on the translation directly
    /// rather than only observing it indirectly through expanded instances.
    /// </summary>
    internal static SchedulerRecurrenceRule? ResolveRule(SchedulerEvent ev)
    {
        if (ev.Recurrence is not null)
        {
            System.Diagnostics.Debug.Assert(
                ev.DaysOfWeek is not { Count: > 0 },
                "SchedulerEvent has both Recurrence and DaysOfWeek set; Recurrence wins per spec §4.1. " +
                "This usually means the caller meant to set exactly one of the two.");
            return ev.Recurrence;
        }

        if (ev.DaysOfWeek is { Count: > 0 })
        {
            // Legacy translation (spec §4.1 point 2): DaysOfWeek + RecurrenceEnd is exactly
            // FREQ=WEEKLY;BYDAY=<DaysOfWeek>;UNTIL=<RecurrenceEnd>. No INTERVAL/COUNT
            // equivalent exists in the legacy shape, so both stay at their rule defaults
            // (Interval=1, Count=null).
            var byDay = new SchedulerByDayRule[ev.DaysOfWeek.Count];
            for (var i = 0; i < ev.DaysOfWeek.Count; i++)
                byDay[i] = new SchedulerByDayRule(ev.DaysOfWeek[i]);

            return new SchedulerRecurrenceRule(
                Freq: SchedulerRecurrenceFrequency.Weekly,
                Interval: 1,
                Count: null,
                Until: ev.RecurrenceEnd,
                ByDay: byDay);
        }

        return null;
    }

    private static IReadOnlyList<SchedulerEventInstance> ExpandSingle(SchedulerEvent ev, DateTime rangeStart, DateTime rangeEnd)
    {
        return ev.End > rangeStart && ev.Start < rangeEnd
            ? new[] { new SchedulerEventInstance(ev.Id, ev.Start, ev.End) }
            : Array.Empty<SchedulerEventInstance>();
    }

    private static IReadOnlyList<SchedulerEventInstance> ExpandRule(
        SchedulerEvent ev, SchedulerRecurrenceRule rule, DateTime rangeStart, DateTime rangeEnd)
    {
        var duration = ev.End - ev.Start;
        HashSet<DateTime>? exceptionDates = null;
        if (ev.ExceptionDates is { Count: > 0 })
        {
            exceptionDates = new HashSet<DateTime>();
            foreach (var d in ev.ExceptionDates)
                exceptionDates.Add(d.Date);
        }

        // Skip the candidates that end before the window opens. They cannot contribute an
        // instance, and walking them was what made a long-lived series vanish entirely.
        //
        // Only when COUNT is absent: COUNT is measured over the raw generated series, so its
        // position has to be counted rather than computed. A COUNT-bounded rule is small by
        // construction (the parser rejects anything larger), so there is nothing to skip.
        var seek = rule.Count.HasValue ? 0 : FirstIntersectingIndex(rule, ev.Start, duration, rangeStart);

        var instances = new List<SchedulerEventInstance>();
        var index = seek;
        var cap = EffectiveCandidateCap(rule, ev.Start, rangeStart, rangeEnd, duration);

        foreach (var candidateStart in GenerateCandidates(rule, ev.Start, seek))
        {
            index++;

            // Safety cap: candidates examined FROM the seek point, independent of COUNT/UNTIL.
            if (index - seek > cap) break;

            // UNTIL is inclusive of its own calendar date (spec §2.5).
            if (rule.Until.HasValue && candidateStart.Date > rule.Until.Value.Date) break;

            // COUNT is measured over the raw rule-generated series, before EXDATE exclusion
            // (RFC 5545 semantics) — an excluded occurrence still consumes a COUNT slot.
            if (rule.Count.HasValue && index > rule.Count.Value) break;

            // Candidates are generated in strictly ascending order, so once one lands at/after
            // rangeEnd, every later candidate would too — safe to stop scanning early. This is a
            // perf optimization only: correctness of COUNT/UNTIL never depended on rangeStart/
            // rangeEnd, since `index` and the Until/Count checks above are computed from
            // ev.Start (the series' own DTSTART), not from the requested render window.
            if (candidateStart >= rangeEnd) break;

            var excluded = exceptionDates is not null && exceptionDates.Contains(candidateStart.Date);
            if (excluded) continue;

            // Clamped rather than added blind: a positive-duration series can now be budgeted
            // far enough to reach the last representable day, where the addition itself threw.
            // The old flat cap stopped decades short of it (Codex review round 3).
            var candidateEnd = duration > DateTime.MaxValue - candidateStart
                ? DateTime.MaxValue
                : candidateStart + duration;
            if (candidateEnd > rangeStart && candidateStart < rangeEnd)
                instances.Add(new SchedulerEventInstance(ev.Id, candidateStart, candidateEnd));
        }

        return instances;
    }

    /// <summary>
    /// Lazily yields raw RRULE candidate start timestamps for <paramref name="rule"/>, in
    /// strictly ascending order, starting at (and never before) <paramref name="dtstart"/>
    /// (<see cref="SchedulerEvent.Start"/>). Unbounded — callers apply COUNT/UNTIL/the occurrence
    /// cap themselves (see <see cref="ExpandRule"/>).
    /// </summary>
    /// <summary>
    /// A SAFE UNDERESTIMATE of how many generated candidates end before <paramref name="rangeStart"/>
    /// and can therefore be skipped. Deliberately conservative — one whole period is subtracted —
    /// because starting too early only costs a few iterations while starting too late would drop
    /// a real occurrence.
    /// </summary>
    internal static int FirstIntersectingIndex(SchedulerRecurrenceRule rule, DateTime dtstart,
                                               TimeSpan duration, DateTime rangeStart)
    {
        // A negative duration is malformed input — SchedulerEvent does not validate End >= Start —
        // and it used to be laid out or discarded harmlessly. Subtracting it here reached FORWARD
        // and threw, taking down every view on the page (Codex review round 8).
        var lookback = duration > TimeSpan.Zero ? duration : TimeSpan.Zero;
        var reach = rangeStart - DateTime.MinValue > lookback ? rangeStart - lookback : DateTime.MinValue;
        if (reach <= dtstart) return 0;

        var interval = Math.Max(1, rule.Interval);
        // WeeklyCandidates collapses ByDay with Distinct(), so a list naming Monday twice — which
        // the legacy DaysOfWeek pair can produce — yields ONE candidate that week, not two.
        // Counting raw entries seeks about twice as far as it should and can land past rangeEnd
        // (Codex review round 8). Monthly resolves each entry separately, so it counts them all.
        var perPeriod = rule.ByDay is { Count: > 0 }
            ? (rule.Freq == SchedulerRecurrenceFrequency.Weekly
                ? rule.ByDay.Select(b => b.Day).Distinct().Count()
                : rule.ByDay.Count)
            : 1;

        double periods = rule.Freq switch
        {
            SchedulerRecurrenceFrequency.Daily => (reach - dtstart).TotalDays / interval,
            SchedulerRecurrenceFrequency.Weekly => (reach - dtstart).TotalDays / (7.0 * interval),
            SchedulerRecurrenceFrequency.Monthly =>
                ((reach.Year - dtstart.Year) * 12.0 + (reach.Month - dtstart.Month)) / interval,
            _ => 0,
        };

        var skippable = (periods - 1) * (rule.Freq == SchedulerRecurrenceFrequency.Daily ? 1 : perPeriod);
        return skippable <= 0 ? 0 : (int)Math.Min(skippable, int.MaxValue / 2);
    }

    private static IEnumerable<DateTime> GenerateCandidates(SchedulerRecurrenceRule rule, DateTime dtstart, int skip) => rule.Freq switch
    {
        SchedulerRecurrenceFrequency.Daily => DailyCandidates(rule, dtstart, skip),
        SchedulerRecurrenceFrequency.Weekly => WeeklyCandidates(rule, dtstart, skip),
        SchedulerRecurrenceFrequency.Monthly => MonthlyCandidates(rule, dtstart, skip),
        _ => throw new ArgumentOutOfRangeException(nameof(rule), rule.Freq, "Unsupported SchedulerRecurrenceFrequency."),
    };

    private static IEnumerable<DateTime> DailyCandidates(SchedulerRecurrenceRule rule, DateTime dtstart, int skip)
    {
        var interval = Math.Max(1, rule.Interval);
        // Jumped to, not iterated to: the point of seeking is to not walk the run-up.
        var offset = (long)skip * interval;
        if (offset > (DateTime.MaxValue - dtstart).TotalDays) yield break;
        var current = dtstart.AddDays(offset);
        while (true)
        {
            yield return current;
            // The step count is no longer bounded by a flat 500, so the advance has to guard
            // its own overflow rather than borrow that bound (Codex review of PR #424).
            if ((DateTime.MaxValue - current).TotalDays < interval) yield break;
            current = current.AddDays(interval);
        }
    }

    // RFC 5545's WKST (week-start-for-INTERVAL-stepping) defaults to Monday; the wave-1 subset
    // doesn't expose WKST as a knob (not in the spec's supported-component table), so Monday is
    // used unconditionally here. Deliberately independent of the Scheduler component's own
    // FirstDayOfWeek (SchedulerDateMath's concern, which is purely about which weekday a
    // month/week GRID visually starts on) — conflating the two would make a rule's occurrence
    // dates shift if a consumer merely changed their calendar's display setting, which would be
    // a real, surprising bug.
    private static IEnumerable<DateTime> WeeklyCandidates(SchedulerRecurrenceRule rule, DateTime dtstart, int skip)
    {
        var interval = Math.Max(1, rule.Interval);
        var days = rule.ByDay is { Count: > 0 }
            ? rule.ByDay.Select(b => b.Day).Distinct().OrderBy(IsoWeekdayIndex).ToArray()
            : new[] { dtstart.DayOfWeek };

        var anchorWeekStart = dtstart.Date.AddDays(-IsoWeekdayIndex(dtstart.DayOfWeek));
        // Whole weeks only. The remainder is left to the loop: a partial week costs at most
        // days.Length iterations, and rounding down keeps the skip an underestimate.
        var weekOffset = days.Length > 0 ? skip / days.Length : 0;
        while (true)
        {
            var offsetDays = weekOffset * 7L * interval;
            if (offsetDays > (DateTime.MaxValue - anchorWeekStart).TotalDays) yield break;
            var weekStart = anchorWeekStart.AddDays(offsetDays);
            foreach (var day in days)
            {
                // The day offset and the time-of-day are each an advance of their own, and the
                // last week before DateTime.MaxValue overflows on one of them rather than on the
                // week step guarded above.
                var dayOffset = IsoWeekdayIndex(day);
                if (dayOffset > (DateTime.MaxValue - weekStart).TotalDays) yield break;
                var atMidnight = weekStart.AddDays(dayOffset);
                if (dtstart.TimeOfDay > DateTime.MaxValue - atMidnight) yield break;

                var candidate = atMidnight + dtstart.TimeOfDay;
                if (candidate >= dtstart)
                    yield return candidate;
            }
            weekOffset++;
        }
    }

    private static IEnumerable<DateTime> MonthlyCandidates(SchedulerRecurrenceRule rule, DateTime dtstart, int skip)
    {
        var interval = Math.Max(1, rule.Interval);
        var perMonth = rule.ByDay is { Count: > 0 } ? rule.ByDay.Count : 1;
        var monthOffset = skip / Math.Max(1, perMonth);
        while (true)
        {
            // AddMonths on a day-1 anchor sidesteps the "Jan 31 + 1 month" overflow trap —
            // SchedulerDateMath.StartOfMonth documents the identical concern for the month grid.
            var anchor = new DateTime(dtstart.Year, dtstart.Month, 1);
            var months = (long)monthOffset * interval;
            // Whole years alone under-counts by up to eleven months: a series starting in
            // January 9999 has eleven representable steps left, and comparing years only
            // treated zero as its maximum, so it yielded January and stopped (Codex review
            // round 3).
            var monthsLeft = (DateTime.MaxValue.Year - anchor.Year) * 12L + (DateTime.MaxValue.Month - anchor.Month);
            if (months > monthsLeft) yield break;
            var monthAnchor = anchor.AddMonths((int)months);
            var year = monthAnchor.Year;
            var month = monthAnchor.Month;

            IEnumerable<DateTime> datesThisMonth;
            if (rule.ByDay is { Count: > 0 })
            {
                var resolved = new List<DateTime>();
                foreach (var byDay in rule.ByDay)
                {
                    var d = ResolveOrdinalWeekday(year, month, byDay.Day, byDay.Ordinal ?? 1);
                    if (d.HasValue) resolved.Add(d.Value);
                }
                resolved.Sort();
                datesThisMonth = resolved;
            }
            else
            {
                // No BYDAY: RFC 5545 default for a bare FREQ=MONTHLY is "same day-of-month as
                // DTSTART". Clamped to the target month's own day count (rather than skipped)
                // so a 31st-anchored monthly rule still produces a February occurrence — a
                // deliberate, documented wave-1 choice; BYMONTHDAY itself (explicit day-number
                // input) is out of scope (spec §2.5's deferred list).
                var day = Math.Min(dtstart.Day, DateTime.DaysInMonth(year, month));
                datesThisMonth = new[] { new DateTime(year, month, day) };
            }

            foreach (var date in datesThisMonth)
            {
                // Same shape as the weekly generator: the time-of-day is its own advance, and
                // the month anchor can already sit on the last representable day.
                if (dtstart.TimeOfDay > DateTime.MaxValue - date.Date) yield break;

                var candidate = date.Date + dtstart.TimeOfDay;
                if (candidate >= dtstart)
                    yield return candidate;
            }

            monthOffset++;
        }
    }

    /// <summary>
    /// The <paramref name="ordinal"/>-th occurrence of <paramref name="day"/> in
    /// <paramref name="year"/>/<paramref name="month"/>. Positive counts from the 1st (1 = first
    /// occurrence); negative counts from the end of the month (-1 = last occurrence). Returns
    /// <c>null</c> when the month doesn't have that many occurrences of the weekday (e.g. a
    /// hypothetical "5th Monday" in a month that only has four).
    /// </summary>
    private static DateTime? ResolveOrdinalWeekday(int year, int month, DayOfWeek day, int ordinal)
    {
        var daysInMonth = DateTime.DaysInMonth(year, month);
        if (ordinal > 0)
        {
            var count = 0;
            for (var d = 1; d <= daysInMonth; d++)
            {
                if (new DateTime(year, month, d).DayOfWeek != day) continue;
                count++;
                if (count == ordinal) return new DateTime(year, month, d);
            }
            return null;
        }

        if (ordinal < 0)
        {
            var count = 0;
            for (var d = daysInMonth; d >= 1; d--)
            {
                if (new DateTime(year, month, d).DayOfWeek != day) continue;
                count++;
                if (count == -ordinal) return new DateTime(year, month, d);
            }
            return null;
        }

        // Ordinal 0 isn't a valid RFC 5545 ordinal; treat as "no match" rather than throwing —
        // same "warn, don't crash" posture used elsewhere in this class.
        return null;
    }

    /// <summary>Monday=0 .. Sunday=6 — the ISO-8601 weekday ordering used to walk a week's candidate days in ascending date order.</summary>
    private static int IsoWeekdayIndex(DayOfWeek d) => d == DayOfWeek.Sunday ? 6 : (int)d - 1;
}

namespace Lumeo;

/// <summary>
/// The <c>FREQ</c> component of the wave-1 RRULE subset (spec §2.5). <c>YEARLY</c> and every
/// other RFC 5545 frequency are explicitly deferred — not silently unsupported, just out of
/// scope for wave 1.
/// </summary>
public enum SchedulerRecurrenceFrequency
{
    /// <summary>Repeats every <c>Interval</c> days.</summary>
    Daily,

    /// <summary>Repeats every <c>Interval</c> weeks, on the day(s) in <see cref="SchedulerRecurrenceRule.ByDay"/> (or the start date's own weekday when <see cref="SchedulerRecurrenceRule.ByDay"/> is unset).</summary>
    Weekly,

    /// <summary>Repeats every <c>Interval</c> months, on the day(s)/ordinal-weekday(s) in <see cref="SchedulerRecurrenceRule.ByDay"/> (or the start date's own day-of-month when <see cref="SchedulerRecurrenceRule.ByDay"/> is unset).</summary>
    Monthly
}

/// <summary>
/// A single <c>BYDAY</c> term: a weekday, optionally qualified with an ordinal ("2nd Monday",
/// "last Friday") for <see cref="SchedulerRecurrenceFrequency.Monthly"/> rules.
/// </summary>
/// <param name="Day">The day of the week.</param>
/// <param name="Ordinal">
/// Only meaningful for <see cref="SchedulerRecurrenceFrequency.Monthly"/> rules. A positive value
/// counts from the start of the month (<c>1</c> = first occurrence of <see cref="Day"/> in the
/// month, <c>2</c> = second, ...); a negative value counts from the end of the month (<c>-1</c> =
/// last occurrence, <c>-2</c> = second-to-last, ...), matching RFC 5545's <c>BYDAY</c> ordinal
/// syntax (e.g. <c>"2MO"</c> = second Monday, <c>"-1FR"</c> = last Friday — the "last Friday of
/// the month standup" case called out in the spec). <c>null</c> (unset) is treated as <c>1</c>
/// (the first occurrence) — RFC 5545's OTHER reading of a bare, unqualified <c>BYDAY</c> inside a
/// <c>MONTHLY</c> rule ("every occurrence of that weekday in the month", i.e. potentially more
/// than one date) is out of scope for wave 1. Ignored entirely for
/// <see cref="SchedulerRecurrenceFrequency.Weekly"/> rules, where a <see cref="SchedulerByDayRule"/>
/// only ever selects a day-of-week within each recurring week.
/// </param>
public sealed record SchedulerByDayRule(DayOfWeek Day, int? Ordinal = null);

/// <summary>
/// The wave-1 RRULE subset (spec §2.5): <c>FREQ=DAILY|WEEKLY|MONTHLY</c>, <c>INTERVAL</c>,
/// <c>COUNT</c>, <c>UNTIL</c>, and <c>BYDAY</c> (weekly day-of-week set, or monthly
/// ordinal-weekday). <c>EXDATE</c> is deliberately NOT part of this record — it continues to be
/// expressed via <see cref="SchedulerEvent.ExceptionDates"/>, the existing shipped property,
/// rather than duplicating it here.
/// </summary>
/// <param name="Freq">The repeat frequency.</param>
/// <param name="Interval">
/// Repeat every <see cref="Interval"/>-th occurrence of <see cref="Freq"/>'s unit (e.g.
/// <see cref="Freq"/> = <see cref="SchedulerRecurrenceFrequency.Weekly"/> and
/// <see cref="Interval"/> = 2 means "every 2 weeks"). Must be 1 or greater; values below 1 are
/// treated as 1 by <c>SchedulerRecurrenceExpander</c> rather than throwing, matching this repo's
/// general "warn, don't crash the render" posture for malformed input.
/// </param>
/// <param name="Count">
/// When set, bounds the series to exactly this many occurrences, counted from
/// <see cref="SchedulerEvent.Start"/> (the series' own DTSTART) — regardless of which date range
/// the expander is later asked to render, so a windowed render always agrees with a full-series
/// render about which occurrence index is "the 5th one". Per RFC 5545, this count is taken over
/// the raw rule-generated series BEFORE <see cref="SchedulerEvent.ExceptionDates"/> exclusions are
/// applied — an excluded occurrence still consumes one of the <see cref="Count"/> slots.
/// </param>
/// <param name="Until">
/// When set, the inclusive end date of the series (spec §2.5: "UNTIL — inclusive end date”). Only
/// the date part is significant; an occurrence landing on <see cref="Until"/>'s own calendar date
/// is still included.
/// </param>
/// <param name="ByDay">
/// For <see cref="SchedulerRecurrenceFrequency.Weekly"/>: the set of weekdays the event repeats
/// on within each recurring week (<see cref="SchedulerByDayRule.Ordinal"/> is ignored). For
/// <see cref="SchedulerRecurrenceFrequency.Monthly"/>: one or more ordinal-weekday terms (e.g.
/// "2nd Monday", "last Friday" — see <see cref="SchedulerByDayRule.Ordinal"/>). <c>null</c>
/// (unset) falls back to <see cref="SchedulerEvent.Start"/>'s own day-of-week (Weekly) or
/// day-of-month (Monthly). Not applicable to <see cref="SchedulerRecurrenceFrequency.Daily"/>.
/// </param>
public sealed record SchedulerRecurrenceRule(
    SchedulerRecurrenceFrequency Freq,
    int Interval = 1,
    int? Count = null,
    DateTime? Until = null,
    IReadOnlyList<SchedulerByDayRule>? ByDay = null);

@namespace Lumeo
@using System.Globalization
@using Lumeo.SchedulerKernel
@inject Lumeo.Services.Localization.ILumeoLocalizer L

@* First-party RESOURCE view — one column per bookable resource for a single day
   (ReUI parity: "a resource view with one column per bookable resource activates
   automatically when resources are passed"). Lumeo already had SchedulerResource
   and SchedulerEvent.ResourceId, but they only drove colour-coding and a legend;
   no view had ever grouped BY resource, so a room-booking or per-person schedule
   was not expressible at all.

   Deliberately a separate component rather than a mode of SchedulerTimeGridView:
   that view's columns ARE dates throughout — _dayColumns, data-daycol, and its
   whole drag/create engine key off the day under the pointer. Overloading them to
   sometimes mean "resource" would fork the interaction layer's most delicate
   code. Sharing the TIME axis and the overlap packer (both pure kernel calls) is
   where the real duplication would have been, and both are reused here.

   ACCESSIBILITY: deliberately NOT role="grid" (Codex review, P2). The DOM is
   column-oriented — one element per resource, hours stacked inside it — while the
   visual grid reads as hours-by-resource, so grid roles reported the two axes
   swapped. A grid role also promises two-dimensional arrow navigation, which this
   read-only view does not implement. Each column is a labelled list of bookings,
   which is what it actually is. *@
<div class="@($"flex flex-col w-full rounded-md border border-border/60 overflow-hidden {Class}".Trim())"
     role="group" aria-label="@GridAriaLabel()" @attributes="AdditionalAttributes">
    @* ONE horizontal scroller wrapping header AND body (Codex review, P2): two
       separate scrollers drift apart as soon as the resource list outgrows the
       viewport, putting every column under the wrong heading. *@
    <div class="overflow-x-auto">
        <div style="min-width: max-content;">
            <div class="flex border-b border-border/60 bg-card">
                <div class="flex-none w-14" aria-hidden="true"></div>
                <div class="grid" style="@ColumnsStyle">
                    @foreach (var resource in _resources)
                    {
                        <div class="border-l border-border/40 px-2 py-1.5 text-center text-[11px] font-medium text-muted-foreground truncate"
                             data-resource-id="@resource.Id" title="@resource.Title">@resource.Title</div>
                    }
                </div>
            </div>

            @if (_anyAllDay)
            {
                <div class="flex border-b border-border/60">
                    <div class="flex-none w-14 pt-1.5 pl-1 text-[10px] text-muted-foreground">@L["Scheduler.AllDay"]</div>
                    <div class="grid" style="@ColumnsStyle">
                        @for (var r = 0; r < _resources.Count; r++)
                        {
                            var resource = _resources[r];
                            <div class="border-l border-border/40 p-1 flex flex-col gap-0.5 min-w-0"
                                 role="list" aria-label="@AllDayListLabel(resource)">
                                @foreach (var block in _allDayByResource[r])
                                {
                                    <button type="button" role="listitem"
                                            class="@($"{ChipClass} w-full {ResolveEventClassNames?.Invoke(block.Source)}".TrimEnd())"
                                            style="@AllDayChipStyle(block)"
                                            data-event-id="@block.Source.Id"
                                            data-resource-id="@resource.Id"
                                            data-allday="true"
                                            aria-label="@AllDayAriaLabel(resource, block)"
                                            @onclick="() => OnEventClickAsync(block.Source)">
                                        <span class="block truncate font-semibold">@block.Source.Title</span>
                                    </button>
                                }
                            </div>
                        }
                    </div>
                </div>
            }

            <div class="flex" style="max-height: 34rem; overflow-y: auto;">
                <div class="flex-none w-14">
                    @foreach (var hour in _hours)
                    {
                        <div class="h-12 relative">
                            <span class="absolute -top-1.5 right-1.5 text-[11px] text-muted-foreground">@FormatHour(hour)</span>
                        </div>
                    }
                </div>
                <div class="grid relative" style="@ColumnsStyle">
                    @for (var r = 0; r < _resources.Count; r++)
                    {
                        var resourceIndex = r;
                        var resource = _resources[resourceIndex];
                        <div class="relative border-l border-border/40"
                             data-resourcecol="@resource.Id"
                             role="list" aria-label="@TimedListLabel(resource)">
                            @foreach (var hour in _hours)
                            {
                                <div class="h-12 border-b border-border/30" aria-hidden="true"></div>
                            }
                            @foreach (var block in _byResource[resourceIndex])
                            {
                                <button type="button" role="listitem"
                                        class="@($"absolute z-10 {ChipClass} {ResolveEventClassNames?.Invoke(block.Source)}".TrimEnd())"
                                        style="@TimedChipStyle(block)"
                                        data-event-id="@block.Source.Id"
                                        data-resource-id="@resource.Id"
                                        aria-label="@TimedAriaLabel(resource, block)"
                                        @onclick="() => OnEventClickAsync(block.Source)">
                                    <span class="block font-semibold truncate">@block.Source.Title</span>
                                    <span class="block text-[10px] opacity-80">@FormatTime(block.Start)</span>
                                </button>
                            }
                        </div>
                    }
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    private const string ChipClass =
        "rounded-sm border-l-2 px-1.5 py-0.5 text-left text-[11px] leading-tight overflow-hidden cursor-pointer focus-visible:outline focus-visible:outline-2 focus-visible:outline-ring";

    /// <summary>Minimum rendered width of a resource column. Below this, headings and chips are unreadable, so the view scrolls horizontally instead of compressing (Codex review, P2).</summary>
    private const string MinColumnWidth = "8rem";

    /// <summary>Shortest booking the layout can draw legibly — also the floor used for overlap packing, so packing and rendering agree.</summary>
    private const int MinRenderedMinutes = 20;

    /// <summary>The events to place. Only those whose <see cref="SchedulerEvent.ResourceId"/> matches a supplied resource are rendered — see <see cref="Resources"/>.</summary>
    [Parameter] public IEnumerable<SchedulerEvent>? Events { get; set; }

    /// <summary>
    /// The bookable resources, one column each, in the given order.
    /// <para>
    /// An event whose <see cref="SchedulerEvent.ResourceId"/> matches none of them is NOT
    /// rendered, deliberately: inventing an "unassigned" column would be a layout decision this
    /// view has no basis to make, and silently folding such events into the first column would
    /// misattribute someone's booking. Callers that want them visible should add a resource to
    /// represent that bucket.
    /// </para>
    /// <para>
    /// Duplicate ids resolve to the LAST entry, matching <c>Scheduler</c>'s own resource lookup so
    /// the two components never disagree about an event's colour.
    /// </para>
    /// </summary>
    [Parameter] public IReadOnlyList<SchedulerResource>? Resources { get; set; }

    /// <summary>The single day this view lays out. Only the date part is read.</summary>
    [Parameter] public DateTime Date { get; set; } = DateTime.Today;

    /// <summary>First minute shown on the time axis. Default 00:00.</summary>
    [Parameter] public TimeOnly? SlotMinTime { get; set; }

    /// <summary>Last minute shown on the time axis. Default end of day.</summary>
    [Parameter] public TimeOnly? SlotMaxTime { get; set; }

    /// <summary>Raised when a booking chip is clicked.</summary>
    [Parameter] public EventCallback<SchedulerEvent> OnEventClick { get; set; }

    /// <summary>Per-event colour override, matching the other first-party views.</summary>
    [Parameter] public Func<SchedulerEvent, string?>? ResolveEventColor { get; set; }

    /// <summary>Extra CSS classes per booking chip, matching the other first-party views' resolver.</summary>
    [Parameter] public Func<SchedulerEvent, string?>? ResolveEventClassNames { get; set; }

    [Parameter] public string? Class { get; set; }
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private IReadOnlyList<SchedulerResource> _resources = Array.Empty<SchedulerResource>();
    private Dictionary<string, SchedulerResource> _resourceById = new(StringComparer.Ordinal);
    private int[] _hours = Array.Empty<int>();
    private int _axisAnchorMinute;
    private int _minMinute;
    private int _maxMinute;
    private List<Block>[] _byResource = Array.Empty<List<Block>>();
    private List<Block>[] _allDayByResource = Array.Empty<List<Block>>();
    private bool _anyAllDay;

    private string ColumnsStyle =>
        $"grid-template-columns: repeat({Math.Max(1, _resources.Count)}, minmax({MinColumnWidth}, 1fr));";

    protected override void OnParametersSet()
    {
        _resources = Resources ?? Array.Empty<SchedulerResource>();

        // Last-wins, matching Scheduler's own RebuildResourceLookup (Codex review,
        // P2): with duplicate ids the two components must agree on the colour.
        _resourceById = new Dictionary<string, SchedulerResource>(StringComparer.Ordinal);
        foreach (var r in _resources) _resourceById[r.Id] = r;

        var min = SlotMinTime ?? new TimeOnly(0, 0);
        var max = SlotMaxTime ?? new TimeOnly(23, 59, 59);
        _minMinute = Math.Clamp(min.Hour * 60 + min.Minute, 0, 24 * 60 - 1);
        // Clamped to the end of the day (Codex review, P2): a SlotMinTime of 23:30
        // pushed the minimum-span rule past midnight, and the resulting hour 24 threw
        // out of DateTime's constructor while formatting the axis.
        _maxMinute = Math.Clamp(Math.Max(_minMinute + MinRenderedMinutes, max.Hour * 60 + max.Minute), 0, 24 * 60);

        // Hour rows anchor on the whole hour at or below the start minute, and every
        // chip is positioned from that SAME anchor (Codex review, P2) — the two used
        // to disagree for a fractional SlotMinTime such as 08:30, so bookings sat half
        // an hour away from their own labels.
        _axisAnchorMinute = _minMinute / 60 * 60;
        var hourStart = _axisAnchorMinute / 60;
        var hourEnd = (int)Math.Ceiling(_maxMinute / 60.0);
        _hours = Enumerable.Range(hourStart, Math.Max(1, hourEnd - hourStart)).ToArray();

        BuildBlocks();
    }

    private void BuildBlocks()
    {
        _byResource = new List<Block>[_resources.Count];
        _allDayByResource = new List<Block>[_resources.Count];
        for (var i = 0; i < _resources.Count; i++)
        {
            _byResource[i] = new List<Block>();
            _allDayByResource[i] = new List<Block>();
        }
        _anyAllDay = false;
        if (_resources.Count == 0) return;

        var events = (Events ?? Enumerable.Empty<SchedulerEvent>()).ToList();
        var byId = new Dictionary<string, SchedulerEvent>(StringComparer.Ordinal);
        foreach (var e in events) byId[e.Id] = e;

        var day = Date.Date;
        var dayEnd = day.AddDays(1);
        var instances = SchedulerRecurrenceExpander.ExpandAll(events, day, dayEnd)
            .Where(i => byId.ContainsKey(i.EventId))
            .ToList();

        for (var r = 0; r < _resources.Count; r++)
        {
            var id = _resources[r].Id;
            var mine = instances
                .Where(i => string.Equals(byId[i.EventId].ResourceId, id, StringComparison.Ordinal))
                .ToList();
            if (mine.Count == 0) continue;

            var timed = new List<(string Key, DateTime Start, DateTime End, SchedulerEvent Source)>();
            for (var n = 0; n < mine.Count; n++)
            {
                var inst = mine[n];
                var src = byId[inst.EventId];

                // All-day bookings get their own strip rather than being dropped
                // (Codex review, P2): the Events contract allows AllDay, and a room
                // booked for the whole day is an ordinary case that simply vanished.
                if (src.AllDay)
                {
                    _allDayByResource[r].Add(new Block(src, inst.Start, inst.End, 0, 1));
                    _anyAllDay = true;
                    continue;
                }

                // Clipped to THIS day (Codex review, P2): a 22:00-02:00 booking is
                // returned whole for either day it touches, so without clipping the
                // second day drew it from 22:00 again instead of from midnight.
                var start = inst.Start < day ? day : inst.Start;
                var end = inst.End > dayEnd ? dayEnd : inst.End;
                if (end <= start) continue;

                // Outside the visible hours entirely — skipped rather than clamped
                // (Codex review, P2): clamping a 06:00-07:00 booking into an
                // 08:00-start axis drew a sliver at the top, implying a reservation
                // that is not actually in view.
                var startMin = (int)(start - day).TotalMinutes;
                var endMin = (int)(end - day).TotalMinutes;
                if (endMin <= _minMinute || startMin >= _maxMinute) continue;

                // Unique per OCCURRENCE, not per (id, start) (Codex review, P2): two
                // events sharing an id and a start time produced the same key and threw
                // out of the packer's ToDictionary.
                timed.Add(($"{inst.EventId}|{n}", start, end, src));
            }

            if (timed.Count == 0) continue;

            // Packed with the SAME minimum span the renderer draws (Codex review, P2):
            // a 5-minute booking is drawn 20 minutes tall, so packing it by its real
            // end let the next booking overlap it on screen.
            var packInput = timed
                .Select(t =>
                {
                    var s = (int)(t.Start - day).TotalMinutes;
                    var e = Math.Max(s + MinRenderedMinutes, (int)(t.End - day).TotalMinutes);
                    return (Id: t.Key, StartMinute: s, EndMinute: e);
                })
                .ToList();
            var packed = SchedulerTimeGridLayout.Pack(packInput)
                .ToDictionary(p => p.Id, p => (p.Column, p.ColumnsInCluster), StringComparer.Ordinal);

            foreach (var t in timed)
            {
                var (col, cols) = packed.TryGetValue(t.Key, out var p) ? p : (0, 1);
                _byResource[r].Add(new Block(t.Source, t.Start, t.End, col, cols));
            }
        }
    }

    private string ResolveColor(SchedulerEvent ev)
    {
        var resource = ev.ResourceId is { } rid && _resourceById.TryGetValue(rid, out var r) ? r : null;
        return ResolveEventColor?.Invoke(ev) ?? ev.Color ?? resource?.Color ?? "var(--color-primary)";
    }

    private string TimedChipStyle(Block block)
    {
        var day = Date.Date;
        var startMinute = Math.Clamp((int)(block.Start - day).TotalMinutes, _minMinute, _maxMinute);
        var endMinute = Math.Clamp(
            Math.Max(startMinute + MinRenderedMinutes, (int)(block.End - day).TotalMinutes),
            _minMinute, _maxMinute);

        const double pxPerMinute = 48.0 / 60.0;
        var top = (startMinute - _axisAnchorMinute) * pxPerMinute;
        var height = Math.Max(16, (endMinute - startMinute) * pxPerMinute);
        var width = 100.0 / Math.Max(1, block.ColumnsInCluster);
        var left = block.Column * width;
        var inv = CultureInfo.InvariantCulture;
        var color = ResolveColor(block.Source);
        return $"top:{top.ToString(inv)}px; height:{height.ToString(inv)}px; left:calc({left.ToString(inv)}% + 2px); width:calc({width.ToString(inv)}% - 4px); background-color: color-mix(in oklab, {color} 18%, transparent); color: color-mix(in oklab, {color} 38%, var(--lumeo-event-fg-anchor)); border-left-color: {color};";
    }

    private string AllDayChipStyle(Block block)
    {
        var color = ResolveColor(block.Source);
        return $"background-color: color-mix(in oklab, {color} 18%, transparent); color: color-mix(in oklab, {color} 38%, var(--lumeo-event-fg-anchor)); border-left-color: {color};";
    }

    private async Task OnEventClickAsync(SchedulerEvent ev)
    {
        if (OnEventClick.HasDelegate) await OnEventClick.InvokeAsync(ev);
    }

    private string GridAriaLabel() =>
        L["Scheduler.ResourceGridLabel", Date.ToString("D", CultureInfo.CurrentUICulture)];

    private static string TimedListLabel(SchedulerResource resource) => resource.Title;

    private string AllDayListLabel(SchedulerResource resource) =>
        $"{resource.Title}, {L["Scheduler.AllDay"]}";

    /// <summary>Names the resource AND the full span: chip height is the only visual cue for duration, and a screen reader cannot see it (Codex review, P2).</summary>
    private static string TimedAriaLabel(SchedulerResource resource, Block block) =>
        $"{block.Source.Title}, {resource.Title}, {FormatTime(block.Start)} – {FormatTime(block.End)}";

    private string AllDayAriaLabel(SchedulerResource resource, Block block) =>
        $"{block.Source.Title}, {resource.Title}, {L["Scheduler.AllDay"]}";

    private static string FormatTime(DateTime value) =>
        value.ToString("t", CultureInfo.CurrentUICulture);

    /// <summary>Hour 24 marks the end of the axis, not a wall-clock hour — rendered as midnight rather than throwing.</summary>
    private static string FormatHour(int hour) =>
        new DateTime(2000, 1, 1, Math.Clamp(hour, 0, 23), 0, 0).ToString("t", CultureInfo.CurrentUICulture);

    private sealed record Block(SchedulerEvent Source, DateTime Start, DateTime End, int Column, int ColumnsInCluster);
}

namespace Lumeo.SchedulerKernel;

/// <summary>
/// Cluster + greedy column packing for overlapping timed events within a single day's time
/// grid (Week/Day view). Faithful formalization of the uploaded demo's <c>layoutTimed()</c> —
/// spec §1.3, which this class implements algorithm-for-algorithm (see <see cref="Pack"/>'s own
/// remarks for the step-by-step correspondence).
/// </summary>
internal static class SchedulerTimeGridLayout
{
    /// <summary>
    /// Packs same-day timed events into (column, columnsInCluster) slots so overlapping events
    /// render side-by-side instead of stacking. Input events are (Id, StartMinute, EndMinute)
    /// triples (minutes since midnight; <c>StartMinute &lt; EndMinute</c> is assumed — a
    /// zero-duration event, <c>StartMinute == EndMinute</c>, is handled without throwing but
    /// never overlaps anything, see remarks). Output is one (Id, Column, ColumnsInCluster) triple
    /// per input event, in the same processing order the algorithm sorts them into (start
    /// ascending, end descending) rather than the caller's original order — callers that need the
    /// original order should re-project by Id.
    /// </summary>
    /// <remarks>
    /// Algorithm (spec §1.3), reproduced 1:1 from the uploaded demo's <c>layoutTimed()</c>:
    /// <list type="number">
    /// <item>Sort by StartMinute ascending, ties broken by EndMinute descending (longer events
    /// first — demo: <c>a.startMin - b.startMin || b.endMin - a.endMin</c>).</item>
    /// <item>Walk the sorted list maintaining a running cluster envelope (<c>clusterEnd</c>): if
    /// an event's StartMinute is at or past <c>clusterEnd</c>, flush the current cluster and
    /// start a new one; otherwise the event joins the current cluster and <c>clusterEnd</c>
    /// extends to <c>max(clusterEnd, event.EndMinute)</c> even if THIS event doesn't overlap the
    /// cluster's first event — only the running envelope (transitive overlap). This is what makes
    /// a 3-event "staircase" (each overlapping only its immediate neighbor) still get 3 columns,
    /// not 2 — a naive pairwise-overlap check would wrongly collapse it to 2.</item>
    /// <item>Within its cluster, each event is assigned the lowest column index whose most
    /// recently placed occupant's end time does not exceed (is not strictly greater than) the
    /// event's own start time — <c>end == start</c> at a column boundary is NOT overlap (open
    /// interval), matching the same flush condition in step 2.</item>
    /// <item><c>ColumnsInCluster</c> for every event in a cluster is <c>max(column) + 1</c> across
    /// that cluster, computed once every event in it has been assigned a column.</item>
    /// </list>
    /// Downstream note: <c>ColumnsInCluster</c> returned here is
    /// always &gt;= 1 (even for a lone zero-duration event), so a caller computing
    /// <c>width = 100% / ColumnsInCluster</c> never divides by zero — the zero-duration case
    /// needs no special-casing in <see cref="Pack"/> itself, only downstream renderers need to
    /// avoid rendering a literal 0px-tall chip, which is a view-layer concern, not this method's.
    /// </remarks>
    internal static IReadOnlyList<(string Id, int Column, int ColumnsInCluster)> Pack(
        IReadOnlyList<(string Id, int StartMinute, int EndMinute)> events)
    {
        if (events.Count == 0) return Array.Empty<(string, int, int)>();

        var sorted = events
            .OrderBy(e => e.StartMinute)
            .ThenByDescending(e => e.EndMinute)
            .ToArray();

        var n = sorted.Length;
        var column = new int[n];
        var clusterId = new int[n];
        var clusterEnd = int.MinValue;
        var currentClusterId = -1;

        // Column -> end time of the last event placed in that column, scoped to the CURRENT
        // cluster only (reset on every flush).
        var columnEnds = new Dictionary<int, int>();

        for (var i = 0; i < n; i++)
        {
            var ev = sorted[i];

            if (i == 0 || ev.StartMinute >= clusterEnd)
            {
                // Flush: start a new cluster. Open interval at the boundary — StartMinute equal
                // to (not just past) clusterEnd does NOT extend the previous cluster.
                currentClusterId++;
                columnEnds.Clear();
                clusterEnd = ev.EndMinute;
            }
            else
            {
                // Joins the current cluster via the running (transitive) envelope, even if this
                // event doesn't overlap the cluster's very first event.
                clusterEnd = Math.Max(clusterEnd, ev.EndMinute);
            }

            clusterId[i] = currentClusterId;

            var col = 0;
            while (columnEnds.TryGetValue(col, out var occupantEnd) && occupantEnd > ev.StartMinute)
                col++;

            column[i] = col;
            columnEnds[col] = ev.EndMinute;
        }

        var maxColumnPerCluster = new Dictionary<int, int>();
        for (var i = 0; i < n; i++)
        {
            var candidate = column[i] + 1;
            if (!maxColumnPerCluster.TryGetValue(clusterId[i], out var current) || candidate > current)
                maxColumnPerCluster[clusterId[i]] = candidate;
        }

        var result = new (string Id, int Column, int ColumnsInCluster)[n];
        for (var i = 0; i < n; i++)
            result[i] = (sorted[i].Id, column[i], maxColumnPerCluster[clusterId[i]]);

        return result;
    }
}

@namespace Lumeo
@using System.Globalization
@using Lumeo.SchedulerKernel
@implements IAsyncDisposable
@inject Lumeo.Services.IComponentInteropService Interop
@inject Lumeo.Services.Localization.ILumeoLocalizer L

@* First-party time-grid view (spec §1.1/§1.2/§1.3/§5), shared by Week (Days=7) and Day
   (Days=1) — mirrors the uploaded demo's renderWeek(days) sharing one implementation via a
   `days` parameter (spec §1.1). Consumes SchedulerDateMath for week boundaries,
   SchedulerRecurrenceExpander for occurrence expansion, and SchedulerTimeGridLayout for
   overlapping-event column packing. Internal building block — see SchedulerMonthView's own
   remarks for the "Scheduler.razor is the only component with public parameters" note. *@
<div class="@($"flex flex-col w-full rounded-md border border-border/60 overflow-hidden {Class}".Trim())" @attributes="AdditionalAttributes">
    @* See SchedulerMonthView's own live-region remarks — rendered empty at
       mount so assistive tech is already observing the node. *@
    <span class="sr-only" aria-live="polite" aria-atomic="true"
          data-testid="scheduler-live-region" data-announce-epoch="@_announcementEpoch">@AnnouncementText</span>
    @if (_allDayInstances.Any())
    {
        <div class="flex border-b border-border/60">
            <div class="flex-none w-14 text-[10px] text-muted-foreground pt-1.5 pl-1">@L["Scheduler.AllDay"]</div>
            <div class="flex-1 grid min-w-0" style="grid-template-columns: repeat(@Days, minmax(0, 1fr));">
                @for (var d = 0; d < Days; d++)
                {
                    var dayIndex = d;
                    var laneSlots = dayIndex < _allDayLaneSlots.Length ? _allDayLaneSlots[dayIndex] : Array.Empty<AllDaySlot?>();
                    <div class="border-l border-border/40 p-1 flex flex-col gap-0.5 min-w-0">
                        @for (var lane = 0; lane < laneSlots.Count; lane++)
                        {
                            var slot = laneSlots[lane];
                            if (slot is null)
                            {
                                <div class="h-[19px]" data-lane="@lane" aria-hidden="true"></div>
                            }
                            else
                            {
                                <Tooltip ShowDelay="400" Class="w-full">
                                    <TooltipTrigger AsChild="true">
                                        <ChildContentSlot Context="pillSlot">
                                            <button type="button" class="@AllDayPillClasses(slot)" style="@PillStyle(slot.Source)"
                                                    data-event-id="@slot.Instance.EventId"
                                                    data-lane="@lane"
                                                    @attributes="pillSlot.Attributes"
                                                    @onclick="() => OnEventClickAsync(slot.Source)">
                                                @if (slot.ShowTitle)
                                                {
                                                    @slot.Source.Title
                                                }
                                                else
                                                {
                                                    <span aria-hidden="true">&nbsp;</span>
                                                }
                                            </button>
                                        </ChildContentSlot>
                                    </TooltipTrigger>
                                    <TooltipContent>@TooltipLabel(slot.Source, slot.Instance)</TooltipContent>
                                </Tooltip>
                            }
                        }
                    </div>
                }
            </div>
        </div>
    }

    <div class="flex" style="max-height: 34rem; overflow-y: auto;" @ref="_scrollRef">
        <div class="flex-none w-14">
            @foreach (var hour in _hourLabels)
            {
                <div class="h-12 relative">
                    <span class="absolute -top-1.5 right-1.5 text-[11px] text-muted-foreground">@FormatHour(hour)</span>
                </div>
            }
        </div>
        <div class="flex-1 grid min-w-0 relative" role="grid" aria-label="@GridAriaLabel()" style="grid-template-columns: repeat(@Days, minmax(0, 1fr));" @ref="_hostRef">
            @for (var d = 0; d < Days; d++)
            {
                var dayIndex = d;
                var day = _dayColumns[dayIndex];
                <div class="relative border-l border-border/40" role="row" data-daycol="@day.ToString("yyyy-MM-dd")" @ref="_dayColumnRefs[dayIndex]">
                    @for (var h = 0; h < _slotStarts.Length; h++)
                    {
                        var slotIndex = h;
                        var slotStart = _slotStarts[slotIndex];
                        var cellLinear = slotIndex * Days + dayIndex;
                        var isFocused = cellLinear == _focusedIndex;
                        <div role="gridcell"
                             @ref="_cellRefs[cellLinear]"
                             tabindex="@(isFocused ? "0" : "-1")"
                             data-slot-hour="@(slotStart / 60)"
                             data-slot-minute="@slotStart"
                             data-off="@(IsOffSlot(day, slotStart) ? "true" : null)"
                             aria-label="@SlotAriaLabel(day, slotStart)"
                             style="@SlotCellStyle()"
                             class="@SlotCellClasses(slotStart)"
                             @onclick="() => OnSlotClickAsync(day, slotIndex)"
                             @ondblclick="() => OnSlotDoubleClickAsync(day, slotStart)"
                             @onkeydown="e => OnGridKeyDownAsync(e, dayIndex, slotIndex)">
                        </div>
                    }
                    @foreach (var block in _timedByDay[dayIndex])
                    {
                        var key = InstanceKey(block.Instance);
                        var blockHourIndex = SlotIndexOf(block.Instance.Start);
                        <Tooltip ShowDelay="400" Class="static">
                            <TooltipTrigger AsChild="true">
                                <ChildContentSlot Context="pillSlot">
                                    <button type="button"
                                            @ref="_pillRefs[key]"
                                            class="@TimedPillClasses()"
                                            style="@TimedPillStyle(block)"
                                            data-event-instance="@key"
                                            data-event-id="@block.Instance.EventId"
                                            data-resizable="@(Editable ? "true" : null)"
                                            tabindex="-1"
                                            aria-label="@PillAriaLabel(block.Source, block.Instance)"
                                            @attributes="pillSlot.Attributes"
                                            @onclick:stopPropagation="true"
                                            @onclick="() => OnEventClickAsync(block.Source)"
                                            @onkeydown="e => OnPillKeyDownAsync(e, block.Source, dayIndex, blockHourIndex)">
                                        <span class="block font-semibold truncate">@block.Source.Title</span>
                                        <span class="block text-[10px] opacity-80">@block.Instance.Start.ToString("t", CultureInfo.CurrentUICulture)</span>
                                    </button>
                                </ChildContentSlot>
                            </TooltipTrigger>
                            <TooltipContent>@TooltipLabel(block.Source, block.Instance)</TooltipContent>
                        </Tooltip>
                    }
                </div>
            }
        </div>
    </div>
</div>

@code {
    /// <summary>The calendar's events (expanded per occurrence internally via <c>SchedulerRecurrenceExpander</c>).</summary>
    [Parameter] public IEnumerable<SchedulerEvent>? Events { get; set; }

    /// <summary>Anchor date. Week mode (<see cref="Days"/> == 7) resolves the containing week via <see cref="FirstDayOfWeek"/>; Day mode (<see cref="Days"/> == 1) shows this date only.</summary>
    [Parameter] public DateTime AnchorDate { get; set; } = DateTime.Today;

    /// <summary>Number of day columns: 7 = Week, 1 = Day (spec §1.1). Any other value renders that many columns starting at <see cref="AnchorDate"/> (wave-3 N-day groundwork, not yet a public view).</summary>
    [Parameter] public int Days { get; set; } = 7;

    [Parameter] public DayOfWeek FirstDayOfWeek { get; set; } = DayOfWeek.Monday;

    /// <summary>Earliest visible slot. Default 00:00. Never changes the underlying wall-clock grid math (spec §2.3) — purely a visible-range clamp.</summary>
    [Parameter] public TimeOnly? SlotMinTime { get; set; }

    /// <summary>Latest visible slot. Default 24:00.</summary>
    [Parameter] public TimeOnly? SlotMaxTime { get; set; }

    /// <summary>
    /// How long one grid row represents. Default (<c>null</c>) is one hour, which is the
    /// grid this view has always drawn.
    /// <para>
    /// Rows have to tile an hour exactly or the labels in the gutter drift away from the
    /// lines they name, so a value that does not divide 60 is rounded UP to the next one
    /// that does (25 minutes becomes 30). Values are clamped to 1..60 minutes.
    /// </para>
    /// </summary>
    [Parameter] public TimeSpan? SlotDuration { get; set; }

    /// <summary>
    /// How far a drag, resize or drag-create snaps. Defaults to <see cref="SlotDuration"/>
    /// when that is set — dragging onto a line the grid does not draw is the kind of
    /// mismatch users read as a bug — and to 15 minutes otherwise, which is what this view
    /// snapped to before the grid was configurable.
    /// </summary>
    [Parameter] public TimeSpan? SnapDuration { get; set; }

    /// <summary>
    /// IANA zone the NOW-INDICATOR is read in. The grid itself stays wall-clock — the wrapper
    /// has already projected the events it hands down (see SchedulerTimeZoneProjection) — but
    /// the now line is computed in the browser from the real clock, so without this it would
    /// sit at the viewer's local time on a grid drawn for somewhere else.
    /// </summary>
    [Parameter] public string? NowTimeZoneId { get; set; }

    /// <summary>
    /// Whether a 7-day grid snaps to the configured week start. True (the default) is the Week
    /// view. False makes seven days mean "seven days from the anchor" — the rolling N-day
    /// window, which happens to collide with the Week view at exactly this one width.
    /// </summary>
    [Parameter] public bool AlignToWeek { get; set; } = true;

    [Parameter] public EventCallback<SchedulerEvent> OnEventClick { get; set; }
    [Parameter] public EventCallback<SchedulerDateRange> OnDateSelect { get; set; }
    [Parameter] public EventCallback OnRequestPrev { get; set; }
    [Parameter] public EventCallback OnRequestNext { get; set; }
    [Parameter] public Func<SchedulerEvent, string?>? ResolveEventColor { get; set; }
    [Parameter] public Func<SchedulerEvent, string?>? ResolveEventClassNames { get; set; }

    /// <summary>Allows events to be dragged (move) and edge-resized. Default true.</summary>
    [Parameter] public bool Editable { get; set; } = true;

    /// <summary>Allows drag-to-create on empty grid background. Default true.</summary>
    [Parameter] public bool Selectable { get; set; } = true;

    /// <summary>Shows the browser-local current-time indicator line (spec §2.2 — positioned and refreshed entirely client-side, never a server-computed value). Default true.</summary>
    [Parameter] public bool NowIndicator { get; set; } = true;

    /// <summary>
    /// Fail-closed validation predicate for a move/resize drop (spec §3.2), widened to a
    /// three-way reject/accept/accept-with-adjustment contract (mirrors ReUI's
    /// <c>onEventUpdate</c>) — see <see cref="SchedulerDropResult"/>. <c>null</c> (default)
    /// means no consumer opted in — JS is told via <c>hasCanDrop: false</c> so zero
    /// <see cref="ValidateDrop"/> interop calls happen per drag, not "always permit".
    /// </summary>
    [Parameter] public Func<SchedulerEvent, SchedulerScheduleDropContext, SchedulerDropResult>? CanDrop { get; set; }

    /// <summary>
    /// Shades non-business-hour slots and non-business days (spec's business-hours regression
    /// fix — the first-party views previously had no equivalent at all, unlike the FullCalendar
    /// wrapper's <c>BusinessHours</c> toggle). Default false (opt-in, matches the wrapper's own
    /// default). Grid interval and snap duration remain out of scope for this pass (still
    /// hardcoded — see the report).
    /// </summary>
    [Parameter] public bool BusinessHours { get; set; }

    /// <summary>Earliest business hour (inclusive) when <see cref="BusinessHours"/> is true. Default 09:00, unchanged from the wrapper this engine replaced.</summary>
    [Parameter] public TimeOnly BusinessHoursStart { get; set; } = new(9, 0);

    /// <summary>Latest business hour (exclusive) when <see cref="BusinessHours"/> is true. Default 17:00.</summary>
    [Parameter] public TimeOnly BusinessHoursEnd { get; set; } = new(17, 0);

    /// <summary>Which days of the week count as business days when <see cref="BusinessHours"/> is true. Default Mon–Fri, unchanged from the wrapper this engine replaced.</summary>
    [Parameter] public IReadOnlyList<DayOfWeek>? BusinessDays { get; set; }

    /// <summary>Raised after a move/resize drag commits (post-<see cref="CanDrop"/> validation, ghost already removed).</summary>
    [Parameter] public EventCallback<SchedulerEvent> OnEventChange { get; set; }

    [Parameter] public string? Class { get; set; }
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private DateTime[] _dayColumns = Array.Empty<DateTime>();
    /// <summary>Start of each grid row, in minutes from midnight.</summary>
    private int[] _slotStarts = Array.Empty<int>();
    /// <summary>Whole hours covered by the grid — the gutter labels, one per hour regardless of row size.</summary>
    private int[] _hourLabels = Array.Empty<int>();
    private int _slotMinutes = 60;
    private int _minMinute;
    private int _maxMinute = 1440;
    private List<TimedBlock>[] _timedByDay = Array.Empty<List<TimedBlock>>();
    private List<TimedBlock> _allDayInstances = new();
    private IReadOnlyList<AllDaySlot?>[] _allDayLaneSlots = Array.Empty<IReadOnlyList<AllDaySlot?>>();
    private int _focusedIndex;
    private ElementReference _scrollRef;
    private ElementReference _hostRef;
    private ElementReference[] _cellRefs = Array.Empty<ElementReference>();
    private ElementReference[] _dayColumnRefs = Array.Empty<ElementReference>();
    private ElementReference[] _registeredNowIndicatorRefs = Array.Empty<ElementReference>();
    private readonly Dictionary<string, ElementReference> _pillRefs = new(StringComparer.Ordinal);
    private DotNetObjectReference<SchedulerTimeGridView>? _selfRef;
    private bool _dragRegistered;
    private int _lastDragOptionsHash;
    // Nullable so a first-render hash that happens to equal a sentinel value can never
    // be mistaken for "already synced" — mirrors the drag-registration gate's own
    // `_dragRegistered && hash == _lastDragOptionsHash` short-circuit (see
    // SyncDragRegistrationAsync above), just expressed via nullability instead of a
    // separate bool since this sync has no other "have we ever registered" state to hang one off of.
    private int? _lastNowIndicatorHash;

    protected override void OnParametersSet()
    {
        _minMinute = (int)(SlotMinTime?.ToTimeSpan().TotalMinutes ?? 0);
        _maxMinute = (int)(SlotMaxTime?.ToTimeSpan().TotalMinutes ?? 1440);
        if (_maxMinute <= _minMinute) _maxMinute = _minMinute + 60;

        _slotMinutes = NormalizeSlotMinutes(SlotDuration);

        var hourStart = _minMinute / 60;
        var hourEnd = (int)Math.Ceiling(_maxMinute / 60.0);
        _hourLabels = Enumerable.Range(hourStart, Math.Max(1, hourEnd - hourStart)).ToArray();

        // Rows span whole hours even when SlotMinTime/SlotMaxTime fall mid-hour, exactly as
        // the hour grid did — the gutter is still one label per hour, so the body has to
        // start and end on the same boundaries or the two columns shear apart.
        var firstMinute = hourStart * 60;
        var lastMinute = Math.Max(firstMinute + _slotMinutes, hourEnd * 60);
        var slotCount = (lastMinute - firstMinute) / _slotMinutes;
        _slotStarts = Enumerable.Range(0, slotCount).Select(i => firstMinute + i * _slotMinutes).ToArray();

        var days = Math.Max(1, Days);
        if (days == 7 && AlignToWeek)
        {
            var weekStart = SchedulerDateMath.StartOfWeek(AnchorDate, FirstDayOfWeek);
            _dayColumns = Enumerable.Range(0, 7).Select(i => weekStart.AddDays(i)).ToArray();
        }
        else
        {
            _dayColumns = Enumerable.Range(0, days).Select(i => AnchorDate.Date.AddDays(i)).ToArray();
        }

        _cellRefs = new ElementReference[_slotStarts.Length * _dayColumns.Length];
        _dayColumnRefs = new ElementReference[_dayColumns.Length];
        if (_focusedIndex < 0 || _focusedIndex >= _cellRefs.Length) _focusedIndex = 0;

        BuildEventLayout();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        await SyncDragRegistrationAsync();
        await SyncNowIndicatorAsync();
    }

    private async Task SyncDragRegistrationAsync()
    {
        // Snap belongs in the hash: it is pushed to JS in the drag options, so a caller
        // changing SlotDuration/SnapDuration after first render has to re-register or the
        // grid would draw one interval while dragging at another.
        var hash = HashCode.Combine(Editable, Selectable, CanDrop is not null, EffectiveSnapMinutes());
        if (_dragRegistered && hash == _lastDragOptionsHash) return;
        _lastDragOptionsHash = hash;
        _selfRef ??= DotNetObjectReference.Create(this);
        try
        {
            await Interop.SchedulerViewsRegisterTimeGridDragAsync(_hostRef, _selfRef, BuildDragOptions());
            _dragRegistered = true;
        }
        catch (Microsoft.JSInterop.JSDisconnectedException) { }
    }

    private object BuildDragOptions()
    {
        const double pxPerMinute = 48.0 / 60.0;
        return new Dictionary<string, object?>
        {
            ["editable"] = Editable,
            // Gated on there being a listener, not just on the flag: JS drew a
            // drag-create ghost, the user released, and CommitCreate dropped it because
            // OnDateSelect had no delegate. Offering a gesture that cannot do anything
            // reads as a broken component, which is exactly how it was reported.
            ["selectable"] = Selectable && OnDateSelect.HasDelegate,
            ["allowResize"] = true,
            ["hasCanDrop"] = CanDrop is not null,
            ["pixelsPerMinute"] = pxPerMinute,
            ["snapMinutes"] = EffectiveSnapMinutes(),
            ["slotMinMinute"] = _minMinute,
        };
    }

    private async Task SyncNowIndicatorAsync()
    {
        var hash = HashCode.Combine(NowIndicator, _minMinute, NowTimeZoneId,
                                    string.Join(",", _dayColumns.Select(d => d.ToString("yyyyMMdd"))));
        if (hash == _lastNowIndicatorHash) return;
        _lastNowIndicatorHash = hash;

        foreach (var r in _registeredNowIndicatorRefs)
        {
            try { await Interop.SchedulerViewsUnregisterNowIndicatorAsync(r); }
            catch (Microsoft.JSInterop.JSDisconnectedException) { }
        }
        _registeredNowIndicatorRefs = Array.Empty<ElementReference>();

        if (!NowIndicator) return;

        // ONE line on the grid host, not one per day column. Two reasons:
        //
        // Appearance — a line inside a column can only ever be that column wide, so
        // "now" showed as a stub over today instead of a rule across the grid, which is
        // what every calendar draws and what it was reported as.
        //
        // Robustness — the per-column loop indexed _dayColumnRefs, an array rebuilt on
        // every parameter set. A ref that had not been bound yet reached JS as an object
        // with no appendChild and threw an unhandled render exception. The host ref is the
        // element the grid itself is bound to, so there is no unbound-index case left.
        var options = new Dictionary<string, object?>
        {
            ["pixelsPerMinute"] = PxPerMinute,
            ["slotMinMinute"] = _minMinute,
            ["days"] = _dayColumns.Select(d => d.ToString("yyyy-MM-dd")).ToArray(),
            ["timeZone"] = NowTimeZoneId,
        };
        try
        {
            await Interop.SchedulerViewsRegisterNowIndicatorAsync(_hostRef, options);
            _registeredNowIndicatorRefs = new[] { _hostRef };
        }
        catch (Microsoft.JSInterop.JSDisconnectedException) { }
    }

    private void BuildEventLayout()
    {
        _pillRefs.Clear();
        if (_dayColumns.Length == 0) { _timedByDay = Array.Empty<List<TimedBlock>>(); _allDayInstances = new(); _allDayLaneSlots = Array.Empty<IReadOnlyList<AllDaySlot?>>(); return; }

        var events = (Events ?? Enumerable.Empty<SchedulerEvent>()).ToList();
        var byId = new Dictionary<string, SchedulerEvent>(StringComparer.Ordinal);
        foreach (var ev in events)
            if (!string.IsNullOrEmpty(ev.Id)) byId[ev.Id] = ev;

        var rangeStart = _dayColumns[0];
        var rangeEnd = _dayColumns[^1].AddDays(1);
        var allInstances = SchedulerRecurrenceExpander.ExpandAll(events, rangeStart, rangeEnd)
            .Where(i => byId.ContainsKey(i.EventId))
            .ToList();

        _allDayInstances = allInstances
            .Where(i => byId[i.EventId].AllDay)
            .Select(i => new TimedBlock(i, byId[i.EventId], 0, 1))
            .ToList();
        BuildAllDayLanes();

        var timedByDay = new List<TimedBlock>[_dayColumns.Length];
        for (var d = 0; d < _dayColumns.Length; d++)
        {
            var day = _dayColumns[d];
            var dayInstances = allInstances
                .Where(i => !byId[i.EventId].AllDay && i.Start.Date == day.Date)
                .ToList();

            var packInput = dayInstances
                .Select(i => (Id: InstanceKey(i), StartMinute: (int)i.Start.TimeOfDay.TotalMinutes, EndMinute: Math.Max((int)i.Start.TimeOfDay.TotalMinutes + 1, (int)i.End.TimeOfDay.TotalMinutes)))
                .ToList();
            var packed = SchedulerTimeGridLayout.Pack(packInput);
            var packedById = packed.ToDictionary(p => p.Id, p => (p.Column, p.ColumnsInCluster), StringComparer.Ordinal);

            var blocks = new List<TimedBlock>();
            foreach (var inst in dayInstances)
            {
                var key = InstanceKey(inst);
                var (col, colCount) = packedById.TryGetValue(key, out var v) ? v : (0, 1);
                blocks.Add(new TimedBlock(inst, byId[inst.EventId], col, colCount));
            }
            timedByDay[d] = blocks;
        }
        _timedByDay = timedByDay;
    }

    /// <summary>
    /// Lane-packs the all-day strip via <see cref="SchedulerMonthLayout.PackRow"/> — the SAME
    /// kernel algorithm Month view already uses for its own row continuity (spec's "one engine"
    /// point) — instead of the previous per-day-column independent <c>.Where(...)</c> filter,
    /// whose stacking order silently shifted a multi-day all-day event's vertical position
    /// between day columns (the structural gap the audit found, not previously flagged
    /// anywhere: Month view's rows were lane-packed for continuity, the TimeGrid's own all-day
    /// strip was not).
    /// </summary>
    private void BuildAllDayLanes()
    {
        if (_allDayInstances.Count == 0 || _dayColumns.Length == 0)
        {
            _allDayLaneSlots = Array.Empty<IReadOnlyList<AllDaySlot?>>();
            return;
        }

        var rowStart = _dayColumns[0];
        var packInput = _allDayInstances
            .Select(b => (Id: InstanceKey(b.Instance), StartDate: b.Instance.Start, EndDate: b.Instance.End, AllDay: true))
            .ToList();
        var lanes = SchedulerMonthLayout.PackRow(rowStart, packInput);
        var maxLane = lanes.Count == 0 ? -1 : lanes.Values.Max();
        var laneCount = maxLane + 1;

        var perDay = new IReadOnlyList<AllDaySlot?>[_dayColumns.Length];
        for (var d = 0; d < _dayColumns.Length; d++)
        {
            var day = _dayColumns[d];
            var daySlots = new AllDaySlot?[laneCount];
            foreach (var block in _allDayInstances)
            {
                if (!TouchesDay(block.Instance.Start, block.Instance.End, true, day)) continue;
                var key = InstanceKey(block.Instance);
                if (!lanes.TryGetValue(key, out var lane) || lane >= laneCount) continue;

                var contL = day.Date > block.Instance.Start.Date;
                var contR = day.Date < LastTouchedDate(block.Instance.End, true, block.Instance.Start);
                daySlots[lane] = new AllDaySlot(block.Instance, block.Source, contL, contR, !contL);
            }
            perDay[d] = daySlots;
        }
        _allDayLaneSlots = perDay;
    }

    /// <summary>Whether the row starting <paramref name="startMinute"/> minutes into <paramref name="day"/> falls outside <see cref="BusinessHoursStart"/>/<see cref="BusinessHoursEnd"/>/<see cref="BusinessDays"/> when <see cref="BusinessHours"/> is enabled.</summary>
    private bool IsOffSlot(DateTime day, int startMinute)
    {
        if (!BusinessHours) return false;
        var businessDays = BusinessDays ?? DefaultBusinessDays;
        if (!businessDays.Contains(day.DayOfWeek)) return true;
        var slotStart = MinuteToTimeOnly(startMinute);
        return slotStart < BusinessHoursStart || slotStart >= BusinessHoursEnd;
    }

    private static readonly DayOfWeek[] DefaultBusinessDays =
        { DayOfWeek.Monday, DayOfWeek.Tuesday, DayOfWeek.Wednesday, DayOfWeek.Thursday, DayOfWeek.Friday };

    /// <summary>Hover-tooltip label for an event chip: title + time range (spec §3.4's promised "title, time range, resource" — resource omitted here since neither view resolves a resource DISPLAY NAME, only the raw <see cref="SchedulerEvent.ResourceId"/>; falls back to that id, labelled, when present).</summary>
    private static string TooltipLabel(SchedulerEvent ev, SchedulerEventInstance inst)
    {
        var time = ev.AllDay ? null : $"{inst.Start:t}–{inst.End:t}";
        var parts = new List<string> { ev.Title };
        if (time is not null) parts.Add(time);
        if (!string.IsNullOrEmpty(ev.ResourceId)) parts.Add(ev.ResourceId);
        return string.Join(" · ", parts);
    }

    private static DateTime LastTouchedDate(DateTime end, bool allDay, DateTime start)
    {
        if (!allDay && end.Date == start.Date) return start.Date;
        var last = end.TimeOfDay == TimeSpan.Zero ? end.Date.AddDays(-1) : end.Date;
        return last < start.Date ? start.Date : last;
    }

    private static bool TouchesDay(DateTime start, DateTime end, bool allDay, DateTime day)
    {
        if (!allDay && end.Date == start.Date) return day.Date == start.Date;
        var last = LastTouchedDate(end, allDay, start);
        return day.Date >= start.Date && day.Date <= last;
    }

    private static string InstanceKey(SchedulerEventInstance i) => $"{i.EventId}|{i.Start:O}";

    private static string FormatHour(int hour) => $"{hour % 24:D2}:00";

    private static TimeOnly MinuteToTimeOnly(int minute) => new((minute / 60) % 24, minute % 60);

    private static string FormatMinute(int minute) => $"{(minute / 60) % 24:D2}:{minute % 60:D2}";

    /// <summary>
    /// Row height in pixels. The 0.8px-per-minute scale is the same constant the drag and
    /// now-indicator maths use (48px per hour); deriving the height from it rather than a
    /// fixed class is what keeps a sub-hour grid aligned with the chips drawn on top of it.
    /// </summary>
    private string SlotCellStyle() =>
        string.Create(CultureInfo.InvariantCulture, $"height:{_slotMinutes * PxPerMinute:0.###}px;");

    /// <summary>
    /// Hour boundaries keep the full rule; lines inside an hour are drawn fainter, so a
    /// 15-minute grid still reads as hours at a glance instead of 96 identical stripes.
    /// </summary>
    private string SlotCellClasses(int startMinute)
    {
        // border/20, not a finer step: the opacity utilities are generated per literal, and
        // border-border/15 is not one the bundle carries — an ungenerated class silently
        // leaves border-b on its default colour, which drew the sub-hour lines DARKER than
        // the hour rules instead of fainter. Caught in the browser; the class name alone
        // looked right in the DOM.
        var border = startMinute % 60 == 0 ? "border-border/30" : "border-border/20";
        return $"border-b {border} cursor-crosshair focus-visible:outline focus-visible:outline-2 focus-visible:outline-ring focus-visible:-outline-offset-2";
    }

    /// <summary>
    /// Rounds UP to the next whole-minute divisor of 60 (see <see cref="SlotDuration"/>), so
    /// every configured grid tiles an hour exactly.
    /// </summary>
    private static int NormalizeSlotMinutes(TimeSpan? requested)
    {
        if (requested is not { } span) return 60;
        var minutes = (int)Math.Round(span.TotalMinutes);
        if (minutes <= 1) return 1;
        if (minutes >= 60) return 60;
        foreach (var divisor in SupportedSlotMinutes)
        {
            if (divisor >= minutes) return divisor;
        }
        return 60;
    }

    private static readonly int[] SupportedSlotMinutes = { 1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60 };

    private const double PxPerMinute = 48.0 / 60.0;

    /// <summary>Drag/resize/create granularity — see <see cref="SnapDuration"/> for why it follows the grid.</summary>
    private int EffectiveSnapMinutes()
    {
        if (SnapDuration is { } snap)
        {
            var minutes = (int)Math.Round(snap.TotalMinutes);
            return Math.Clamp(minutes, 1, 60);
        }
        return SlotDuration is null ? 15 : _slotMinutes;
    }

    private string GridAriaLabel() => Days == 1 ? L["Scheduler.Day"] : L["Scheduler.Week"];

    private string SlotAriaLabel(DateTime day, int startMinute) =>
        $"{day.ToString("D", CultureInfo.CurrentUICulture)}, {FormatMinute(startMinute)}";

    private static string PillAriaLabel(SchedulerEvent ev, SchedulerEventInstance inst) =>
        $"{ev.Title}, {inst.Start:t}–{inst.End:t}";

    private string AllDayPillClasses(AllDaySlot slot)
    {
        var classes = "block w-full text-left text-[11px] font-medium px-1.5 py-0.5 rounded truncate border-0 cursor-pointer";
        if (slot.ContL) classes += " rounded-l-none";
        if (slot.ContR) classes += " rounded-r-none";
        var extra = ResolveEventClassNames?.Invoke(slot.Source);
        if (!string.IsNullOrEmpty(extra)) classes += " " + extra;
        return classes;
    }

    private static string TimedPillClasses() =>
        "absolute rounded-md overflow-hidden text-left text-[11px] leading-tight px-1.5 py-0.5 border-l-4 cursor-pointer select-none";

    private string PillStyle(SchedulerEvent ev)
    {
        var color = ResolveEventColor?.Invoke(ev) ?? ev.Color ?? "var(--color-primary)";
        return $"background-color: color-mix(in oklab, {color} 18%, transparent); color: color-mix(in oklab, {color} 38%, var(--lumeo-event-fg-anchor));";
    }

    private string TimedPillStyle(TimedBlock block)
    {
        var color = ResolveEventColor?.Invoke(block.Source) ?? block.Source.Color ?? "var(--color-primary)";
        var startMinute = Math.Clamp((int)block.Instance.Start.TimeOfDay.TotalMinutes, _minMinute, _maxMinute);
        var rawEndMinute = (int)block.Instance.End.TimeOfDay.TotalMinutes;
        if (rawEndMinute <= startMinute) rawEndMinute = startMinute + 15;
        var endMinute = Math.Clamp(rawEndMinute, _minMinute, _maxMinute);
        const double pxPerMinute = 48.0 / 60.0;
        var top = (startMinute - _minMinute) * pxPerMinute;
        var height = Math.Max(16, (endMinute - startMinute) * pxPerMinute);
        var width = 100.0 / block.ColumnsInCluster;
        var left = block.Column * width;
        return $"top:{top.ToString(CultureInfo.InvariantCulture)}px; height:{height.ToString(CultureInfo.InvariantCulture)}px; left:calc({left.ToString(CultureInfo.InvariantCulture)}% + 2px); width:calc({width.ToString(CultureInfo.InvariantCulture)}% - 4px); background-color: color-mix(in oklab, {color} 18%, transparent); color: color-mix(in oklab, {color} 38%, var(--lumeo-event-fg-anchor)); border-left-color: {color};";
    }

    // ── Interaction ──────────────────────────────────────────────────────

    private async Task OnEventClickAsync(SchedulerEvent ev)
    {
        if (OnEventClick.HasDelegate) await OnEventClick.InvokeAsync(ev);
    }

    /// <summary>
    /// Takes the ROW INDEX, not the hour: <see cref="LinearIndex"/> indexes into
    /// <see cref="_slotStarts"/>, so passing a clock hour put the roving tabindex on the
    /// wrong cell whenever SlotMinTime moved the grid off midnight.
    /// </summary>
    private void OnSlotClickAsync(DateTime day, int slotIndex)
    {
        _focusedIndex = LinearIndex(Array.IndexOf(_dayColumns, day), slotIndex);
    }

    private async Task OnSlotDoubleClickAsync(DateTime day, int startMinute)
    {
        if (!OnDateSelect.HasDelegate) return;
        var start = day.Date.AddMinutes(startMinute);
        // 30 minutes stays the default so the out-of-the-box behaviour is unchanged; once a
        // caller has asked for a specific grid, the row they clicked is the obvious range.
        var length = SlotDuration is null ? 30 : _slotMinutes;
        await OnDateSelect.InvokeAsync(new SchedulerDateRange(start, start.AddMinutes(length), false));
    }

    private async Task OnPillKeyDownAsync(KeyboardEventArgs e, SchedulerEvent ev, int dayIndex, int hourIndex)
    {
        if (e.Key is "Enter" or " ")
        {
            await OnEventClickAsync(ev);
        }
        else if (e.Key == "Escape")
        {
            var idx = LinearIndex(dayIndex, hourIndex);
            _focusedIndex = idx;
            await FocusCellAsync(idx);
        }
    }

    private int LinearIndex(int dayIndex, int hourIndex) => hourIndex * _dayColumns.Length + dayIndex;

    /// <summary>The row <paramref name="instant"/> falls in — the LAST row that starts at or before it, since an instant rarely lands exactly on a boundary once rows are shorter than an hour.</summary>
    private int SlotIndexOf(DateTime instant)
    {
        var minute = (int)instant.TimeOfDay.TotalMinutes;
        var best = 0;
        for (var i = 0; i < _slotStarts.Length; i++)
        {
            if (_slotStarts[i] > minute) break;
            best = i;
        }
        return best;
    }

    /// <summary>Roving-tabindex 2-D grid navigation (spec §5.2's Week/Day column).</summary>
    private async Task OnGridKeyDownAsync(KeyboardEventArgs e, int dayIndex, int hourIndex)
    {
        var current = LinearIndex(dayIndex, hourIndex);
        _focusedIndex = current;
        int nextDay = dayIndex, nextHour = hourIndex;
        switch (e.Key)
        {
            case "ArrowRight": nextDay = Math.Min(_dayColumns.Length - 1, dayIndex + 1); break;
            case "ArrowLeft": nextDay = Math.Max(0, dayIndex - 1); break;
            case "ArrowDown": nextHour = Math.Min(_slotStarts.Length - 1, hourIndex + 1); break;
            case "ArrowUp": nextHour = Math.Max(0, hourIndex - 1); break;
            case "Home": nextHour = 0; break;
            case "End": nextHour = _slotStarts.Length - 1; break;
            case "PageUp":
                if (OnRequestPrev.HasDelegate) await OnRequestPrev.InvokeAsync();
                return;
            case "PageDown":
                if (OnRequestNext.HasDelegate) await OnRequestNext.InvokeAsync();
                return;
            case "Enter":
            case " ":
                await ActivateFocusedSlotAsync(dayIndex, hourIndex);
                return;
            default:
                return;
        }

        var next = LinearIndex(nextDay, nextHour);
        if (next != current)
        {
            _focusedIndex = next;
            await FocusCellAsync(next);
        }
    }

    private async Task ActivateFocusedSlotAsync(int dayIndex, int hourIndex)
    {
        var slotStart = _slotStarts[hourIndex];
        var slotEnd = slotStart + _slotMinutes;
        var block = _timedByDay.Length > dayIndex
            ? _timedByDay[dayIndex].FirstOrDefault(b =>
            {
                var m = (int)b.Instance.Start.TimeOfDay.TotalMinutes;
                return m >= slotStart && m < slotEnd;
            })
            : null;
        if (block is not null)
        {
            var key = InstanceKey(block.Instance);
            if (_pillRefs.TryGetValue(key, out var pillRef))
            {
                try { await pillRef.FocusAsync(); }
                catch (Microsoft.JSInterop.JSDisconnectedException) { }
            }
        }
        else
        {
            await OnSlotDoubleClickAsync(_dayColumns[dayIndex], slotStart);
        }
    }

    private async Task FocusCellAsync(int index)
    {
        try { await _cellRefs[index].FocusAsync(); }
        catch (Microsoft.JSInterop.JSDisconnectedException) { }
    }

    // ── Drag/resize/create (spec §3.1-§3.4) ────────────────────────────────
    // Ghost-only: JS never mutates the real chip (data-event-instance element) during a
    // drag — only a cloned ghost moves (scheduler-views.js's makeGhost). Fail-closed:
    // ValidateDrop is awaited by JS BEFORE CommitDrag/CommitCreate is ever invoked; any
    // rejected/thrown invocation resolves to `false` on the JS side (.catch(() => false)),
    // never `true`. See scheduler-views.js's own header comment for the full argument.

    /// <summary>
    /// [JSInvokable] fail-closed CanDrop check for a move/resize candidate. Returns
    /// <c>false</c> (never permits) for any input JS shouldn't have been able to produce
    /// (unknown instance key, malformed mode) — an unrecognized shape is not evidence of
    /// permission, only of something already gone wrong upstream. Only the
    /// <see cref="SchedulerDropResult.Accepted"/> half of the three-way verdict crosses the JS
    /// boundary here — the visual ghost only needs accept/reject;
    /// <see cref="SchedulerDropResult.Adjustment"/> is applied once, authoritatively, in
    /// <see cref="CommitDrag"/>.
    /// </summary>
    [JSInvokable]
    public bool ValidateDrop(string instanceKey, string mode, string? dayIso, int deltaMinutes)
    {
        if (CanDrop is null) return true;
        var parsed = ParseInstanceKey(instanceKey);
        if (parsed is not { } p) return false;
        var src = FindEvent(p.EventId);
        if (src is null) return false;
        var (newStart, newEnd, source) = ComputeCandidate(p.Start, src.End - src.Start, mode, dayIso, deltaMinutes);
        if (newStart is null || newEnd is null) return false;
        return CanDrop(src, new SchedulerScheduleDropContext(newStart.Value, newEnd.Value, source)).Accepted;
    }

    [JSInvokable]
    public async Task CommitDrag(string instanceKey, string mode, string? dayIso, int deltaMinutes)
    {
        var parsed = ParseInstanceKey(instanceKey);
        if (parsed is not { } p) return;
        var src = FindEvent(p.EventId);
        if (src is null) return;
        var (newStart, newEnd, source) = ComputeCandidate(p.Start, src.End - src.Start, mode, dayIso, deltaMinutes);
        if (newStart is null || newEnd is null || newStart == src.Start && newEnd == src.End) return;
        var finalStart = newStart.Value;
        var finalEnd = newEnd.Value;
        var finalAllDay = src.AllDay;

        // Re-validate at commit time — same reasoning as SchedulerMonthView.CommitDrag: this is
        // the only place a SchedulerDropResult.Adjustment can be applied (ValidateDrop only
        // surfaces Accepted over the JS boundary), and it closes the staleness gap where JS's
        // last cached ValidateDrop poll could otherwise be trusted without a final re-check.
        if (CanDrop is not null)
        {
            var ctx = new SchedulerScheduleDropContext(finalStart, finalEnd, source);
            var result = CanDrop(src, ctx);
            // See SchedulerMonthView's twin: the ordinary rejection is handled
            // in NotifyDropRejected, but the commit-time staleness rejection
            // lands HERE and would otherwise be silent. `source` already carries
            // the gesture kind, so a refused resize keeps its own wording.
            if (!result.Accepted)
            {
                var stale = source is SchedulerEventUpdateSource.ResizeStart or SchedulerEventUpdateSource.ResizeEnd;
                Announce(L[stale ? "Scheduler.Announce.ResizeRejected" : "Scheduler.Announce.MoveRejected", src.Title]);
                return;
            }
            if (result.Adjustment is { } adjustment)
            {
                finalStart = adjustment.Start ?? finalStart;
                finalEnd = adjustment.End ?? finalEnd;
                finalAllDay = adjustment.AllDay ?? finalAllDay;
            }
        }

        var updated = src with { Start = finalStart, End = finalEnd, AllDay = finalAllDay };
        // Announced from the COMMITTED values, after any CanDrop adjustment —
        // and with TIMES, not just the date: in a time grid the times are the
        // whole point of the gesture. Covers resize as well as move, which is
        // why the wording is "now <start> to <end>" rather than "moved to".
        // Gated on OnEventChange (Codex review of this PR, P2): with no handler
        // the gesture is ghost-only and the real block snaps back, so announcing
        // a reschedule would describe something that did not persist.
        // A CanDrop adjustment can snap the event back to exactly where it
        // started; the earlier no-op check ran against the PROPOSED values,
        // not these (Codex review of this PR, P2). Announcing a move for an
        // unchanged event states something that did not happen.
        if (updated.Start == src.Start && updated.End == src.End && updated.AllDay == src.AllDay) return;
        if (!OnEventChange.HasDelegate) return;
        // See SchedulerMonthView's twin: announce only once the handler
        // has completed, so a faulted persist cannot be heard as success.
        await OnEventChange.InvokeAsync(updated);
        Announce(L["Scheduler.Announce.EventRescheduled",
            src.Title, FormatAnnounceMoment(updated.Start), FormatAnnounceMoment(updated.End)]);
    }

    // ── Live-region announcements (ReUI parity) ──────────────────────────────
    // See SchedulerMonthView's own remarks — same house pattern (Carousel.razor),
    // same reason: these views shipped with no aria-live region at all.

    /// <summary>
    /// [JSInvokable] counterpart to <see cref="SchedulerMonthView.NotifyDropRejected"/> — see its
    /// remarks. <paramref name="mode"/> carries the gesture kind so a refused RESIZE is not
    /// announced as a refused move (Codex review of this PR, P2).
    /// </summary>
    [JSInvokable]
    public void NotifyDropRejected(string instanceKey, string? mode)
    {
        // Same instanceKey -> event resolution CommitDrag performs.
        var title = ParseInstanceKey(instanceKey) is { } p ? FindEvent(p.EventId)?.Title ?? string.Empty : string.Empty;
        var isResize = mode is not null && mode.StartsWith("resize", StringComparison.OrdinalIgnoreCase);
        Announce(L[isResize ? "Scheduler.Announce.ResizeRejected" : "Scheduler.Announce.MoveRejected", title]);
    }

    private string? _announcement;
    private int _announcementEpoch;

    /// <summary>
    /// See <see cref="SchedulerMonthView"/>'s twin: the region element stays
    /// MOUNTED and only its text changes, with a zero-width space alternating so
    /// a repeated identical message is still a text mutation.
    /// </summary>
    private string? AnnouncementText =>
        _announcement is null ? null : _announcementEpoch % 2 == 0 ? _announcement : _announcement + ZeroWidthSpace;

    /// <summary>
    /// U+200B. Named rather than written literally: an invisible character in
    /// source is unreadable and easy to delete by accident.
    /// </summary>
    private const string ZeroWidthSpace = "​";

    private void Announce(string message)
    {
        _announcementEpoch++;
        _announcement = message;
        StateHasChanged();
    }

    /// <summary>Date + time of day, spelled out — an announcement is heard without the grid for context.</summary>
    private static string FormatAnnounceMoment(DateTime value) =>
        value.ToString("f", CultureInfo.CurrentUICulture);

    [JSInvokable]
    public async Task CommitCreate(string dayIso, int startMinute, int endMinute)
    {
        if (!DateTime.TryParse(dayIso, CultureInfo.InvariantCulture, DateTimeStyles.None, out var day)) return;
        var start = day.Date.AddMinutes(startMinute);
        var end = day.Date.AddMinutes(Math.Max(startMinute + 1, endMinute));
        if (OnDateSelect.HasDelegate) await OnDateSelect.InvokeAsync(new SchedulerDateRange(start, end, false));
    }

    private SchedulerEvent? FindEvent(string id) =>
        (Events ?? Enumerable.Empty<SchedulerEvent>()).FirstOrDefault(e => e.Id == id);

    /// <summary>Splits an instance key on its LAST '|' — the ISO-O suffix never contains one, so an event Id that itself contains '|' still round-trips correctly.</summary>
    private static (string EventId, DateTime Start)? ParseInstanceKey(string key)
    {
        var idx = key.LastIndexOf('|');
        if (idx < 0) return null;
        var eventId = key[..idx];
        if (!DateTime.TryParseExact(key[(idx + 1)..], "O", CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out var start)) return null;
        return (eventId, start);
    }

    private static (DateTime? Start, DateTime? End, SchedulerEventUpdateSource Source) ComputeCandidate(
        DateTime instanceStart, TimeSpan duration, string mode, string? dayIso, int deltaMinutes)
    {
        var instanceEnd = instanceStart + duration;
        switch (mode)
        {
            case "move":
                if (string.IsNullOrEmpty(dayIso) || !DateTime.TryParse(dayIso, CultureInfo.InvariantCulture, DateTimeStyles.None, out var day))
                    return (null, null, SchedulerEventUpdateSource.Move);
                var newStart = day.Date + instanceStart.TimeOfDay + TimeSpan.FromMinutes(deltaMinutes);
                return (newStart, newStart + duration, SchedulerEventUpdateSource.Move);
            case "resize-start":
                var rsStart = instanceStart + TimeSpan.FromMinutes(deltaMinutes);
                if (rsStart >= instanceEnd) rsStart = instanceEnd.AddMinutes(-15);
                return (rsStart, instanceEnd, SchedulerEventUpdateSource.ResizeStart);
            case "resize-end":
                var reEnd = instanceEnd + TimeSpan.FromMinutes(deltaMinutes);
                if (reEnd <= instanceStart) reEnd = instanceStart.AddMinutes(15);
                return (instanceStart, reEnd, SchedulerEventUpdateSource.ResizeEnd);
            default:
                return (null, null, SchedulerEventUpdateSource.Move);
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_dragRegistered)
        {
            try { await Interop.SchedulerViewsUnregisterTimeGridDragAsync(_hostRef); }
            catch (Microsoft.JSInterop.JSDisconnectedException) { }
        }
        foreach (var r in _registeredNowIndicatorRefs)
        {
            try { await Interop.SchedulerViewsUnregisterNowIndicatorAsync(r); }
            catch (Microsoft.JSInterop.JSDisconnectedException) { }
        }
        _selfRef?.Dispose();
    }

    private sealed record TimedBlock(SchedulerEventInstance Instance, SchedulerEvent Source, int Column, int ColumnsInCluster);

    /// <summary>An all-day strip lane slot — mirrors <c>SchedulerMonthView.PillSlot</c>'s continuation-styling shape (spec's "one engine" point, §1's structural fix).</summary>
    private sealed record AllDaySlot(SchedulerEventInstance Instance, SchedulerEvent Source, bool ContL, bool ContR, bool ShowTitle);
}

using System.Globalization;

namespace Lumeo;

/// <summary>
/// Projects events into a display time zone and back again.
///
/// <para>
/// Every Scheduler view is deliberately a WALL-CLOCK renderer: it reads calendar fields off
/// the <see cref="DateTime"/> values it is handed and never consults
/// <see cref="TimeZoneInfo"/> (see SchedulerDateMath's own remarks for why). That property is
/// what makes the grid immune to DST and to the difference between a CI box and a dev
/// machine, and it is not given up here. Instead the wrapper converts events ON THE WAY IN
/// and converts edits back ON THE WAY OUT, so the views keep rendering exactly one thing —
/// wall-clock — and only the question of WHICH wall clock moves.
/// </para>
///
/// <para>
/// Which values move is decided by <see cref="DateTime.Kind"/>, because that is the only
/// thing that says whether a value denotes a real instant:
/// </para>
/// <list type="bullet">
/// <item><description>
/// <see cref="DateTimeKind.Unspecified"/> — a naive wall-clock reading, already expressed in
/// whatever zone the caller means. Left ALONE. This is what virtually every existing caller
/// passes, which is why switching a time zone on cannot silently move their events.
/// </description></item>
/// <item><description>
/// <see cref="DateTimeKind.Utc"/> and <see cref="DateTimeKind.Local"/> — real instants, so
/// they are converted into the display zone for rendering and converted back to the same
/// kind when an edit is handed to the caller.
/// </description></item>
/// </list>
///
/// <para>
/// All-day events are dates, not instants, and are never converted: shifting one by a few
/// hours moves it onto a different DAY, which is the one thing an all-day event must never
/// do.
/// </para>
/// </summary>
public static class SchedulerTimeZoneProjection
{
    /// <summary>
    /// The zone for an IANA id (also accepts a Windows id), or <c>null</c> when unset or
    /// unknown. Never throws: an id the host has no data for degrades to "no projection",
    /// which renders the caller's own wall-clock values rather than failing the render.
    /// </summary>
    public static TimeZoneInfo? Resolve(string? timeZoneId)
    {
        if (string.IsNullOrWhiteSpace(timeZoneId)) return null;
        try
        {
            return TimeZoneInfo.FindSystemTimeZoneById(timeZoneId);
        }
        catch (TimeZoneNotFoundException) { return null; }
        catch (InvalidTimeZoneException) { return null; }
    }

    /// <summary>Wall-clock reading of <paramref name="value"/> in <paramref name="zone"/>. See the class remarks for which kinds move.</summary>
    public static DateTime ToDisplay(DateTime value, TimeZoneInfo? zone)
    {
        if (zone is null) return value;
        return value.Kind switch
        {
            DateTimeKind.Utc => DateTime.SpecifyKind(TimeZoneInfo.ConvertTimeFromUtc(value, zone), DateTimeKind.Unspecified),
            DateTimeKind.Local => DateTime.SpecifyKind(TimeZoneInfo.ConvertTime(value, TimeZoneInfo.Local, zone), DateTimeKind.Unspecified),
            _ => value,
        };
    }

    /// <summary>
    /// The inverse of <see cref="ToDisplay(DateTime, TimeZoneInfo?)"/>: turns a wall-clock reading in
    /// <paramref name="zone"/> back into a value of <paramref name="originalKind"/>, so an
    /// edit reaches the caller in the same frame of reference they handed us.
    /// </summary>
    public static DateTime FromDisplay(DateTime displayValue, DateTimeKind originalKind, TimeZoneInfo? zone)
    {
        if (zone is null || originalKind == DateTimeKind.Unspecified) return DateTime.SpecifyKind(displayValue, originalKind);

        var naive = DateTime.SpecifyKind(displayValue, DateTimeKind.Unspecified);

        // A drag can land on a wall-clock reading that does not exist — the hour a spring-forward
        // transition skips. Converting it throws, which would turn a legal-looking drop into an
        // unhandled exception on the circuit, so the reading is nudged forward past the gap
        // instead. Ambiguous readings (the repeated autumn hour) do not throw; .NET resolves
        // them to standard time, and this deliberately does not second-guess that.
        if (zone.IsInvalidTime(naive)) naive = naive.Add(zone.GetAdjustmentRules().Length > 0 ? TimeSpan.FromHours(1) : TimeSpan.Zero);

        return originalKind == DateTimeKind.Utc
            ? DateTime.SpecifyKind(TimeZoneInfo.ConvertTimeToUtc(naive, zone), DateTimeKind.Utc)
            : DateTime.SpecifyKind(TimeZoneInfo.ConvertTime(naive, zone, TimeZoneInfo.Local), DateTimeKind.Local);
    }

    /// <summary>An event with its instants read in <paramref name="zone"/>. All-day events are returned untouched.</summary>
    public static SchedulerEvent ToDisplay(SchedulerEvent ev, TimeZoneInfo? zone)
    {
        if (zone is null || ev.AllDay) return ev;
        return ev with
        {
            Start = ToDisplay(ev.Start, zone),
            End = ToDisplay(ev.End, zone),
        };
    }

    /// <summary>
    /// An edited event converted back into <paramref name="original"/>'s frame of reference.
    /// The kinds come from the ORIGINAL because the views hand back naive wall-clock values —
    /// they have no idea what frame the caller was using.
    /// </summary>
    public static SchedulerEvent FromDisplay(SchedulerEvent edited, SchedulerEvent? original, TimeZoneInfo? zone)
    {
        if (zone is null || edited.AllDay) return edited;
        var startKind = original?.Start.Kind ?? DateTimeKind.Unspecified;
        var endKind = original?.End.Kind ?? DateTimeKind.Unspecified;
        return edited with
        {
            Start = FromDisplay(edited.Start, startKind, zone),
            End = FromDisplay(edited.End, endKind, zone),
        };
    }

    /// <summary>Today's date in <paramref name="zone"/>, falling back to the host's own today when unset.</summary>
    public static DateTime TodayIn(TimeZoneInfo? zone) =>
        zone is null
            ? DateTime.Today
            : TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow, zone).Date;

    /// <summary>
    /// The zone id handed to JS, which resolves it with <c>Intl</c> rather than .NET. Only
    /// IANA ids travel: <c>Intl</c> does not understand Windows ids, and sending one across
    /// would silently leave the now-indicator on the browser's own clock.
    /// </summary>
    public static string? JsZoneId(TimeZoneInfo? zone)
    {
        if (zone is null) return null;
        if (TimeZoneInfo.TryConvertWindowsIdToIanaId(zone.Id, out var iana)) return iana;
        return zone.Id.Contains('/', StringComparison.Ordinal)
            ? zone.Id
            : zone.Id.Equals("UTC", StringComparison.OrdinalIgnoreCase)
                ? "UTC"
                : null;
    }

    /// <summary>Culture-invariant IANA-ish rendering used in diagnostics and aria text.</summary>
    internal static string Describe(TimeZoneInfo? zone) =>
        zone is null ? string.Empty : zone.Id.ToString(CultureInfo.InvariantCulture);
}

using System.Globalization;

namespace Lumeo;

/// <summary>The granularity of one column on a <see cref="SchedulerTimelineView"/>'s horizontal axis.</summary>
public enum SchedulerTimelineUnit
{
    /// <summary>One column per day.</summary>
    Day,

    /// <summary>One column per week, starting on the view's configured first day of week.</summary>
    Week,

    /// <summary>One column per calendar month.</summary>
    Month,
}

/// <summary>
/// Date-to-pixel arithmetic for the resource timeline's horizontal axis.
///
/// <para>
/// Deliberately its own implementation rather than a reference to Lumeo.Gantt, whose
/// <c>GanttScale</c> solves the same problem: that type is internal to the Gantt package, and
/// making <c>Lumeo.Scheduler</c> depend on <c>Lumeo.Gantt</c> would put a whole Gantt into every
/// project that only wanted a calendar — the opposite of why the FullCalendar dependency was
/// removed. The subset needed here is small enough that duplicating it costs less than the
/// coupling would.
/// </para>
///
/// <para>
/// Everything below is calendar-field arithmetic on wall-clock values, never
/// <see cref="TimeZoneInfo"/> and never elapsed-time subtraction across a day boundary, so a
/// DST transition cannot shift a column — the same discipline the grid views follow.
/// </para>
/// </summary>
public static class SchedulerTimelineScale
{
    /// <summary>Default column width in pixels for each unit — wide enough to read a date label.</summary>
    public static int DefaultColumnWidth(SchedulerTimelineUnit unit) => unit switch
    {
        SchedulerTimelineUnit.Day => 96,
        SchedulerTimelineUnit.Week => 120,
        SchedulerTimelineUnit.Month => 140,
        _ => 96,
    };

    /// <summary>
    /// The first instant of the column containing <paramref name="date"/>. Columns must start on
    /// a real boundary or every bar on the axis is offset by the remainder.
    /// </summary>
    public static DateTime AlignOrigin(SchedulerTimelineUnit unit, DateTime date, DayOfWeek firstDayOfWeek) => unit switch
    {
        SchedulerTimelineUnit.Day => date.Date,
        SchedulerTimelineUnit.Week => StartOfWeek(date, firstDayOfWeek),
        SchedulerTimelineUnit.Month => new DateTime(date.Year, date.Month, 1),
        _ => date.Date,
    };

    /// <summary>The column start dates covering <paramref name="count"/> units from <paramref name="origin"/>.</summary>
    public static IReadOnlyList<DateTime> BuildColumns(SchedulerTimelineUnit unit, DateTime origin, int count)
    {
        var n = Math.Max(1, count);
        var cols = new List<DateTime>(n);
        cols.Add(origin);
        for (var i = 1; i < n; i++)
        {
            // Truncate, do not saturate (Codex review round 6). Clamping each step to
            // DateTime.MaxValue produced a run of identical final columns: the same date drawn
            // over and over, headers and rules overflowing a track measured for one column.
            // An axis that reaches the end of the calendar is simply shorter.
            //
            // Stepping from the PREVIOUS column rather than recomputing from the origin is what
            // makes the saturation visible: Advance returns DateTime.MaxValue itself, which is
            // a later instant on the same final day and so compares as genuine progress.
            var next = Advance(unit, cols[^1], 1);
            if (next == DateTime.MaxValue || next <= cols[^1]) break;
            cols.Add(next);
        }
        return cols;
    }

    /// <summary>
    /// Horizontal offset in pixels of <paramref name="date"/> from <paramref name="origin"/>.
    /// Fractional within a column, so a bar starting mid-day lands mid-column rather than
    /// snapping to the boundary.
    /// </summary>
    public static double DateToPixel(SchedulerTimelineUnit unit, DateTime origin, DateTime date, int columnWidth) => unit switch
    {
        SchedulerTimelineUnit.Day => (date - origin).TotalDays * columnWidth,
        SchedulerTimelineUnit.Week => (date - origin).TotalDays / 7.0 * columnWidth,

        // Months are unequal, so a day fraction has to be taken against the LENGTH OF THE
        // MONTH the date falls in — a flat /30 would drift by up to a day inside February and
        // by half a day in every 31-day month.
        SchedulerTimelineUnit.Month => MonthsBetween(origin, date) * columnWidth
                                        + (date.Day - 1 + date.TimeOfDay.TotalDays)
                                          / DateTime.DaysInMonth(date.Year, date.Month) * columnWidth,
        _ => 0,
    };

    /// <summary>Total width in pixels of the columns actually drawn from <paramref name="origin"/>.</summary>
    public static double TotalWidth(SchedulerTimelineUnit unit, DateTime origin, int count, int columnWidth)
    {
        // Whole columns, because that is what the headers and grid rules paint. Measuring the
        // pixel position of the exclusive end instead disagreed with them wherever that end was
        // clamped: a week running off the calendar is about 5/7 of a column wide by date, while
        // its header still occupies a full one, and the surplus showed as phantom days past the
        // end of the range (Codex review round 7). Dropping the column is not the answer — the
        // first one is the caller's own anchor, and removing it would leave nothing on screen.
        return BuildColumns(unit, origin, count).Count * (double)columnWidth;
    }

    /// <summary>
    /// Moves <paramref name="from"/> forward by <paramref name="units"/> columns, stopping at
    /// <see cref="DateTime.MaxValue"/> rather than throwing. A caller may legitimately anchor a
    /// timeline in the last representable column — <c>RangeStart</c> is public — and the
    /// exclusive end of that column does not exist (Codex review of PR #424).
    /// </summary>
    internal static DateTime Advance(SchedulerTimelineUnit unit, DateTime from, int units)
    {
        if (units <= 0) return from;

        switch (unit)
        {
            case SchedulerTimelineUnit.Week:
            {
                var days = (long)units * 7;
                return days > (DateTime.MaxValue - from).TotalDays ? DateTime.MaxValue : from.AddDays(days);
            }
            case SchedulerTimelineUnit.Month:
            {
                var monthsLeft = (DateTime.MaxValue.Year - from.Year) * 12L + (DateTime.MaxValue.Month - from.Month);
                return units > monthsLeft ? DateTime.MaxValue : from.AddMonths(units);
            }
            default:
                return units > (DateTime.MaxValue - from).TotalDays ? DateTime.MaxValue : from.AddDays(units);
        }
    }

    /// <summary>
    /// Moves <paramref name="from"/> BACKWARD by <paramref name="units"/> columns, stopping at
    /// <see cref="DateTime.MinValue"/>. The toolbar pages an axis that may already sit on the
    /// lower boundary, and a view that renders must not be crashable by its own Previous button
    /// (Codex review of PR #424).
    /// </summary>
    internal static DateTime Retreat(SchedulerTimelineUnit unit, DateTime from, int units)
    {
        if (units <= 0) return from;

        switch (unit)
        {
            case SchedulerTimelineUnit.Week:
            {
                var days = (long)units * 7;
                return days > (from - DateTime.MinValue).TotalDays ? DateTime.MinValue : from.AddDays(-days);
            }
            case SchedulerTimelineUnit.Month:
            {
                var monthsBack = (from.Year - DateTime.MinValue.Year) * 12L + (from.Month - DateTime.MinValue.Month);
                return units > monthsBack ? DateTime.MinValue : from.AddMonths(-units);
            }
            default:
                return units > (from - DateTime.MinValue).TotalDays ? DateTime.MinValue : from.AddDays(-units);
        }
    }

    /// <summary>Steps <paramref name="from"/> by <paramref name="units"/> columns in either
    /// direction, clamped to the representable range.</summary>
    internal static DateTime Step(SchedulerTimelineUnit unit, DateTime from, int units) =>
        units >= 0 ? Advance(unit, from, units) : Retreat(unit, from, -units);

    /// <summary>Header label for a column, at the granularity that column represents.</summary>
    public static string ColumnLabel(SchedulerTimelineUnit unit, DateTime column, CultureInfo culture) => unit switch
    {
        SchedulerTimelineUnit.Day => column.ToString("ddd d", culture),
        SchedulerTimelineUnit.Week => column.ToString("MMM d", culture),
        SchedulerTimelineUnit.Month => column.ToString("MMM yyyy", culture),
        _ => column.ToString("d", culture),
    };

    /// <summary>Whether <paramref name="column"/> is the column containing <paramref name="today"/>.</summary>
    public static bool IsCurrentColumn(SchedulerTimelineUnit unit, DateTime column, DateTime today) => unit switch
    {
        SchedulerTimelineUnit.Day => column.Date == today.Date,
        SchedulerTimelineUnit.Week => today.Date >= column.Date
                                      && today.Date < Advance(SchedulerTimelineUnit.Week, column.Date, 1),
        SchedulerTimelineUnit.Month => column.Year == today.Year && column.Month == today.Month,
        _ => false,
    };

    private static int MonthsBetween(DateTime origin, DateTime date) =>
        (date.Year - origin.Year) * 12 + (date.Month - origin.Month);

    private static DateTime StartOfWeek(DateTime date, DayOfWeek firstDayOfWeek)
    {
        var diff = (7 + (date.DayOfWeek - firstDayOfWeek)) % 7;
        // A caller may anchor at DateTime.MinValue, and with a week start other than the one
        // that date happens to fall on, this step goes below the representable range
        // (Codex review round 5).
        return diff > (date.Date - DateTime.MinValue).TotalDays ? DateTime.MinValue : date.Date.AddDays(-diff);
    }
}

@namespace Lumeo
@using System.Globalization
@using Lumeo.SchedulerKernel
@inject Lumeo.Services.Localization.ILumeoLocalizer L

@* Resource timeline: rows are resources, the time axis runs HORIZONTALLY across days,
   weeks or months. Distinct from SchedulerResourceView, which lays out a single day with
   one column per resource and a vertical clock — that one answers "who is where today",
   this one answers "how is this resource booked over the coming stretch". *@
<div class="@($"flex flex-col w-full rounded-md border border-border/60 overflow-hidden {Class}".Trim())"
     @attributes="AdditionalAttributes">

    @* Deliberately NOT role="grid" (Codex review, P2). The gutter and the scrolling track
       are separate subtrees and the bars are absolutely positioned, so row/columnheader roles
       here were orphaned — assistive tech could not associate a date header with a resource
       row. A labelled group plus a list of resources, with each bar naming its own resource
       and time range, states only what the markup can actually deliver. *@
    <div class="flex" role="group" aria-label="@L["Scheduler.Resources"]">

        @* Resource gutter — outside the horizontal scroller so it stays put while the axis
           scrolls. Its rows must match the timeline's row heights exactly or the two halves
           shear apart, which is why both read the same RowStyle. *@
        <div class="flex-none w-40 border-e border-border/60" role="list">
            <div class="h-9 border-b border-border/60 bg-muted/30 px-2 flex items-center text-[11px] font-medium text-muted-foreground">
                @L["Scheduler.Resources"]
            </div>
            @for (var r = 0; r < _rows.Count; r++)
            {
                var row = _rows[r];
                <div role="listitem"
                     class="border-b border-border/60 px-2 flex items-center gap-1.5 text-xs"
                     style="@RowStyle(r)"
                     data-timeline-resource="@row.Resource.Id">
                    <span class="inline-block h-2.5 w-2.5 flex-none rounded-[calc(var(--radius)*2)]"
                          style="background: @(row.Resource.Color ?? "var(--color-primary)")" aria-hidden="true"></span>
                    <span class="truncate">@row.Resource.Title</span>
                </div>
            }
        </div>

        @* dir on the SCROLLER, not only on the track inside it (Codex review round 2, P2):
           an RTL document gives this overflow container an RTL scroll origin, so a timeline
           wider than its viewport opened at the far end of the range with RangeStart off
           screen — even with the track's own geometry already pinned LTR. *@
        <div class="flex-1 min-w-0 overflow-x-auto" dir="ltr">
            @* direction:ltr pins the time axis (Codex review, P1). The header row is
               flex, so under RTL it puts the first date on the right while the bars,
               rules and today marker keep positioning from the physical left — the
               bookings would sit under the wrong dates. The labels inside stay
               localised; only the axis direction is fixed. *@
            <div class="relative" style="@TrackStyle()" dir="ltr">

                @* Axis header *@
                <div class="flex h-9 border-b border-border/60 bg-muted/30" aria-hidden="true">
                    @foreach (var col in _columns)
                    {
                        <div class="@ColumnHeaderClasses(col)"
                             style="@ColumnStyle()"
                             data-timeline-column="@col.ToString("yyyy-MM-dd")">
                            @SchedulerTimelineScale.ColumnLabel(Unit, col, CultureInfo.CurrentUICulture)
                        </div>
                    }
                </div>

                @for (var r = 0; r < _rows.Count; r++)
                {
                    var row = _rows[r];
                    <div class="relative border-b border-border/60" style="@RowStyle(r)"
                         data-timeline-row="@row.Resource.Id">

                        @* Column rules, drawn behind the bars so a booking can cross them. *@
                        @foreach (var col in _columns)
                        {
                            <div class="@GridLineClasses(col)"
                                 style="@ColumnRuleStyle(col)"
                                 aria-hidden="true"></div>
                        }

                        @foreach (var bar in row.Bars)
                        {
                            @* A Url turns the bar into a link, exactly as SchedulerEvent.Url
                               documents and the other views behave — a URL-backed booking was
                               inert here when no callback was registered (Codex review round 7). *@
                            @if (!string.IsNullOrEmpty(bar.Source.Url))
                            {
                                <a href="@bar.Source.Url"
                                   class="@BarClasses(bar)"
                                   style="@BarStyle(bar, row.Resource)"
                                   data-event-id="@bar.Source.Id"
                                   data-timeline-bar="@bar.Source.Id"
                                   aria-label="@BarAriaLabel(row.Resource, bar)">
                                    <span class="truncate">@bar.Source.Title</span>
                                </a>
                            }
                            else
                            {
                                <button type="button"
                                        class="@BarClasses(bar)"
                                        style="@BarStyle(bar, row.Resource)"
                                        data-event-id="@bar.Source.Id"
                                        data-timeline-bar="@bar.Source.Id"
                                        aria-label="@BarAriaLabel(row.Resource, bar)"
                                        @onclick="() => OnEventClickAsync(bar.Source)">
                                    <span class="truncate">@bar.Source.Title</span>
                                </button>
                            }
                        }
                    </div>
                }

                @if (_todayLeft is not null)
                {
                    @* One rule down the whole track, not a stub per row — the same shape the
                       time grid's now-indicator settled on after it was reported as spanning
                       only a single column. *@
                    <div data-timeline-today
                         class="pointer-events-none absolute top-9 bottom-0 border-l-2 border-destructive"
                         style="@TodayStyle()"
                         aria-hidden="true"></div>
                }
            </div>
        </div>
    </div>
</div>

