            .Where(e => e.ResourceId is not null && shown.Contains(e.ResourceId))
            .Select(e => (src: e,
                          instances: SchedulerRecurrenceExpander.ExpandAll(
                              new[] { e }, expandFrom, axisEnd)))
            .ToList();

        foreach (var res in resources)
        {
            var mine = expanded
                // No IsNullOrEmpty guard (Codex review, P2): a blank resource id is
                // legitimate — RebuildResourceLookup and the resource view both honour it —
                // so the ordinal comparison alone decides.
                .Where(p => string.Equals(p.src.ResourceId, res.Id, StringComparison.Ordinal))
                .SelectMany(p => p.instances.Select(i => (p.src, i)))
                // A zero-length booking sitting exactly on the axis origin is kept
                // (Codex review, P2): a strict End > start dropped a midnight marker on the
                // first visible column, contradicting this view's own support for them.
                .Where(t => t.i.Start < axisEnd
                            && (t.i.End > axisStart || (t.i.End == t.i.Start && t.i.Start >= axisStart)))
                .OrderBy(t => t.i.Start)
                .ToList();

            // Lanes are packed by RENDERED GEOMETRY, not by time (Codex review, P2). Every bar
            // is floored to a visible minimum width, and at day scale an hour is four pixels —
            // so two back-to-back hour bookings share a lane by the clock while overlapping on
            // screen, the later button covering the earlier one.
            var laneRight = new List<double>();
            var bars = new List<Bar>(mine.Count);
            foreach (var (src, i) in mine)
            {
                var from = i.Start < axisStart ? axisStart : i.Start;
                var to = i.End > axisEnd ? axisEnd : i.End;
                var left = SchedulerTimelineScale.DateToPixel(Unit, _origin, from, ColumnWidthPx);
                var width = Math.Max(MinBarWidthPx, SchedulerTimelineScale.DateToPixel(Unit, _origin, to, ColumnWidthPx) - left);

                // The minimum width must not push the bar past the end of the track. A short
                // booking finishing at midnight on the last column was floored to six pixels and
                // rendered into a day that does not exist, stretching the scrollable area beyond
                // the advertised range (Codex review round 7). Shifted back rather than clipped,
                // so the hit target survives.
                if (left + width > _totalWidth) left = Math.Max(0, _totalWidth - width);
                var right = left + width;

                var lane = laneRight.FindIndex(r => r <= left);
                if (lane < 0) { laneRight.Add(right); lane = laneRight.Count - 1; }
                else laneRight[lane] = right;

                bars.Add(new Bar(src, i, left, width, lane));
            }

            _rows.Add(new Row(res, bars, Math.Max(1, laneRight.Count)));
        }
    }

    // Derived from the columns actually built, not from the requested count: near the end of the
    // calendar the axis truncates, and an end computed from the request would claim range the
    // view never draws (Codex review rounds 4 and 6).
    private DateTime AxisEnd() =>
        _columns.Count > 0 ? SchedulerTimelineScale.Advance(Unit, _columns[^1], 1) : _origin;

    private string TrackStyle() =>
        string.Create(Inv, $"width:{_totalWidth.ToString("0.##", Inv)}px;");

    private string ColumnStyle() =>
        string.Create(Inv, $"width:{ColumnWidthPx}px; flex:0 0 {ColumnWidthPx}px;");

    private string ColumnRuleStyle(DateTime column)
    {
        var left = SchedulerTimelineScale.DateToPixel(Unit, _origin, column, ColumnWidthPx);
        return string.Create(Inv, $"position:absolute; top:0; bottom:0; left:{left.ToString("0.##", Inv)}px; width:{ColumnWidthPx}px;");
    }

    private string TodayStyle() =>
        string.Create(Inv, $"left:{(_todayLeft ?? 0).ToString("0.##", Inv)}px;");

    private string RowStyle(int index)
    {
        var lanes = _rows[index].Lanes;
        return string.Create(Inv, $"height:{lanes * LaneHeightPx + 8}px;");
    }

    private string ColumnHeaderClasses(DateTime col)
    {
        var classes = "flex items-center justify-center border-e border-border/40 text-[11px] text-muted-foreground";
        if (SchedulerTimelineScale.IsCurrentColumn(Unit, col, Today ?? DateTime.Today))
            classes += " font-semibold text-foreground";
        return classes;
    }

    private string GridLineClasses(DateTime col)
    {
        var classes = "border-e border-border/25";
        if (SchedulerTimelineScale.IsCurrentColumn(Unit, col, Today ?? DateTime.Today)) classes += " bg-accent/20";
        return classes;
    }

    private string BarClasses(Bar bar)
    {
        var classes = "absolute flex items-center rounded px-1.5 text-[11px] font-medium leading-tight text-left border-0 cursor-pointer select-none overflow-hidden";
        var extra = ResolveEventClassNames?.Invoke(bar.Source);
        if (!string.IsNullOrEmpty(extra)) classes += " " + extra;
        return classes;
    }

    private string BarStyle(Bar bar, SchedulerResource res)
    {
        // callback, then the event's own colour, then the RESOURCE's — the order
        // SchedulerResourceView uses. Without the last step a direct caller saw a gutter full
        // of distinct colours and a timeline entirely in the primary one (Codex review, P2).
        var color = ResolveEventColor?.Invoke(bar.Source) ?? bar.Source.Color ?? res.Color ?? "var(--color-primary)";
        var top = 4 + bar.Lane * LaneHeightPx;
        var style = string.Create(Inv,
            $"left:{bar.Left.ToString("0.##", Inv)}px; width:{bar.Width.ToString("0.##", Inv)}px; top:{top}px; height:{LaneHeightPx - 4}px; ");

        // The same contrast treatment as every other view: the colour as an 18% tint, the text
        // mixed toward an anchor that flips with the theme. The raw colour stays on the left
        // border, which is the bar's colour identity.
        style += $"background-color: color-mix(in oklab, {color} 18%, transparent);";
        style += $" color: color-mix(in oklab, {color} 38%, var(--lumeo-event-fg-anchor));";
        style += $" border-left: 2px solid {color};";
        return style;
    }

    // The END matters (Codex review, P2): a bar's width conveys duration visually, and without
    // it two bookings starting at the same time are indistinguishable to a screen reader.
    private string BarAriaLabel(SchedulerResource res, Bar bar) =>
        $"{bar.Source.Title}, {res.Title}, {bar.Instance.Start.ToString("g", CultureInfo.CurrentUICulture)}"
        + $" – {bar.Instance.End.ToString("g", CultureInfo.CurrentUICulture)}";

    private async Task OnEventClickAsync(SchedulerEvent ev)
    {
        if (OnEventClick.HasDelegate) await OnEventClick.InvokeAsync(ev);
    }
}

using System.Globalization;
using Lumeo.Services.Localization;

namespace Lumeo.SchedulerKernel;

/// <summary>
/// View-title formatting for the Scheduler toolbar, routed through <see cref="ILumeoLocalizer"/>
/// for every string that needs one, and through an explicit <see cref="CultureInfo"/> for plain
/// date formatting. Spec §1.1/§4.6/§7.1.
///
/// <para>
/// <b>Why an explicit <see cref="CultureInfo"/> parameter, not ambient
/// <see cref="CultureInfo.CurrentCulture"/>:</b> Blazor Server shares threads/requests across
/// possibly-different-locale users; reading the ambient culture deep inside a pure kernel
/// function makes the result depend on whatever the CALLING request happened to set, which is
/// exactly the kind of implicit, hard-to-test dependency the rest of this kernel avoids (compare
/// <c>SchedulerDateMath</c>/<c>SchedulerRecurrenceExpander</c>'s explicit "never touch ambient
/// state" TZ/DST design). Callers (the eventual Razor view layer) resolve the request's culture
/// once and pass it down explicitly.
/// </para>
///
/// <para>
/// <b>The <c>Scheduler.WeekOf</c> bug this exists to not repeat (spec §4.6):</b> the
/// FullCalendar-era <c>Scheduler.razor</c>'s title logic calls
/// <c>string.Format(L["Scheduler.WeekOf"], ...)</c> — a MANUAL <c>string.Format</c> wrapped
/// around the localizer's plain (no-args) indexer. If the underlying localized string has no
/// <c>{0}</c> placeholder (as en/de's currently do, a data bug being fixed on a sibling branch,
/// out of this class's scope), <c>string.Format</c> silently ignores the extra argument and the
/// date is dropped with no error. This class instead always goes through
/// <see cref="ILumeoLocalizer"/>'s OWN args-aware indexer (<c>this[key, args]</c>) rather than a
/// second, hand-rolled <c>string.Format</c> call site — not because that indexer is immune to the
/// SAME missing-placeholder data bug (it isn't; a missing <c>{0}</c> in the string data will
/// still drop the argument no matter which call shape reaches it), but because routing every
/// localized, argument-carrying title through the ONE sanctioned formatting entry point is what
/// keeps this class itself from re-introducing a DIFFERENT variant of the same class of bug later
/// (e.g. forgetting to pass the date argument at all). <c>SchedulerTitleFormatterTests</c> proves
/// this by asserting the formatted Week title actually CONTAINS the date substring, using a
/// locally-constructed test localizer whose <c>Scheduler.WeekOf</c> value has a <c>{0}</c>
/// (i.e. what the sibling branch's fix will make en/de look like) — a test that only checked
/// "does not throw" would have passed on the actual WeekOf bug.
/// </para>
/// </summary>
internal static class SchedulerTitleFormatter
{
    /// <summary>
    /// Formats the toolbar title for <paramref name="view"/> anchored at <paramref name="date"/>.
    /// </summary>
    /// <param name="view">Which view's title convention to use.</param>
    /// <param name="date">The view's anchor date (e.g. the currently-focused day/week/month).</param>
    /// <param name="firstDayOfWeek">Used only by <see cref="SchedulerView.Week"/> to resolve the week's start via <see cref="SchedulerDateMath.StartOfWeek"/>.</param>
    /// <param name="localizer">Source of localized strings (only <c>Scheduler.WeekOf</c> is looked up today).</param>
    /// <param name="culture">Culture used for plain date/month/weekday formatting.</param>
    internal static string Format(SchedulerView view, DateTime date, DayOfWeek firstDayOfWeek, ILumeoLocalizer localizer, CultureInfo culture) => view switch
    {
        SchedulerView.Month => date.ToString("MMMM yyyy", culture),
        SchedulerView.Week => localizer["Scheduler.WeekOf", SchedulerDateMath.StartOfWeek(date, firstDayOfWeek).ToString("MMM d, yyyy", culture)],
        SchedulerView.Day => date.ToString("dddd, MMM d, yyyy", culture),
        SchedulerView.List => date.ToString("MMMM yyyy", culture),
        _ => date.ToString("MMMM yyyy", culture),
    };
}

@namespace Lumeo
@inject Lumeo.Services.Localization.ILumeoLocalizer L

@* Prev/Next/Today + view switcher, extracted from the FullCalendar-era Scheduler.razor
   (spec §1.1/§1.2) so the first-party view engine and any future consumer can share one
   toolbar instance instead of duplicating the markup. Purely presentational — all state
   (current view, current title) is owned by the caller. *@
<div class="@($"flex flex-wrap items-center justify-between gap-2 {Class}".Trim())" @attributes="AdditionalAttributes">
    <div class="flex items-center gap-1">
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Sm" OnClick="OnPrev" aria-label="@L["Scheduler.Previous"]">
            <SvgGlyph Svg="@(LumeoIcons.ChevronLeft)" class="h-4 w-4" />
        </Button>
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Sm" OnClick="OnToday">@L["Scheduler.Today"]</Button>
        <Button Variant="Button.ButtonVariant.Outline" Size="Button.ButtonSize.Sm" OnClick="OnNext" aria-label="@L["Scheduler.Next"]">
            <SvgGlyph Svg="@(LumeoIcons.ChevronRight)" class="h-4 w-4" />
        </Button>
    </div>
    <div class="flex-1 text-center text-sm font-medium text-foreground truncate px-2">
        @Title
    </div>
    <ToggleGroup Type="ToggleGroup.ToggleGroupType.Single"
                 Variant="ToggleGroup.ToggleGroupVariant.Outline"
                 Size="Lumeo.Size.Sm"
                 Value="@CurrentView.ToString()"
                 ValueChanged="OnViewValueChangedAsync">
        <ToggleGroupItem Value="@nameof(SchedulerView.Month)">@L["Scheduler.Month"]</ToggleGroupItem>
        <ToggleGroupItem Value="@nameof(SchedulerView.Week)">@L["Scheduler.Week"]</ToggleGroupItem>
        <ToggleGroupItem Value="@nameof(SchedulerView.Day)">@L["Scheduler.Day"]</ToggleGroupItem>
        <ToggleGroupItem Value="@nameof(SchedulerView.List)">@L["Scheduler.List"]</ToggleGroupItem>
    </ToggleGroup>
</div>

@code {
    /// <summary>The view currently shown by the caller. Drives the pressed state of the view switcher.</summary>
    [Parameter] public SchedulerView CurrentView { get; set; }

    /// <summary>Raised when the user picks a different view from the switcher.</summary>
    [Parameter] public EventCallback<SchedulerView> CurrentViewChanged { get; set; }

    /// <summary>The formatted title shown between the nav buttons and the view switcher (<c>SchedulerTitleFormatter.Format</c>'s output).</summary>
    [Parameter] public string Title { get; set; } = "";

    /// <summary>Raised when the "previous" nav button is clicked.</summary>
    [Parameter] public EventCallback OnPrev { get; set; }

    /// <summary>Raised when the "next" nav button is clicked.</summary>
    [Parameter] public EventCallback OnNext { get; set; }

    /// <summary>Raised when the "today" button is clicked.</summary>
    [Parameter] public EventCallback OnToday { get; set; }

    /// <summary>Additional CSS classes merged onto the root row.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Additional HTML attributes captured and forwarded to the root row.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private async Task OnViewValueChangedAsync(string? v)
    {
        if (string.IsNullOrEmpty(v) || !Enum.TryParse<SchedulerView>(v, out var parsed) || parsed == CurrentView) return;
        if (CurrentViewChanged.HasDelegate) await CurrentViewChanged.InvokeAsync(parsed);
    }
}

namespace Lumeo;

/// <summary>
/// A calendar/scheduler event — the data contract every Scheduler view renders from.
/// </summary>
/// <param name="Id">Stable identifier used to reconcile edits back into the caller's collection.</param>
/// <param name="Title">The label rendered on the event chip.</param>
/// <param name="Start">Start timestamp (inclusive).</param>
/// <param name="End">End timestamp (exclusive: an event ending 10:00 does not occupy the 10:00 slot).</param>
/// <param name="AllDay">When true the event is rendered in the all-day lane.</param>
/// <param name="Color">CSS color or variable reference, e.g. "var(--color-primary)".</param>
/// <param name="Url">Optional link opened on click instead of firing OnEventClick.</param>
/// <param name="ExtendedProps">Arbitrary app-level metadata round-tripped through the JS layer.</param>
/// <param name="DaysOfWeek">
/// For recurring events: the days of the week on which the event repeats.
/// Uses FullCalendar's free simple recurrence model (no premium rrule plugin required).
/// e.g. [DayOfWeek.Monday, DayOfWeek.Wednesday, DayOfWeek.Friday].
/// When set, <see cref="Start"/> and <see cref="End"/> provide the start/end times
/// (time-of-day part only) and <see cref="RecurrenceEnd"/> bounds the recurrence.
/// </param>
/// <param name="RecurrenceEnd">
/// Optional end date for a recurring event. The event will not appear after this date.
/// Only meaningful when <see cref="DaysOfWeek"/> is set.
/// </param>
/// <param name="ExceptionDates">
/// Dates on which a recurring event should be skipped (one-off exclusions).
/// Only meaningful when <see cref="DaysOfWeek"/> is set.
/// </param>
/// <param name="ResourceId">
/// Optional resource identifier. When a <c>Resources</c> list is provided on the
/// <see cref="Scheduler"/> component, events are color-coded by their resource and
/// a resource legend is rendered above the calendar.
/// </param>
/// <param name="ClassNames">
/// Extra CSS class names to apply to the event chip, as produced by the
/// <c>EventClassNames</c> callback on the Scheduler component (or set directly here).
/// </param>
public record SchedulerEvent(
    string Id,
    string Title,
    DateTime Start,
    DateTime End,
    bool AllDay = false,
    string? Color = null,
    string? Url = null,
    Dictionary<string, object>? ExtendedProps = null,
    IReadOnlyList<DayOfWeek>? DaysOfWeek = null,
    DateTime? RecurrenceEnd = null,
    IReadOnlyList<DateTime>? ExceptionDates = null,
    string? ResourceId = null,
    string? ClassNames = null
)
{
    // Trim safety: this record is deserialized from JS (JsOnEventClick/JsOnEventChange
    // [JSInvokable] parameters). JSRuntime's reflection-based serializer must never bind
    // the positional ctor — the trimmer strips its parameter names
    // ("ConstructorContainsNullParameterNames", crashes the component under a trimmed
    // publish). With this parameterless ctor STJ uses property-based (de)serialization
    // instead. Do not remove.
    public SchedulerEvent() : this("", "", default, default) { }

    /// <summary>
    /// The <see cref="SchedulerCalendar.Id"/> this event belongs to, or null when it belongs to
    /// none. Null and the empty string are DIFFERENT: a blank id matches a calendar declared with
    /// one, while null matches no calendar at all and is therefore never hidden by a visibility
    /// toggle — the same distinction <see cref="ResourceId"/> draws.
    /// </summary>
    /// <remarks>
    /// A body property rather than a positional parameter, for the reason spelled out on
    /// <see cref="Recurrence"/> below: appending to the primary constructor changes the
    /// compiler-synthesized Deconstruct/constructor signature that callers may already depend on.
    /// </remarks>
    public string? CalendarId { get; init; }

    /// <summary>
    /// Optional structured recurrence rule (wave-1 RRULE subset: <c>FREQ=DAILY|WEEKLY|MONTHLY</c>,
    /// <c>INTERVAL</c>, <c>COUNT</c>, <c>UNTIL</c>, <c>BYDAY</c>). When set, this takes precedence
    /// over the legacy <see cref="DaysOfWeek"/>/<see cref="RecurrenceEnd"/> pair — both express the
    /// same underlying recurrence engine (<c>SchedulerRecurrenceExpander</c> translates
    /// <see cref="DaysOfWeek"/>+<see cref="RecurrenceEnd"/> into the equivalent
    /// <see cref="SchedulerRecurrenceRule"/> at its own boundary when <see cref="Recurrence"/> is
    /// unset), so setting both is redundant rather than contradictory — but is still flagged via a
    /// debug-build assertion (not a thrown exception, matching this repo's "warn, don't crash the
    /// render" posture) since it usually indicates the caller meant to pick one.
    /// <see cref="ExceptionDates"/> continues to double as this rule's <c>EXDATE</c> list.
    /// </summary>
    /// <remarks>
    /// Deliberately declared as a body property (<c>{ get; init; }</c>), NOT appended to the
    /// primary constructor's positional parameter list, even though the parameter-list shape is
    /// how earlier design notes for this feature sketched it. Appending it positionally would
    /// change the compiler-synthesized <c>Deconstruct</c>/constructor signature that
    /// <c>PublicAPI.Shipped.txt</c> already pins for this shipped record — CONTRIBUTING.md's
    /// "Never delete or change the signature of a shipped public member directly" rule — forcing
    /// an unnecessary <c>[Obsolete]</c> deprecation cycle for a purely-additive feature. A body
    /// property adds a new getter/init member without touching anything already shipped: every
    /// existing call site (positional or named) keeps compiling and behaving identically, and
    /// object-initializer / <c>with</c>-expression syntax (<c>ev with { Recurrence = rule }</c>)
    /// already reads/writes it like any other property. The ONE synthesized record member this
    /// does NOT flow into is <c>Deconstruct</c> — that method (and the primary constructor's own
    /// signature) is generated strictly from the primary constructor's parameter list, which is
    /// exactly what stays byte-for-byte unchanged here (verified: adding this property produced
    /// zero new/changed <c>PublicAPI.*.txt</c> entries for either). <c>Equals</c>/
    /// <c>GetHashCode</c>/<c>ToString</c>, by contrast, DO already pick it up automatically —
    /// per the C# record spec, the compiler-synthesized versions of those three compare/print
    /// every instance field the record declares, which includes this auto-property's backing
    /// field, not only the primary constructor's positional ones. So two events differing only
    /// in <see cref="Recurrence"/> are correctly NOT equal and hash differently, with no extra
    /// work needed here — see <c>SchedulerEventRecurrencePropertyTests</c> for the test that
    /// pins this down rather than assuming it. (This built-in record equality is a different
    /// mechanism from <c>Scheduler.razor</c>'s own hand-rolled <c>ComputeEventsHash</c>, which
    /// remains out of this task's scope — see the wave-1a task report.)
    /// </remarks>
    public SchedulerRecurrenceRule? Recurrence { get; init; }
}

/// <summary>
/// A named resource (person, room, equipment) used by the Scheduler for
/// color-coding events. Does not require the FullCalendar Premium resource plugin.
/// </summary>
/// <param name="Id">Identifier matched against <see cref="SchedulerEvent.ResourceId"/>.</param>
/// <param name="Title">Display name shown in the resource legend.</param>
/// <param name="Color">
/// CSS color applied to events belonging to this resource when the event itself
/// does not supply its own <see cref="SchedulerEvent.Color"/>.
/// </param>
public record SchedulerResource(string Id, string Title, string? Color = null);

/// <summary>
/// One named calendar an event can belong to — "Team", "Personal", a room's booking feed.
///
/// <para>
/// Distinct from <see cref="SchedulerResource"/> on purpose, because they answer different
/// questions. A RESOURCE is who or what an event consumes, and the resource views lay one out
/// per lane; a CALENDAR is which feed an event came from, and it decides whether the event is
/// shown at all. An event can have both: Alice's booking (resource) from the Team calendar.
/// </para>
/// </summary>
/// <param name="Id">Matches <see cref="SchedulerEvent.CalendarId"/>. A blank id is legitimate
/// and means the same as any other id — it is NOT "no calendar".</param>
/// <param name="Name">Shown on the visibility chip.</param>
/// <param name="Color">Colour for this calendar's events, used when neither the event nor its
/// resource supplies one.</param>
/// <param name="Visible">Initial visibility. The user's own toggling is component state from
/// then on, so re-rendering with the same list does not undo it.</param>
public record SchedulerCalendar(string Id, string Name, string? Color = null, bool Visible = true);

/// <summary>How several visible calendars share the space.</summary>
public enum SchedulerPaneMode
{
    /// <summary>All visible calendars in ONE view, drawn over each other. The default, and what
    /// the component did before calendars existed.</summary>
    Overlay,

    /// <summary>One view per visible calendar, side by side. Answers "what does each look like on
    /// its own" — the question overlaying cannot.</summary>
    SideBySide,
}

/// <summary>
/// A date range produced when the user drag-selects in the calendar.
/// </summary>
public record SchedulerDateRange(DateTime Start, DateTime End, bool AllDay)
{
    // Trim safety: this record is deserialized from JS (JsOnDateSelect [JSInvokable]
    // parameter). See SchedulerEvent's parameterless ctor above. Do not remove.
    public SchedulerDateRange() : this(default, default, false) { }
}


/// <summary>
/// Built-in views exposed by the Lumeo scheduler, each rendered by a first-party
/// Blazor view component — no third-party calendar library is involved.
/// </summary>
public enum SchedulerView
{
    Month,
    Week,
    Day,
    List,

    /// <summary>
    /// One column per entry in <c>Scheduler.Resources</c>, for a single day. Requires
    /// <c>Resources</c> to be non-empty; without it the view falls back to <see cref="Day"/>.
    /// </summary>
    Resource,

    /// <summary>
    /// A rolling window of <c>Scheduler.VisibleDays</c> days starting at the current date —
    /// ReUI's "N-day" view. Unlike <see cref="Week"/> it does not align to a week start, so
    /// "the next three days" stays the next three days as you page through it. Set
    /// <c>Scheduler.VisibleDays</c> to choose the width.
    /// </summary>
    MultiDay,

    /// <summary>
    /// One ROW per entry in <c>Scheduler.Resources</c> with the time axis running
    /// horizontally across days, weeks or months — a resource timeline.
    /// <para>
    /// Not a variant of <see cref="Resource"/>: that lays out a single day with a column per
    /// resource and a vertical clock ("who is where today"), while this answers "how is this
    /// resource booked over the coming stretch". Requires <c>Resources</c>; without it the
    /// view falls back to <see cref="Day"/>. Added last so the existing values keep their
    /// numeric identity.
    /// </para>
    /// </summary>
    Timeline,
}
